@app.post("/master/notice/{notice_id}/update")
async def master_notice_update(notice_id: int, request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    title = data.get("title", "").strip()
    content = data.get("content", "").strip()
    is_active = bool(data.get("is_active", True))
    is_popup = bool(data.get("is_popup", False))
    popup_end_date = data.get("popup_end_date") or None

    if not title or not content:
        return JSONResponse(status_code=400, content={"detail": "제목과 내용을 입력하세요."})

    conn = get_conn()
    conn.execute(
        "UPDATE notice SET title=?, content=?, is_active=?, is_popup=?, popup_end_date=?, updated_at=NOW() WHERE id=?",
        (title, content, is_active, is_popup, popup_end_date, notice_id)
    )
    conn.commit()
    return JSONResponse(content={"status": "ok"})


@app.post("/master/notice/{notice_id}/delete")
async def master_notice_delete(notice_id: int, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    conn = get_conn()
    conn.execute("DELETE FROM notice_read_log WHERE notice_id=?", (notice_id,))
    conn.execute("DELETE FROM notice_popup_dismiss WHERE notice_id=?", (notice_id,))
    conn.execute("DELETE FROM notice WHERE id=?", (notice_id,))
    conn.commit()
    return JSONResponse(content={"status": "ok"})


