@app.post("/login")
async def login_submit(request: Request, login_id: str = Form(...), password: str = Form(...)):
    account = authenticate(login_id, password)
    if not account:
        return HTMLResponse(content="""
        <html><head><meta charset="utf-8"></head>
        <body style="font-family:sans-serif;text-align:center;padding-top:80px;">
          <h3>❌ 아이디 또는 비밀번호가 틀렸습니다.</h3>
          <a href="/login">다시 시도</a>
        </body></html>""", status_code=401)
    device_info = request.headers.get("user-agent", "")[:255]
    client_ip = request.client.host if request.client else ""
    token = create_session(account["login_id"], account["role"], account["branch_code"], device_info, client_ip, account.get("branch_type"))
    resp = RedirectResponse(url="/", status_code=303)
    resp.set_cookie(key="session_token", value=token, max_age=7 * 24 * 3600, httponly=True)
    return resp


@app.get("/logout")
async def logout(session_token: str = Cookie(default=None)):
    if session_token:
        delete_session(session_token)
    resp = RedirectResponse(url="/login", status_code=303)
    resp.delete_cookie("session_token")
    return resp


@app.get("/auto-login/{token}")
async def auto_login(token: str):
    info = get_auto_login_info(token)
    if not info:
        return HTMLResponse(content="<h3>❌ 유효하지 않은 자동로그인 링크입니다.</h3>", status_code=404)
    session_token = create_session(info["login_id"], "branch", info["branch_code"])
    resp = RedirectResponse(url="/", status_code=303)
    resp.set_cookie(key="session_token", value=session_token, max_age=7 * 24 * 3600, httponly=True)
    return resp

def send_teams_notification_to_url(webhook_url: str, title: str, message: str, link_url: str = "", link_text: str = "", sent_by: str = "", device_info: str = "", target_label: str = "custom", file_url: str = "", file_name: str = ""):
    """webhook_url을 직접 지정해서 발송 (자유 채널용). teams_send_log에도 기록."""
    import httpx
    body_blocks = [
        {"type": "TextBlock", "text": title, "weight": "Bolder", "size": "Medium", "wrap": True},
        {"type": "TextBlock", "text": message, "wrap": True}
    ]
    actions = []
    if link_url:
        actions.append({"type": "Action.OpenUrl", "title": link_text or "바로가기", "url": link_url})
    if file_url:
        actions.append({"type": "Action.OpenUrl", "title": "📎 " + (file_name or "파일 다운로드"), "url": file_url})
    if actions:
        body_blocks.append({"type": "ActionSet", "actions": actions})
    payload = {
        "type": "message",
        "attachments": [{
            "contentType": "application/vnd.microsoft.card.adaptive",
            "contentUrl": None,
            "content": {
                "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
                "type": "AdaptiveCard", "version": "1.4", "body": body_blocks
            }
        }]
    }
    success, detail = False, ""
    try:
        with httpx.Client(timeout=10) as client:
            resp = client.post(webhook_url, json=payload)
            if resp.status_code >= 300:
                detail = f"status={resp.status_code} body={resp.text[:300]}"
            else:
                detail, success = "성공", True
    except Exception as e:
        detail = f"exception={str(e)[:300]}"

    conn = get_conn()
    conn.execute(
        "INSERT INTO teams_send_log (branch_code, title, message, success, detail, sent_by, device_info) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (target_label, title, message, success, detail, sent_by, device_info)
    )
    conn.commit()
    conn.close()
    return success, detail

def send_teams_notification(branch_code: str, title: str, message: str, link_url: str = "", link_text: str = "", sent_by: str = "", device_info: str = "", file_url: str = "", file_name: str = ""):
    """지정된 branch_code(또는 'master')의 Teams 웹훅으로 알림 발송 (Adaptive Card 형식, 링크 지원).
    웹훅 미등록 시 조용히 무시. 모든 시도를 teams_send_log에 기록.
    반환값: (성공여부: bool, 상세정보: str)"""
    import httpx
    conn = get_conn()
    row = conn.execute(
        "SELECT webhook_url FROM teams_webhook WHERE branch_code=?", (branch_code,)
    ).fetchone()

    if not row or not row["webhook_url"]:
        conn.execute(
            "INSERT INTO teams_send_log (branch_code, title, message, success, detail, sent_by, device_info) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (branch_code, title, message, False, "웹훅 미등록", sent_by, device_info)
        )
        conn.commit()
        conn.close()
        return False, "웹훅 미등록"

    body_blocks = [
        {"type": "TextBlock", "text": title, "weight": "Bolder", "size": "Medium", "wrap": True},
        {"type": "TextBlock", "text": message, "wrap": True}
    ]
    actions = []
    if link_url:
        actions.append({"type": "Action.OpenUrl", "title": link_text or "바로가기", "url": link_url})
    if file_url:
        actions.append({"type": "Action.OpenUrl", "title": "📎 " + (file_name or "파일 다운로드"), "url": file_url})
    if actions:
        body_blocks.append({"type": "ActionSet", "actions": actions})

    payload = {
        "type": "message",
        "attachments": [
            {
                "contentType": "application/vnd.microsoft.card.adaptive",
                "contentUrl": None,
                "content": {
                    "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
                    "type": "AdaptiveCard",
                    "version": "1.4",
                    "body": body_blocks
                }
            }
        ]
    }

    success = False
    detail = ""
    try:
        with httpx.Client(timeout=10) as client:
            resp = client.post(row["webhook_url"], json=payload)
            if resp.status_code >= 300:
                detail = f"status={resp.status_code} body={resp.text[:300]}"
                success = False
            else:
                detail = "성공"
                success = True
    except Exception as e:
        detail = f"exception={str(e)[:300]}"
        success = False

    conn.execute(
        "INSERT INTO teams_send_log (branch_code, title, message, success, detail, sent_by, device_info) VALUES (?, ?, ?, ?, ?, ?, ?)",
        (branch_code, title, message, success, detail, sent_by, device_info)
    )
    conn.commit()
    conn.close()
    return success, detail

    payload = {
        "@type": "MessageCard",
        "@context": "http://schema.org/extensions",
        "themeColor": color,
        "title": title,
        "text": message
    }

    try:
        with httpx.Client(timeout=10) as client:
            resp = client.post(row["webhook_url"], json=payload)
            return resp.status_code < 300
    except Exception:
        return False

# ── RAW 목 데이터 (추후 MSSQL 교체) ─────────────────────

def fetch_raw_inventory() -> List[Dict[str, Any]]:
    """RAW 재고 — master 소스 우선, 없으면 branch 소스 사용"""
    conn = get_conn()
    rows = conn.execute("SELECT * FROM raw_inventory ORDER BY source DESC").fetchall()
    conn.close()
    merged = {}
    for r in rows:
        key = f"{r['branch_code']}|{r['item_code']}"
        if key not in merged:
            merged[key] = dict(r)
    return list(merged.values())

# ── 재고 마감 (3단계 중 2: 저장/마감 — 마감 가능 기간은 해당 일자 + 익일) ──────────

def _stock_closing_editable_dates():
    """KST 기준 오늘 날짜와 저장/마감 가능한 날짜 목록 (오늘, 어제 — 11/5 마감은 11/5~6에 가능)"""
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz
    today = _dt.now(_tz(_td(hours=9))).date()
    return today, [today, today - _td(days=1)]


def _stock_closing_live_items(target_branch: str, sel_date, mismatch_only: bool = False) -> list:
    """선택 날짜(KST 00~24시)의 QR 입·출고 스캔 합계 + QR 재고 + 유비플러스 재고. QR DB(inventory) 등록 상품만.
    재고 값은 해당 날짜의 가장 늦은 슬롯(24→22→21) 스냅샷을 쓰고, 스냅샷이 없으면 현재 값을 쓴다.
    mismatch_only=True이면 스냅샷(없으면 현재값) 시점에 QR≠유비플러스인 품목만 반환."""
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz
    kst = _tz(_td(hours=9))
    start_kst = _dt(sel_date.year, sel_date.month, sel_date.day, tzinfo=kst)
    end_kst = start_kst + _td(days=1)
    start_utc = start_kst.astimezone(_tz.utc).strftime("%Y-%m-%dT%H:%M:%S")
    end_utc = end_kst.astimezone(_tz.utc).strftime("%Y-%m-%dT%H:%M:%S")
    snap_date = sel_date.strftime("%Y-%m-%d")

    conn = get_conn()
    params = [start_utc, end_utc]
    branch_cond = ""
    if target_branch:
        branch_cond = " AND branch_code=?"
        params.append(target_branch)
    scan_rows = conn.execute(
        "SELECT branch_code, item_code, COUNT(*) AS cnt FROM scan_log "
        "WHERE scan_type IN ('OUT','IN') AND scanned_at >= ? AND scanned_at < ?"
        + branch_cond + " GROUP BY branch_code, item_code",
        tuple(params)
    ).fetchall()
    if target_branch:
        inv_rows = conn.execute(
            "SELECT branch_code, item_code, item_name, quantity FROM inventory WHERE branch_code=?",
            (target_branch,)
        ).fetchall()
        snap_rows = conn.execute(
            "SELECT slot, branch_code, item_code, qr_qty, ups_qty FROM stock_daily_snapshot "
            "WHERE snap_date=? AND branch_code=?",
            (snap_date, target_branch)
        ).fetchall()
    else:
        inv_rows = conn.execute(
            "SELECT branch_code, item_code, item_name, quantity FROM inventory"
        ).fetchall()
        snap_rows = conn.execute(
            "SELECT slot, branch_code, item_code, qr_qty, ups_qty FROM stock_daily_snapshot "
            "WHERE snap_date=?",
            (snap_date,)
        ).fetchall()
    conn.close()

    inv_map = {
        f"{r['branch_code']}|{r['item_code']}": {"name": r["item_name"], "qty": r["quantity"]}
        for r in inv_rows
    }
    raw_map = {f"{r['branch_code']}|{r['item_code']}": r["quantity"] for r in fetch_raw_inventory()}

    # 지점별로 해당 날짜에서 가장 늦은 슬롯(24 > 22 > 21)의 스냅샷만 사용
    slot_rank = {"21": 1, "22": 2, "24": 3}
    best_rank = {}
    for s in snap_rows:
        rk = slot_rank.get(str(s["slot"]), 0)
        if rk > best_rank.get(s["branch_code"], 0):
            best_rank[s["branch_code"]] = rk
    snap_map = {}
    for s in snap_rows:
        if slot_rank.get(str(s["slot"]), 0) == best_rank.get(s["branch_code"]):
            snap_map[f"{s['branch_code']}|{s['item_code']}"] = s

    def _basis_label(s):
        slot = str(s["slot"])
        if slot == "24":
            return "스냅샷 " + (sel_date + _td(days=1)).strftime("%m/%d") + " 00:15"
        return "스냅샷 " + sel_date.strftime("%m/%d") + " " + slot + ":15"

    scan_cnt = {f"{r['branch_code']}|{r['item_code']}": r["cnt"] for r in scan_rows}

    if mismatch_only:
        # 스냅샷 작성 시점(없으면 현재값)의 QR 재고 ≠ 유비플러스 재고 품목만 선정
        items = []
        for key in set(inv_map) | set(snap_map):
            if key not in inv_map:
                continue
            snap = snap_map.get(key)
            if snap is not None:
                qr_val = snap["qr_qty"]
                ups_val = snap["ups_qty"]
                basis = "snap"
                basis_label = _basis_label(snap)
            else:
                qr_val = inv_map[key]["qty"]
                ups_val = (raw_map[key] or 0) if key in raw_map else None
                basis = "live"
                basis_label = "현재 값(스냅샷 없음)"
            if qr_val is None or ups_val is None or qr_val == ups_val:
                continue
            bc_k, code_k = key.split("|", 1)
            items.append({
                "branch_code": bc_k,
                "item_code": code_k,
                "item_name": inv_map[key]["name"],
                "qr_qty": qr_val,
                "ups": ups_val,
                "cnt": scan_cnt.get(key, 0),
                "basis": basis,
                "basis_label": basis_label,
            })
        items.sort(key=lambda x: (str(x["branch_code"]), str(x["item_code"])))
        return items

    items = []
    for r in scan_rows:
        key = f"{r['branch_code']}|{r['item_code']}"
        if key not in inv_map:
            continue
        snap = snap_map.get(key)
        if snap is not None:
            qr_qty = snap["qr_qty"] or 0
            ups = snap["ups_qty"]
            basis = "snap"
            basis_label = _basis_label(snap)
        else:
            qr_qty = inv_map[key]["qty"] or 0
            ups = (raw_map[key] or 0) if key in raw_map else None
            basis = "live"
            basis_label = "현재 값(스냅샷 없음)"
        items.append({
            "branch_code": r["branch_code"],
            "item_code": r["item_code"],
            "item_name": inv_map[key]["name"],
            "qr_qty": qr_qty,
            "ups": ups,
            "cnt": r["cnt"],
            "basis": basis,
            "basis_label": basis_label,
        })
    items.sort(key=lambda x: (str(x["branch_code"]), str(x["item_code"])))
    return items

def _sc_day_flows(branch_code: str, sel_date, codes: list):
    """지점×날짜×품번목록의 당일 출고 흐름을 시간순 이벤트로 반환.
    반환: (ups_by_code, qr_by_code) — 각 값은 [{"t": naive KST datetime, "code","customer"?}...]"""
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz
    kst = _tz(_td(hours=9))
    utc = _tz.utc
    date_str = sel_date.strftime("%Y-%m-%d")
    codes = [str(c) for c in codes]
    if not codes or not branch_code:
        return {}, {}

    branches = get_branches(branch_type='branch')
    code_to_name = {b["branch_code"]: b["branch_name"] for b in branches}
    branch_name = code_to_name.get(branch_code, "")
    if not branch_name:
        return {}, {}

    start_kst = _dt(sel_date.year, sel_date.month, sel_date.day, tzinfo=kst)
    end_kst = start_kst + _td(days=1)
    start_utc = start_kst.astimezone(utc).strftime("%Y-%m-%dT%H:%M:%S")
    end_utc = end_kst.astimezone(utc).strftime("%Y-%m-%dT%H:%M:%S")

    conn = get_conn()
    try:
        ph = ",".join("?" for _ in codes)
        ups_rows = conn.execute(
            "SELECT sale_datetime, customer_name, item_code, quantity FROM sales_records "
            f"WHERE sale_date=? AND branch_name=? AND item_code IN ({ph})",
            tuple([date_str, branch_name] + codes)
        ).fetchall()
        qr_rows = conn.execute(
            "SELECT scanned_at, item_code FROM scan_log "
            f"WHERE branch_code=? AND scan_type='OUT' AND scanned_at>=? AND scanned_at<? "
            f"AND item_code IN ({ph})",
            tuple([branch_code, start_utc, end_utc] + codes)
        ).fetchall()
    finally:
        conn.close()

    ups_by_code, qr_by_code = {}, {}
    for r in ups_rows:
        try:
            t = _dt.strptime(str(r["sale_datetime"]), "%Y-%m-%d %H:%M")
        except Exception:
            continue
        qty = max(1, int(r["quantity"] or 1))
        for _ in range(min(qty, 50)):
            ups_by_code.setdefault(r["item_code"], []).append({
                "t": t, "code": r["item_code"],
                "customer": (r["customer_name"] or "").strip() or "고객",
            })
    for r in qr_rows:
        try:
            t = _dt.fromisoformat(str(r["scanned_at"]).replace("Z", "+00:00"))
            if t.tzinfo is None:
                t = t.replace(tzinfo=utc)
            t = t.astimezone(kst).replace(tzinfo=None)
        except Exception:
            continue
        qr_by_code.setdefault(r["item_code"], []).append({"t": t, "code": r["item_code"]})
    for v in ups_by_code.values():
        v.sort(key=lambda x: x["t"])
    for v in qr_by_code.values():
        v.sort(key=lambda x: x["t"])
    return ups_by_code, qr_by_code


def _sc_match_flows(u_list: list, q_list: list, window_min: int = 30):
    """유비플러스 이벤트(u_list)와 QR 이벤트(q_list)를 시간순 매칭.
    반환: (missed_ups, extra_qr) — 매칭 안 된 이벤트들."""
    import bisect
    from datetime import timedelta as _td
    q_times = [q["t"] for q in q_list]
    used_q = [False] * len(q_list)
    missed_ups = []
    for u in u_list:
        lo = bisect.bisect_left(q_times, u["t"] - _td(minutes=window_min))
        hi = bisect.bisect_right(q_times, u["t"] + _td(minutes=window_min))
        best_i, best_d = -1, None
        for i in range(lo, hi):
            if used_q[i]:
                continue
            d = abs((u["t"] - q_times[i]).total_seconds()) / 60.0
            if best_d is None or d < best_d:
                best_i, best_d = i, d
        if best_i >= 0:
            used_q[best_i] = True
        else:
            missed_ups.append(u)
    extra_qr = [q for i, q in enumerate(q_list) if not used_q[i]]
    return missed_ups, extra_qr


def _sc_discrepancy_analysis(branch_code: str, sel_date, lines: list) -> list:
    """오차(diff_qty != 0)가 있는 품목별로 당일 유비플러스 출고(sales_records)와
    QR 출고 스캔(scan_log OUT)을 시간순으로 매칭해 누락/오등록 추정 문자열을 만든다.
    건수 차이(net)가 큰 쪽만 보고하고, 양쪽에 남은 건(교차)은 건수 차이가 없을 때만 표시.
    반환: [{branch_code,item_name,ups_qty,counted_qty,diff_qty,estimate}]"""
    date_str = sel_date.strftime("%Y-%m-%d")
    diff_lines = [l for l in lines if (l["diff_qty"] or 0) != 0]
    if not diff_lines or not branch_code:
        return []

    codes = [str(l["item_code"]) for l in diff_lines]
    ups_by_code, qr_by_code = _sc_day_flows(branch_code, sel_date, codes)

    out = []
    for l in diff_lines:
        code = str(l["item_code"])
        u_list = ups_by_code.get(code, [])
        q_list = qr_by_code.get(code, [])
        missed_ups, extra_qr = _sc_match_flows(u_list, q_list)

        net = len(u_list) - len(q_list)  # >0 이면 유비플러스가 더 많음 → QR 누락 방향
        parts = []
        # 건수 차이가 있으면 차이가 큰 쪽의 미매칭 건만 보고 (반대쪽은 타이밍 노이즈)
        if net > 0 and missed_ups:
            for u in missed_ups[:3]:
                parts.append(f"{u['t'].strftime('%H:%M')} {u['customer']} QR 누락 추정")
            if len(missed_ups) > 3:
                parts.append(f"QR 누락 외 {len(missed_ups) - 3}건")
        elif net < 0 and extra_qr:
            for q in extra_qr[:3]:
                parts.append(f"{q['t'].strftime('%H:%M')} 유비플러스 오등록 추정")
            if len(extra_qr) > 3:
                parts.append(f"오등록 외 {len(extra_qr) - 3}건")
        else:
            # 건수는 같은데 시간대가 어긋난 교차 케이스 — 양쪽 미매칭을 함께 표시
            for u in missed_ups[:2]:
                parts.append(f"{u['t'].strftime('%H:%M')} {u['customer']} QR 누락 추정")
            for q in extra_qr[:2]:
                parts.append(f"{q['t'].strftime('%H:%M')} 유비플러스 오등록 추정")
        if not parts:
            if u_list or q_list:
                parts.append(
                    f"유비플러스 출고 {len(u_list)}건 / QR 출고 {len(q_list)}건 — 시간 매칭 실패"
                )
            else:
                parts.append("당일 출고 내역 없음")
        estimate = " / ".join(parts)

        out.append({
            "branch_code": l["branch_code"],
            "item_code": code,
            "item_name": l["item_name"] or "",
            "ups_qty": l["ups_qty"],
            "counted_qty": l["counted_qty"],
            "diff_qty": l["diff_qty"],
            "estimate": estimate,
            # 타임라인 표시용 원본 이벤트 (오차내역 하단 아코디언)
            "qr_events": [q["t"].strftime("%H:%M") for q in q_list[:200]],
            "ups_events": [{"t": u["t"].strftime("%H:%M"), "customer": u["customer"]}
                           for u in u_list[:200]],
            "missed": [{"t": u["t"].strftime("%H:%M"), "customer": u["customer"]}
                       for u in missed_ups[:50]],
            "extra": [q["t"].strftime("%H:%M") for q in extra_qr[:50]],
        })
    return out


def _sc_adjust_cell(branch_code, item_code, editable) -> str:
    """재고 마감 목록의 'QR 수정' 칸 — 수기조정(/adjust)으로 해당 지점·상품을 미리 선택해서 이동"""
    from urllib.parse import quote as _quote
    if not editable:
        return "<td>-</td>"
    link = "/adjust?preset_branch=" + _quote(str(branch_code)) + "&preset_code=" + _quote(str(item_code))
    return (
        '<td><a href="' + link + '" style="background:#1E2761;color:white;padding:4px 10px;'
        'border-radius:6px;font-size:12px;text-decoration:none;">수정</a></td>'
    )

def _sc_closer_box(view_mode: str, save, can_write: bool) -> str:
    """재고 마감 화면 맨 위의 '마감 담당자' + '오차 사유' 입력칸"""
    import html as _html
    name = ""
    reason = ""
    if save:
        try:
            name = str(save["closer_name"] or "")
            reason = str(save["reason"] or "")
        except Exception:
            name = ""
            reason = ""
    esc = _html.escape(name)
    resc = _html.escape(reason)
    if can_write:
        return (
            '<div class="card" style="margin-bottom:12px;">'
            '<label style="font-size:13px;font-weight:bold;">마감 담당자 <span style="color:#DC2626;">*</span></label>'
            f'<input type="text" id="scCloser" maxlength="30" placeholder="마감 담당자 이름 (필수)" value="{esc}" style="margin-top:6px;max-width:260px;">'
            '<div style="font-size:12px;color:#888;margin-top:4px;">지점 계정과 무관하게 실제 마감하는 사람의 이름을 입력해주세요. 마감할 때 필수입니다.</div>'
            '<label style="font-size:13px;font-weight:bold;display:block;margin-top:12px;">전체 오차 사유 <span style="color:#888;font-weight:normal;">(선택)</span></label>'
            f'<input type="text" id="scReason" maxlength="200" placeholder="전체 사유 — 품목별 사유는 표의 \'사유\' 칸에 입력" value="{resc}" style="margin-top:6px;max-width:100%;">'
            '<div style="font-size:12px;color:#888;margin-top:4px;">오차가 있는 품목은 표의 \'사유\' 칸 입력이 마감 시 필수입니다. 여기는 전체를 덮는 메모입니다.</div>'
            "</div>"
        )
    shown = esc if esc else "-"
    rshown = resc if resc else "-"
    return (
        '<div class="card" style="margin-bottom:12px;font-size:13px;">'
        f'<b>마감 담당자</b> {shown}<br><b>오차 사유</b> {rshown}</div>'
    )


@app.get("/stock-closing", response_class=HTMLResponse)
async def stock_closing_page(
    session_token: str = Cookie(default=None),
    filter_branch: str = "",
    date: str = ""
):
    """재고 마감 — 날짜별 QR 입·출고 스캔 목록, QR 재고, 유비플러스 재고, 실사 수량 저장/마감, 오차"""
    import html as _html
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz

    user = get_session(session_token)
    if not user:
        return RedirectResponse(url="/login", status_code=303)

    is_master_user = user["role"] == "master"
    target_branch = filter_branch if is_master_user else user["branch_code"]

    # 한국시간 기준 조회 날짜 (기본 오늘, 미래 날짜는 오늘로 보정)
    kst = _tz(_td(hours=9))
    today_kst, editable_dates = _stock_closing_editable_dates()
    sel_date = today_kst
    if date:
        try:
            sel_date = _dt.strptime(date, "%Y-%m-%d").date()
        except ValueError:
            sel_date = today_kst
    if sel_date > today_kst:
        sel_date = today_kst
    can_edit_date = sel_date in editable_dates
    sel_date_str = sel_date.strftime("%Y-%m-%d")
    today_str = today_kst.strftime("%Y-%m-%d")
    window_end_str = (sel_date + _td(days=1)).strftime("%Y-%m-%d")

    # 지점이 정해진 경우에만 저장/마감 내역 조회
    save = None
    snap_lines = []
    conn = get_conn()
    if target_branch:
        save = conn.execute(
            "SELECT * FROM stock_closing_saves WHERE branch_code=? AND close_date=?",
            (target_branch, sel_date_str)
        ).fetchone()
        if save:
            snap_lines = conn.execute(
                "SELECT * FROM stock_closing_lines WHERE save_id=? ORDER BY item_code",
                (save["id"],)
            ).fetchall()
    conn.close()

    save_status = ((save["status"] or "draft") if save else "")
    if save and save_status == "closed":
        view_mode = "closed"
    elif can_edit_date:
        view_mode = "live"
    elif save:
        view_mode = "draft_snapshot"
    else:
        view_mode = "past_live"
    can_write = (view_mode == "live") and (not is_master_user)

    draft_counts = {}
    draft_reasons = {}
    if save and view_mode == "live":
        draft_counts = {l["item_code"]: l["counted_qty"] for l in snap_lines}
        try:
            draft_reasons = {l["item_code"]: (l["reason"] or "") for l in snap_lines}
        except Exception:
            draft_reasons = {}

    def _fmt_num(v):
        return "-" if v is None else str(v)

    def _diff_html(d):
        if d is None:
            return '<td class="sc-diff" style="font-weight:bold;color:#888;">-</td>'
        color = "#22C55E" if d == 0 else ("#EF4444" if d < 0 else "#F59E0B")
        txt = ("+" if d > 0 else "") + str(d)
        return f'<td class="sc-diff" style="font-weight:bold;color:{color};">{txt}</td>'

    rows_html = ""
    if view_mode in ("closed", "draft_snapshot"):
        # 저장된 값 그대로 표시
        for l in snap_lines:
            rows_html += (
                "<tr>"
                f"<td>{_html.escape(str(l['branch_code']))}</td>"
                f"<td>{_html.escape(str(l['item_name'] or ''))}</td>"
                f"<td>{_html.escape(str(l['item_code']))}</td>"
                f"<td>{_fmt_num(l['scan_qty'])}</td>"
                f"<td>{_fmt_num(l['qr_qty'])}</td>"
                f"<td>{_fmt_num(l['ups_qty'])}</td>"
                f"<td>{_fmt_num(l['counted_qty'])}</td>"
                + _diff_html(l["diff_qty"])
                + "<td>" + (_html.escape(str(l["reason"])) if "reason" in l.keys() and l["reason"] else "-") + "</td>"
                + "<td>-</td>"
                + "</tr>"
            )
        empty_msg = "저장된 상품이 없습니다 (해당 날짜에 스캔된 QR 등록 상품이 없었습니다)"
    else:
        items = _stock_closing_live_items(target_branch, sel_date, mismatch_only=True)
        for it in items:
            if can_edit_date or it["basis"] == "snap":
                qr_disp = _fmt_num(it["qr_qty"])
                ups = it["ups"]
                ups_disp = _fmt_num(ups)
                ups_attr = "" if ups is None else str(ups)
                qr_attr = "" if it["qr_qty"] is None else str(it["qr_qty"])
            else:
                # 과거 날짜(저장값 없음): QR/유비플러스 재고는 현재 값만 있어 비교 불가
                qr_disp = "-"
                ups_disp = "-"
                ups_attr = ""
                qr_attr = ""
            cv = draft_counts.get(it["item_code"])
            val_attr = "" if cv is None else f' value="{cv}"'
            rv = draft_reasons.get(it["item_code"], "")
            r_attr = _html.escape(str(rv))
            dis = "" if can_write else " disabled"
            rows_html += (
                "<tr>"
                f"<td>{_html.escape(str(it['branch_code']))}</td>"
                f"<td>{_html.escape(str(it['item_name']))}</td>"
                f"<td>{_html.escape(str(it['item_code']))}</td>"
                f"<td>{it['cnt']}</td>"
                f"<td>{qr_disp}</td>"
                f"<td>{ups_disp}</td>"
                f'<td><input type="number" min="0" class="sc-input" '
                f'data-code="{_html.escape(str(it["item_code"]))}" data-ups="{ups_attr}" data-qr="{qr_attr}"{val_attr} '
                f'placeholder="실사" oninput="scUpdateDiff(this)"{dis} '
                'style="width:100%;padding:4px;border:1px solid #ccc;border-radius:6px;"></td>'
                '<td class="sc-diff" style="font-weight:bold;color:#888;">-</td>'
                f'<td><input type="text" class="sc-reason" data-code="{_html.escape(str(it["item_code"]))}" '
                f'value="{r_attr}" placeholder="오차 시 필수" maxlength="200"{dis} '
                'style="width:100%;padding:4px;border:1px solid #ccc;border-radius:6px;font-size:12px;"></td>'
                + _sc_adjust_cell(it["branch_code"], it["item_code"], can_edit_date)
                + "</tr>"
            )
        empty_msg = "해당 날짜에 스캔된 QR 등록 상품이 없습니다"
    if not rows_html:
        rows_html = (
            '<tr><td colspan="10" style="text-align:center;padding:24px;color:#888;">'
            + empty_msg + "</td></tr>"
        )

    # 지점 필터(마스터) + 날짜 필터를 한 폼으로 묶어 서로의 선택값이 유지되도록 함
    branch_select_html = ""
    if is_master_user:
        branch_options = '<option value="">전체 지점</option>'
        for b in get_branches():
            sel = "selected" if filter_branch == b["branch_code"] else ""
            branch_options += (
                f'<option value="{_html.escape(str(b["branch_code"]))}" {sel}>'
                f'{_html.escape(str(b["branch_name"]))}</option>'
            )
        branch_select_html = (
            '<div style="flex:1;max-width:220px;">'
            '<label style="font-size:12px;color:#888;">지점 필터</label>'
            f'<select name="filter_branch" style="margin-top:4px;">{branch_options}</select>'
            "</div>"
        )
    filter_html = (
        '<form method="get" action="/stock-closing" style="margin-bottom:16px;">'
        '<div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;">'
        + branch_select_html
        + '<div style="flex:1;max-width:170px;">'
        '<label style="font-size:12px;color:#888;">날짜</label>'
        f'<input type="date" name="date" value="{sel_date_str}" max="{today_str}" style="margin-top:4px;">'
        "</div>"
        '<button class="btn" type="submit">조회</button>'
        '<a href="/stock-closing" style="padding:10px 14px;background:#eee;'
        'border-radius:8px;font-size:13px;text-decoration:none;color:#555;">오늘로</a>'
        "</div></form>"
    )

    # 상단 메타 정보 — 필터 아래, 테이블 위에 표시 (기존 QR/RW 마지막 스캔 카드 대체)
    meta_lines = [
        f"{sel_date_str} (00시~24시) QR 스캔 기준",
        "금일 출고 수량 = 출고(OUT) + 입고(IN) 스캔 합계 · 오차 = 실사 수량 − 유비플러스 재고",
    ]
    if view_mode in ("live", "past_live") and items:
        basis_text = ", ".join(sorted({it["basis_label"] for it in items}))
        meta_lines.append("QR 재고·유비플러스 재고 기준: " + basis_text)
    if view_mode == "live":
        meta_lines.append(f"마감 가능 기간: {sel_date_str} ~ {window_end_str}")
    cards_html = (
        '<div class="card" style="margin-bottom:16px;padding:10px 14px;">'
        + "".join(
            f'<div style="font-size:12px;color:#475569;line-height:1.7;">{_html.escape(ln)}</div>'
            for ln in meta_lines
        )
        + "</div>"
    )

    # 상태 안내 문구
    notice_style = 'class="card" style="font-size:12px;margin-bottom:12px;'
    notices_html = ""
    if view_mode == "closed":
        _sc_reason = ""
        try:
            _sc_reason = str(save["reason"] or "")
        except Exception:
            _sc_reason = ""
        _sc_reason_html = (
            f' · 사유: {_html.escape(_sc_reason)}' if _sc_reason else ""
        )
        notices_html += (
            f'<div {notice_style}color:#166534;background:#F0FDF4;">'
            f'✅ 마감 완료 — {_html.escape(str(save["closed_by"] or "-"))} · '
            f'{_html.escape(str(save["closed_at"] or "-"))} · 마감 후에는 수정할 수 없습니다.'
            + _sc_reason_html + "</div>"
        )
    elif view_mode == "live":
        if save:
            _sc_draft_reason = ""
            try:
                _sc_draft_reason = str(save["reason"] or "")
            except Exception:
                _sc_draft_reason = ""
            _sc_draft_reason_html = (
                f' · 사유: {_html.escape(_sc_draft_reason)}' if _sc_draft_reason else ""
            )
            notices_html += (
                f'<div {notice_style}color:#1E40AF;background:#EFF6FF;">'
                f'💾 임시저장됨 — {_html.escape(str(save["saved_by"] or "-"))} · '
                f'{_html.escape(str(save["saved_at"] or "-"))} (마감 전까지 수정할 수 있습니다)'
                + _sc_draft_reason_html + "</div>"
            )
        if sel_date != today_kst:
            notices_html += (
                f'<div {notice_style}color:#92400E;background:#FFFBEB;">'
                "전일 날짜 마감입니다. QR 재고와 유비플러스 재고는 현재 시점 값입니다.</div>"
            )
        if is_master_user:
            notices_html += (
                f'<div {notice_style}color:#475569;background:#F8FAFC;">'
                "마스터 계정은 조회만 가능합니다. 지점을 선택하면 해당 지점의 저장/마감 내용이 표시됩니다. "
                '<a href="/stock-closing/status" style="color:#1E2761;font-weight:bold;">→ 지점별 마감 현황 보기</a></div>'
            )
    elif view_mode == "draft_snapshot":
        notices_html += (
            f'<div {notice_style}color:#92400E;background:#FFFBEB;">'
            f'임시저장 값입니다(마감되지 않음) — 마지막 저장 {_html.escape(str(save["saved_at"] or "-"))}. '
            "마감 가능 기간이 지나 더 이상 수정할 수 없습니다.</div>"
        )
    else:
        notices_html += (
            f'<div {notice_style}color:#92400E;background:#FFFBEB;">'
            "전일 날짜 마감입니다. 재고 값은 위에 표시된 기준 시각을 따릅니다.</div>"
        )

    # 저장된 내역 기준 오차 분석 — 유비플러스 출고 vs QR 출고 스캔 시간 매칭 추정
    disc_html = ""
    if save and target_branch:
        disc_items = _sc_discrepancy_analysis(target_branch, sel_date, snap_lines)
        if disc_items:
            def _chip(t, bg, fg="#1F2937", extra=""):
                return ('<span style="display:inline-block;margin:2px;padding:2px 6px;border-radius:4px;'
                        'font-size:11px;background:' + bg + ';color:' + fg + ';">'
                        + _html.escape(str(t) + extra) + '</span>')

            disc_rows = ""
            for d in disc_items:
                dcolor = "#EF4444" if (d["diff_qty"] or 0) < 0 else "#F59E0B"
                dsign = "+" if (d["diff_qty"] or 0) > 0 else ""
                qr_ev = d.get("qr_events") or []
                ups_ev = d.get("ups_events") or []
                missed = d.get("missed") or []
                extra = d.get("extra") or []
                # 타임라인 칩 (각 행 최대 60개 표시)
                qr_chips = " ".join(_chip(t, "#DBEAFE") for t in qr_ev[:60])
                if len(qr_ev) > 60:
                    qr_chips += _chip("외 " + str(len(qr_ev) - 60) + "건", "#E2E8F0", "#64748B")
                ups_chips = " ".join(_chip(e["t"] + " " + (e.get("customer") or ""), "#DCFCE7")
                                    for e in ups_ev[:60])
                if len(ups_ev) > 60:
                    ups_chips += _chip("외 " + str(len(ups_ev) - 60) + "건", "#E2E8F0", "#64748B")
                if not qr_chips:
                    qr_chips = '<span style="color:#aaa;">없음</span>'
                if not ups_chips:
                    ups_chips = '<span style="color:#aaa;">없음</span>'
                miss_chips = " ".join(
                    _chip(m["t"] + " " + (m.get("customer") or "") + " QR누락?", "#FEE2E2", "#991B1B")
                    for m in missed[:20])
                ext_chips = " ".join(
                    _chip(t + " 오등록?", "#FEE2E2", "#991B1B") for t in extra[:20])
                unmatch = ""
                if miss_chips or ext_chips:
                    unmatch = ('<div style="margin-top:4px;"><b style="color:#DC2626;font-size:11px;">미매칭 추정:</b> '
                               + miss_chips + ext_chips + '</div>')
                has_tl = bool(qr_ev or ups_ev)
                # 1행: 요약 / 2행: 타임라인(항상 표시)
                tl_row = ""
                if has_tl:
                    tl_row = (
                        '<tr><td colspan="5" style="background:#F8FAFC;padding:8px 10px;">'
                        '<div style="font-size:12px;">'
                        '<div style="margin-bottom:4px;"><b>QR 스캔:</b> ' + qr_chips + '</div>'
                        '<div style="margin-bottom:4px;"><b>유비플러스:</b> ' + ups_chips + '</div>'
                        + unmatch + '</div></td></tr>'
                    )
                else:
                    tl_row = ('<tr><td colspan="5" style="background:#F8FAFC;padding:6px 10px;'
                              'color:#aaa;font-size:12px;">출고 내역 없음</td></tr>')
                disc_rows += (
                    "<tr>"
                    f"<td>{_html.escape(str(d['branch_code']))}</td>"
                    f"<td>{_html.escape(str(d['item_name']))}</td>"
                    f"<td>{_fmt_num(d['ups_qty'])}</td>"
                    f"<td>{_fmt_num(d['counted_qty'])}</td>"
                    f"<td style='font-weight:bold;color:{dcolor};white-space:nowrap;'>{dsign}{d['diff_qty']}</td>"
                    "</tr>" + tl_row
                )
            disc_html = (
                '<div class="card" style="border:1px solid #FCA5A5;background:#FFF7ED;margin-bottom:16px;">'
                '<h3 style="margin:0 0 4px 0;font-size:14px;">⚠️ 오차 내역</h3>'
                '<p style="font-size:11px;color:#888;margin:0 0 8px 0;">'
                '각 항목 아래에 당일 QR 출고 스캔과 유비플러스 출고를 시간순으로 나열했습니다. '
                '빨간색은 시간 매칭이 안 된 건으로, 실제 원인과 다를 수 있는 추정입니다.</p>'
                '<div class="table-scroll-wrap"><table data-colver="2026-11-20" style="table-layout:fixed;min-width:640px;"><colgroup><col style="width:90px"><col style="width:230px"><col style="width:130px"><col style="width:90px"><col style="width:100px"></colgroup><thead><tr>'
                '<th style="width:10%">지점</th><th style="width:30%">상품명</th>'
                '<th style="width:14%">유비플러스 재고수량</th><th style="width:10%">실사수량</th>'
                '<th style="width:9%">오차</th>'
                '</tr></thead><tbody>' + disc_rows + '</tbody></table></div></div>'
            )

    buttons_html = ""
    if can_write:
        buttons_html = (
            f'<div id="scMeta" data-date="{sel_date_str}" style="display:none;"></div>'
            '<div style="display:flex;gap:8px;margin-top:12px;">'
            '<button class="btn" type="button" style="flex:1;background:#64748B;" onclick="scSubmit(\'draft\')">💾 저장</button>'
            '<button class="btn" type="button" style="flex:1;" onclick="scSubmit(\'close\')">✅ 마감</button>'
            "</div>"
            '<p style="font-size:12px;color:#888;margin-top:8px;">'
            "저장은 마감 전까지 수정할 수 있습니다. 마감하면 수정할 수 없으니 확인 후 눌러주세요.</p>"
        )

    script = """
    <script>
      function scUpdateDiff(inp) {
        var tr = inp.closest('tr');
        var cell = tr.querySelector('.sc-diff');
        var ups = inp.getAttribute('data-ups');
        if (inp.value === '' || ups === '') {
          cell.textContent = '-';
          cell.style.color = '#888';
          return;
        }
        var diff = parseInt(inp.value, 10) - parseInt(ups, 10);
        if (isNaN(diff)) {
          cell.textContent = '-';
          cell.style.color = '#888';
          return;
        }
        cell.textContent = (diff > 0 ? '+' : '') + diff;
        cell.style.color = diff === 0 ? '#22C55E' : (diff < 0 ? '#EF4444' : '#F59E0B');
      }

      function scCollect() {
        var counts = {};
        var reasons = {};
        document.querySelectorAll('.sc-input').forEach(function(inp) {
          counts[inp.getAttribute('data-code')] = inp.value;
        });
        document.querySelectorAll('.sc-reason').forEach(function(inp) {
          reasons[inp.getAttribute('data-code')] = inp.value;
        });
        return {counts: counts, reasons: reasons};
      }

      async function scSubmit(mode) {
        var meta = document.getElementById('scMeta');
        if (!meta) return;
        var date = meta.getAttribute('data-date');
        var closerEl = document.getElementById('scCloser');
        var closer = closerEl ? closerEl.value.trim() : '';
        var reasonEl = document.getElementById('scReason');
        var reason = reasonEl ? reasonEl.value.trim() : '';
        if (mode === 'close' && closer === '') {
          alert('마감 담당자 이름을 입력해주세요. (마감 시 필수)');
          if (closerEl) closerEl.focus();
          return;
        }
        if (mode === 'close') {
          var empty = 0;
          var noReason = 0;
          document.querySelectorAll('.sc-input').forEach(function(inp) {
            if (inp.value !== '') return;
            var qr = inp.getAttribute('data-qr');
            var ups = inp.getAttribute('data-ups');
            if (qr !== null && qr !== '' && ups !== null && ups !== ''
                && parseInt(qr, 10) !== parseInt(ups, 10)) empty++;
          });
          document.querySelectorAll('.sc-input').forEach(function(inp) {
            var tr = inp.closest('tr');
            var diffCell = tr ? tr.querySelector('.sc-diff') : null;
            var t = diffCell ? diffCell.textContent.trim() : '';
            if (t !== '' && t !== '-' && t !== '0') {
              var code = inp.getAttribute('data-code');
              var rInp = tr.querySelector('.sc-reason[data-code="' + code + '"]');
              if (!rInp || rInp.value.trim() === '') noReason++;
            }
          });
          if (empty > 0) {
            alert('QR 재고와 유비플러스 재고가 다른 상품 중 실사 수량이 입력되지 않은 것이 ' + empty + '개 있습니다.\\n해당 품목만 입력한 뒤 마감해주세요. (오차 없는 품목은 미입력 가능)');
            return;
          }
          if (noReason > 0) {
            alert("오차가 있는 품목 " + noReason + "개의 사유가 입력되지 않았습니다.\\n표의 '사유' 칸에 입력한 뒤 마감해주세요.");
            return;
          }
          if (!confirm('마감 후에는 수정할 수 없습니다.\\n입력한 내용을 확인했다면 [확인]을 눌러 마감해주세요.')) {
            return;
          }
        }
        try {
          var collected = scCollect();
          var res = await fetch('/stock-closing/save', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({date: date, mode: mode, counts: collected.counts, reasons: collected.reasons, closer_name: closer, reason: reason})
          });
          var data = await res.json();
          if (!res.ok) {
            alert(data.detail || '처리에 실패했습니다.');
            return;
          }
          alert(data.message || '완료되었습니다.');
          location.reload();
        } catch (e) {
          alert('오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
        }
      }

      window.addEventListener('load', function() {
        document.querySelectorAll('.sc-input').forEach(function(inp) {
          if (inp.value !== '') scUpdateDiff(inp);
        });
      });
    </script>
    """

    content = (
        '<h2 style="margin:0 0 8px 0;">📦 재고 마감</h2>'
        + _closing_guide_bar(user, "stock-closing")
        + _sc_closer_box(view_mode, save, can_write)
        + filter_html
        + cards_html
        + notices_html
        + disc_html
        + '<div class="card"><div class="table-scroll-wrap"><table data-colver="2026-11">'
        "<thead><tr>"
        '<th style="width:8%">지점</th><th style="width:25%">상품명</th>'
        '<th style="width:10%">상품코드</th><th style="width:9%">금일 출고 수량</th>'
        '<th style="width:9%">QR 재고 수량</th><th style="width:11%">유비플러스 재고 수량</th>'
        '<th style="width:11%">실사 수량</th><th style="width:7%">오차</th><th style="width:12%">사유</th><th style="width:10%">QR 수정</th>'
        "</tr></thead><tbody>"
        + rows_html
        + "</tbody></table></div>"
        + buttons_html
        + "</div>"
        + script
    )
    return HTMLResponse(render_page(content, user, active="stock-closing"))


@app.get("/master/sc-estimate-test", response_class=HTMLResponse)
async def master_sc_estimate_test(
    session_token: str = Cookie(default=None),
    branch_code: str = "",
    date: str = "",
):
    """오차 추정 미리보기 — 텍스트 추정 vs 타임라인 2행 표시 비교용 테스트 페이지 (마스터 전용)"""
    import html as _html
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz

    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)

    kst = _tz(_td(hours=9))
    today_kst = _dt.now(kst).date()
    sel_date = today_kst
    if date:
        try:
            sel_date = _dt.strptime(date, "%Y-%m-%d").date()
        except ValueError:
            pass
    if sel_date > today_kst:
        sel_date = today_kst
    sel_date_str = sel_date.strftime("%Y-%m-%d")

    branches = get_branches(branch_type='branch')
    if not branch_code and branches:
        branch_code = branches[0]["branch_code"]
    bname_map = {b["branch_code"]: b["branch_name"] for b in branches}

    # 저장 내역이 있으면 그 품목 기준, 없으면 당일 출고가 있는 품목 전체(최대 60)
    conn = get_conn()
    save = conn.execute(
        "SELECT * FROM stock_closing_saves WHERE branch_code=? AND close_date=? ORDER BY id DESC LIMIT 1",
        (branch_code, sel_date_str)
    ).fetchone() if branch_code else None
    lines = []
    if save:
        lines = conn.execute(
            "SELECT * FROM stock_closing_lines WHERE save_id=? ORDER BY item_code",
            (save["id"],)
        ).fetchall()
    conn.close()

    if lines:
        codes = [str(l["item_code"]) for l in lines]
        name_map = {str(l["item_code"]): (l["item_name"] or "") for l in lines}
        diff_map = {str(l["item_code"]): (l["diff_qty"] or 0) for l in lines}
    else:
        ups_tmp, qr_tmp = _sc_day_flows(branch_code, sel_date, [""])
        # 빈 코드로는 못 가져오므로 scan/sales에서 코드 수집
        conn = get_conn()
        date_str = sel_date_str
        bn = bname_map.get(branch_code, "")
        rows = conn.execute(
            "SELECT DISTINCT item_code FROM scan_log WHERE branch_code=? AND scan_type='OUT' "
            "AND substr(scanned_at,1,10) IN (?, ?)",
            (branch_code, sel_date_str, (sel_date - _td(days=1)).strftime("%Y-%m-%d"))
        ).fetchall()
        codes = [r["item_code"] for r in rows][:60]
        conn.close()
        name_map, diff_map = {}, {}

    ups_by_code, qr_by_code = _sc_day_flows(branch_code, sel_date, codes) if codes else ({}, {})

    # 텍스트 추정 (오차 있는 품목만)
    pseudo_lines = [
        {"branch_code": branch_code, "item_code": c, "item_name": name_map.get(c, c),
         "ups_qty": None, "counted_qty": None, "diff_qty": diff_map.get(c, 1)}
        for c in codes if diff_map.get(c, 0) != 0 or not lines
    ]
    estimates = {r["item_code"]: r["estimate"] for r in
                 _sc_discrepancy_analysis(branch_code, sel_date, pseudo_lines)} if pseudo_lines else {}

    items_html = ""
    shown = 0
    for c in codes:
        u_list = ups_by_code.get(c, [])
        q_list = qr_by_code.get(c, [])
        if not u_list and not q_list:
            continue
        missed, extra = _sc_match_flows(u_list, q_list)
        matched_u = [u for u in u_list if u not in missed]
        matched_q = [q for q in q_list if q not in extra]
        nm = _html.escape(str(name_map.get(c) or c))
        diff_v = diff_map.get(c)
        diff_badge = ""
        if diff_v is not None and diff_v != 0:
            diff_badge = f'<span style="color:#DC2626;font-weight:bold;">오차 {diff_v:+d}</span>'
        est = _html.escape(str(estimates.get(c, "-")))
        # 타임라인: 2행 — QR 스캔 / 유비플러스 판매
        def _chips(evts, is_ups):
            out = []
            for e in evts:
                t = e["t"].strftime("%H:%M")
                if is_ups:
                    label = f"{t} {e.get('customer','')}"
                    cls = "background:#DCFCE7;"
                else:
                    label = t
                    cls = "background:#DBEAFE;"
                out.append(
                    f'<span style="display:inline-block;margin:2px;padding:2px 6px;border-radius:4px;font-size:11px;{cls}">{_html.escape(label)}</span>'
                )
            return " ".join(out) if out else '<span style="color:#aaa;">없음</span>'
        qr_chips = _chips(q_list, False)
        ups_chips = _chips(u_list, True)
        # 미매칭 하이라이트는 별도 행으로
        miss_chips = " ".join(
            f'<span style="display:inline-block;margin:2px;padding:2px 6px;border-radius:4px;font-size:11px;background:#FEE2E2;color:#991B1B;">{_html.escape(u["t"].strftime("%H:%M") + " " + u.get("customer",""))} QR누락?</span>'
            for u in missed[:10]
        )
        ext_chips = " ".join(
            f'<span style="display:inline-block;margin:2px;padding:2px 6px;border-radius:4px;font-size:11px;background:#FEE2E2;color:#991B1B;">{_html.escape(q["t"].strftime("%H:%M"))} 오등록?</span>'
            for q in extra[:10]
        )
        items_html += f"""
        <div class="card" style="padding:10px 14px;margin-bottom:8px;">
          <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;">
            <div style="font-weight:bold;font-size:13px;">{nm} <span style="color:#888;font-weight:normal;">({c})</span> {diff_badge}</div>
            <div style="font-size:11px;color:#888;">QR {len(q_list)}건 / 유비플러스 {len(u_list)}건</div>
          </div>
          <div style="font-size:12px;margin:6px 0;padding:6px;background:#FFF7ED;border-radius:6px;">
            <b>텍스트 추정:</b> {est}
          </div>
          <details>
            <summary style="font-size:12px;color:#1E2761;cursor:pointer;">타임라인 보기 (QR / 유비플러스 2행)</summary>
            <div style="margin-top:6px;font-size:12px;">
              <div style="margin-bottom:4px;"><b>QR 스캔:</b> {qr_chips}</div>
              <div style="margin-bottom:4px;"><b>유비플러스:</b> {ups_chips}</div>
              {(('<div style="margin-bottom:4px;"><b style="color:#DC2626;">미매칭 추정:</b> ' + miss_chips + ext_chips + '</div>') if (missed or extra) else '')}
            </div>
          </details>
        </div>"""
        shown += 1
        if shown >= 60:
            break

    branch_options = "".join(
        f'<option value="{b["branch_code"]}" {"selected" if b["branch_code"]==branch_code else ""}>{b["branch_name"]}</option>'
        for b in branches
    )
    content = f"""
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:12px;">
      <a href="/master" style="color:#1E2761;">← 마스터</a>
      <h2>🧪 오차 추정 미리보기</h2>
    </div>
    <div class="card" style="margin-bottom:12px;">
      <form method="get" action="/master/sc-estimate-test" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
        <select name="branch_code" style="padding:8px;">{branch_options}</select>
        <input type="date" name="date" value="{sel_date_str}" max="{today_kst.strftime('%Y-%m-%d')}" style="padding:8px;">
        <button class="btn" type="submit">조회</button>
      </form>
      <p style="font-size:12px;color:#888;margin:8px 0 0 0;">
        {('저장 내역 ' + str(save['close_date']) + ' 기준 ' + str(len(lines)) + '개 품목') if lines else '저장 내역 없음 — 당일 출고 있는 품목 최대 60개 표시'}
        · 매칭 허용 오차 ±30분
      </p>
    </div>
    {items_html if items_html else '<div class="card" style="text-align:center;color:#888;padding:30px;">표시할 출고 내역이 없습니다.</div>'}
    """
    return HTMLResponse(render_page(content, user, "master"))


@app.post("/stock-closing/save")
async def stock_closing_save(request: Request, session_token: str = Cookie(default=None)):
    """재고 마감 저장(임시저장)/마감 — 스캔·QR재고·유비플러스 재고는 서버가 다시 계산, 화면에서는 실사 수량만 받음"""
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz
    from fastapi import HTTPException
    from fastapi.responses import JSONResponse

    user = get_session(session_token)
    if not user:
        raise HTTPException(status_code=401, detail="로그인이 필요합니다.")
    if user["role"] == "master":
        raise HTTPException(status_code=403, detail="마스터 계정은 조회만 가능합니다. 지점 계정에서 저장/마감해주세요.")
    branch_code = user["branch_code"]

    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="요청 형식이 올바르지 않습니다.")
    date_str = str(body.get("date", "")).strip()
    mode = str(body.get("mode", "")).strip()
    counts = body.get("counts") or {}
    closer_name = str(body.get("closer_name", "")).strip()[:30]
    reason = str(body.get("reason", "")).strip()[:200]
    reasons = body.get("reasons") or {}
    if not isinstance(reasons, dict):
        reasons = {}
    if mode == "close" and not closer_name:
        raise HTTPException(status_code=400, detail="마감 담당자 이름을 입력해주세요. (마감 시 필수)")
    if mode not in ("draft", "close"):
        raise HTTPException(status_code=400, detail="저장 방식이 올바르지 않습니다.")
    if not isinstance(counts, dict):
        raise HTTPException(status_code=400, detail="실사 수량 형식이 올바르지 않습니다.")
    try:
        sel_date = _dt.strptime(date_str, "%Y-%m-%d").date()
    except ValueError:
        raise HTTPException(status_code=400, detail="날짜 형식이 올바르지 않습니다.")

    today_kst, editable_dates = _stock_closing_editable_dates()
    if sel_date not in editable_dates:
        raise HTTPException(status_code=400, detail="저장/마감 가능한 기간(해당 일자 + 익일)이 지났습니다.")

    # 서버에서 현재 값을 다시 계산
    items = _stock_closing_live_items(branch_code, sel_date, mismatch_only=True)
    lines = []
    missing = 0
    mismatch = 0
    for it in items:
        raw_val = counts.get(it["item_code"])
        counted = None
        if raw_val is not None and str(raw_val).strip() != "":
            try:
                counted = int(str(raw_val).strip())
            except ValueError:
                raise HTTPException(status_code=400, detail="실사 수량이 숫자가 아닙니다: " + str(it["item_code"]))
            if counted < 0:
                raise HTTPException(status_code=400, detail="실사 수량은 0 이상이어야 합니다: " + str(it["item_code"]))
        ups = it["ups"]
        if counted is None:
            # 실사 필수는 QR재고 ≠ 유비플러스재고 오차가 있는 품목뿐
            if it["qr_qty"] is not None and ups is not None and it["qr_qty"] != ups:
                missing += 1
        diff = (counted - ups) if (counted is not None and ups is not None) else None
        if diff is not None and diff != 0:
            mismatch += 1
        line_reason = str(reasons.get(it["item_code"], "") or "").strip()[:200] or None
        lines.append((it["item_code"], it["item_name"], it["cnt"], it["qr_qty"], ups, counted, diff, line_reason))

    if mode == "close" and missing > 0:
        raise HTTPException(
            status_code=400,
            detail="QR 재고와 유비플러스 재고가 다른 상품 중 실사 수량이 입력되지 않은 것이 " + str(missing) + "개 있습니다. 해당 품목만 입력하고 마감해주세요."
        )
    if mode == "close":
        no_reason = sum(
            1 for ln in lines
            if ln[6] is not None and ln[6] != 0 and not ln[7]
        )
        if no_reason > 0:
            raise HTTPException(
                status_code=400,
                detail="오차가 있는 품목 " + str(no_reason) + "개의 사유가 입력되지 않았습니다. 표의 '사유' 칸에 입력한 뒤 마감해주세요."
            )

    now_str = _dt.now(_tz(_td(hours=9))).strftime("%Y-%m-%d %H:%M:%S")
    login = user.get("login_id") or branch_code
    status = "closed" if mode == "close" else "draft"
    closed_by = login if mode == "close" else None
    closed_at = now_str if mode == "close" else None

    conn = get_conn()
    try:
        existing = conn.execute(
            "SELECT id, status FROM stock_closing_saves WHERE branch_code=? AND close_date=?",
            (branch_code, date_str)
        ).fetchone()
        if existing and (existing["status"] or "draft") == "closed":
            raise HTTPException(status_code=400, detail="이미 마감된 날짜입니다. 마감 후에는 수정할 수 없습니다.")
        if existing:
            save_id = existing["id"]
            conn.execute(
                "UPDATE stock_closing_saves SET status=?, saved_by=?, saved_at=?, closed_by=?, closed_at=?, "
                "item_count=?, mismatch_count=?, reason=? WHERE id=?",
                (status, login, now_str, closed_by, closed_at, len(lines), mismatch, reason or None, save_id)
            )
            conn.execute("DELETE FROM stock_closing_lines WHERE save_id=?", (save_id,))
        else:
            conn.execute(
                "INSERT INTO stock_closing_saves (branch_code, close_date, status, saved_by, saved_at, "
                "closed_by, closed_at, item_count, mismatch_count, reason) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (branch_code, date_str, status, login, now_str, closed_by, closed_at, len(lines), mismatch, reason or None)
            )
            row = conn.execute(
                "SELECT id FROM stock_closing_saves WHERE branch_code=? AND close_date=?",
                (branch_code, date_str)
            ).fetchone()
            save_id = row["id"]
        conn.execute("UPDATE stock_closing_saves SET closer_name=? WHERE id=?", (closer_name or None, save_id))
        for ln in lines:
            conn.execute(
                "INSERT INTO stock_closing_lines (save_id, branch_code, close_date, item_code, item_name, "
                "scan_qty, qr_qty, ups_qty, counted_qty, diff_qty, reason) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (save_id, branch_code, date_str) + ln
            )
        conn.commit()
    finally:
        conn.close()

    if mode == "close":
        msg = "마감되었습니다. 마감 후에는 수정할 수 없습니다."
    else:
        msg = "저장되었습니다. (임시저장 — 마감 전까지 수정할 수 있습니다)"
    return JSONResponse({"ok": True, "mode": mode, "message": msg})


# ── 지점 재고 실사 (daily stocktake — 소모품 제외 전 품목, 거래처/품류 필터) ──

# 거래처명 정규화 매핑 — 비어 있으면 원본 그대로 사용. "펫네스트"/"펫네스트(디자인주권)" 합치기 여부는
# 운영 데이터 확인 후 여기 한 곳만 수정하면 된다 (기본: 합치지 않음).
_DST_VENDOR_NAME_MAP = {}

# 상품 DB상 "구매처 없음"을 의미하는 플레이스홀더 — 거래처 필터에서는 (미등록)으로 취급
_DST_SUPPLIER_BLANK_VALUES = {"[삭제된구매처]"}


def _daily_stocktake_pm_map() -> dict:
    """item_code -> {supplier, category, consumable}. product_master는 지점별 중복 행이 있어 품번별로 집계.
    is_consumable은 PostgreSQL(boolean)/SQLite(int) 공통으로 CASE 집계 (COALESCE(x,0)은 PG에서 타입 오류)."""
    conn = get_conn()
    try:
        rows = conn.execute(
            "SELECT item_code, "
            "MAX(CASE WHEN is_consumable THEN 1 ELSE 0 END) AS is_consumable, "
            "min(NULLIF(trim(COALESCE(supplier, '')), '')) AS supplier, "
            "min(NULLIF(trim(COALESCE(category, '')), '')) AS category "
            "FROM product_master "
            "WHERE item_code IS NOT NULL AND item_code <> '' "
            "GROUP BY item_code"
        ).fetchall()
    except Exception:
        # product_master 테이블이 없는 환경(SQLite 로컬 등)에서는 마스터 정보 없이 진행
        rows = []
    finally:
        conn.close()
    pm = {}
    for r in rows:
        supplier = (r["supplier"] or "").strip()
        if supplier in _DST_SUPPLIER_BLANK_VALUES:
            supplier = ""
        supplier = _DST_VENDOR_NAME_MAP.get(supplier, supplier)
        pm[str(r["item_code"])] = {
            "supplier": supplier,
            "category": r["category"] or "",
            "consumable": bool(r["is_consumable"]),
        }
    return pm


def _daily_stocktake_items(branch_code: str):
    """지점의 소모품 제외 품목 + QR재고 + 유비플러스 재고 + 거래처/품류 (inventory 보유 품목만).
    거래처·품류·소모품은 상품 DB(product_master)만 사용 — purchase_records/상품명 접두사 대체 조회 없음.
    소모품 판정: product_master.is_consumable (NULL→소모품 아님) + 품번 미등록 해시 코드('미지정_')는 소모품 간주.
    품번에 pm 행이 없으면 소모품 아님으로 간주(단 '미지정_' 제외).
    반환: (items, excluded_count) — 제외 규칙: 빈 품번, 지점 목록에 없는 branch_code,
    UPS(raw)에 없고 qr_qty=0인 행, 소모품."""
    conn = get_conn()
    try:
        inv_rows = conn.execute(
            "SELECT item_code, item_name, quantity FROM inventory WHERE branch_code=? ORDER BY item_code",
            (branch_code,)
        ).fetchall()
    finally:
        conn.close()
    pm = _daily_stocktake_pm_map()
    raw_map = {f"{r['branch_code']}|{r['item_code']}": r["quantity"] for r in fetch_raw_inventory()}
    valid_codes = {str(b["branch_code"]) for b in get_branches(branch_type=None)}
    branch_valid = str(branch_code) in valid_codes
    items = []
    excluded = 0
    for r in inv_rows:
        code = str(r["item_code"] or "").strip()
        if not code or not branch_valid:
            excluded += 1
            continue
        if code.startswith("미지정_"):
            # 유비플러스 원본에 품번이 없어 업로드 시 생성된 해시 코드 — 상품 DB에 없는 품목이라 소모품으로 간주해 제외
            excluded += 1
            continue
        info = pm.get(code) or {}
        if info.get("consumable"):
            excluded += 1
            continue
        key = f"{branch_code}|{code}"
        ups = raw_map.get(key)
        qr_qty = r["quantity"] or 0
        if ups is None and qr_qty == 0:
            excluded += 1
            continue
        items.append({
            "item_code": code,
            "item_name": r["item_name"],
            "supplier": info.get("supplier", ""),
            "category": info.get("category", ""),
            "qr_qty": qr_qty,
            "ups": ups,
        })
    return items, excluded


def _dst_closer_box(save, can_write: bool) -> str:
    """재고 실사 화면 맨 위의 '실사 담당자' 입력칸"""
    import html as _html
    name = ""
    if save:
        try:
            name = str(save["closer_name"] or "")
        except Exception:
            name = ""
    esc = _html.escape(name)
    if can_write:
        return (
            '<div class="card" style="margin-bottom:12px;">'
            '<label style="font-size:13px;font-weight:bold;">실사 담당자 <span style="color:#DC2626;">*</span></label>'
            f'<input type="text" id="dstCloser" maxlength="30" placeholder="실사 담당자 이름 (필수)" value="{esc}" style="margin-top:6px;max-width:260px;">'
            '<div style="font-size:12px;color:#888;margin-top:4px;">실제 실사하는 사람의 이름을 입력해주세요. 저장할 때 필수입니다.</div>'
            "</div>"
        )
    shown = esc if esc else "-"
    return (
        '<div class="card" style="margin-bottom:12px;font-size:13px;">'
        f'<b>실사 담당자</b> {shown}</div>'
    )


@app.get("/daily-stocktake", response_class=HTMLResponse)
async def daily_stocktake_page(
    session_token: str = Cookie(default=None),
    filter_branch: str = "",
    date: str = "",
    vendor: str = "",
    category: str = "",
):
    """재고 실사 — 날짜/거래처/품류 선택 후 소모품 제외 품목 실사 수량 입력·저장. 마스터는 지점 선택 후 실사 가능."""
    import html as _html
    from datetime import datetime as _dt, timedelta as _td, timezone as _tz

    user = get_session(session_token)
    if not user:
        return RedirectResponse(url="/login", status_code=303)

    is_master_user = user["role"] == "master" or user.get("branch_type") == "hq"
    kst = _tz(_td(hours=9))
    today_kst = _dt.now(kst).date()

    sel_date = today_kst
    if date:
        try:
            sel_date = _dt.strptime(date, "%Y-%m-%d").date()
        except ValueError:
            sel_date = today_kst
    if sel_date > today_kst:
        sel_date = today_kst
    sel_date_str = sel_date.strftime("%Y-%m-%d")
    today_str = today_kst.strftime("%Y-%m-%d")

    target_branch = filter_branch if is_master_user else user["branch_code"]

    # 마스터가 지점을 선택하지 않은 경우: 지점 선택 안내만 표시
    if is_master_user and not target_branch:
        branch_options = '<option value="">-- 지점을 선택하세요 --</option>'
        for b in get_branches():
            branch_options += (
                f'<option value="{_html.escape(str(b["branch_code"]))}">'
                f'{_html.escape(str(b["branch_name"]))}</option>'
            )
        picker = (
            '<div class="card" style="max-width:420px;margin:40px auto;text-align:center;">'
            '<h2 style="margin-bottom:12px;">🧮 재고 실사</h2>'
            '<p style="color:#888;font-size:13px;margin-bottom:16px;">실사할 지점을 선택하세요.</p>'
            '<form method="get" action="/daily-stocktake">'
            f'<select name="filter_branch" style="margin-bottom:12px;">{branch_options}</select>'
            '<br><button class="btn" type="submit">선택</button>'
            '<a href="/master/daily-stocktake" style="display:inline-block;margin-left:8px;padding:10px 14px;background:#eee;border-radius:8px;font-size:13px;text-decoration:none;color:#555;">결과 보기</a>'
            "</form></div>"
        )
        return HTMLResponse(render_page(picker, user, "daily-stocktake"))

    # 저장 내역 + 라인 조회
    save = None
    line_map = {}
    conn = get_conn()
    try:
        save = conn.execute(
            "SELECT * FROM daily_stocktake_saves WHERE branch_code=? AND count_date=?",
            (target_branch, sel_date_str)
        ).fetchone()
        if save:
            for l in conn.execute(
                "SELECT * FROM daily_stocktake_lines WHERE save_id=?",
                (save["id"],)
            ).fetchall():
                line_map[str(l["item_code"])] = l
    finally:
        conn.close()

    items, excluded_count = _daily_stocktake_items(target_branch)

    # 마감 상태 — 마감된 실사는 입력·저장·마감 모두 불가 (서버에서도 강제)
    is_closed = bool(save and (save["status"] or "open") == "closed")
    page_can_write = not is_closed

    # 거래처/품류 필터 옵션 (필터 전 전체 품목 기준)
    def _opts(values, current, none_label):
        vals = sorted({v for v in values if v})
        has_none = any(not v for v in values)
        out = f'<option value="">전체</option>'
        if has_none:
            sel = "selected" if current == "__none__" else ""
            out += f'<option value="__none__" {sel}>{none_label}</option>'
        for v in vals:
            sel = "selected" if current == v else ""
            out += f'<option value="{_html.escape(v)}" {sel}>{_html.escape(v)}</option>'
        return out

    all_suppliers = [it["supplier"] for it in items]
    all_categories = [it["category"] for it in items]
    vendor_options = _opts(all_suppliers, vendor, "(미등록)")
    category_options = _opts(all_categories, category, "(미등록)")

    def _match(val, flt):
        if not flt:
            return True
        if flt == "__none__":
            return not val
        return val == flt

    filtered_items = [
        it for it in items
        if _match(it["supplier"], vendor) and _match(it["category"], category)
    ]

    def _fmt_num(v):
        return "-" if v is None else str(v)

    def _diff_html(d):
        if d is None:
            return '<td class="dst-diff" style="font-weight:bold;color:#888;">-</td>'
        color = "#22C55E" if d == 0 else ("#EF4444" if d < 0 else "#F59E0B")
        txt = ("+" if d > 0 else "") + str(d)
        return f'<td class="dst-diff" style="font-weight:bold;color:{color};">{txt}</td>'

    rows_html = ""
    for it in filtered_items:
        code = it["item_code"]
        line = line_map.get(code)
        if line is not None:
            # 저장된 라인: 스냅샷 값 + 저장된 실사 수량
            qr_disp = _fmt_num(line["qr_qty"])
            ups_val = line["ups_qty"]
            ups_disp = _fmt_num(ups_val)
            ups_attr = "" if ups_val is None else str(ups_val)
            loc_vals = [_dst_line_get(line, "loc1_qty"), _dst_line_get(line, "loc2_qty"),
                        _dst_line_get(line, "loc3_qty")]
            cv = line["counted_qty"]  # 실사 수량 칸 = 최종 실사 수량
            badge = ' <span style="font-size:10px;color:#1E40AF;background:#EFF6FF;padding:1px 5px;border-radius:8px;">스냅샷</span>'
        else:
            qr_disp = _fmt_num(it["qr_qty"])
            ups_val = it["ups"]
            ups_disp = _fmt_num(ups_val)
            ups_attr = "" if ups_val is None else str(ups_val)
            cv = None
            loc_vals = [None, None, None]
            badge = (' <span style="font-size:10px;color:#166534;background:#F0FDF4;padding:1px 5px;border-radius:8px;">현재값</span>'
                     if save else "")
        if ups_val is None:
            badge += ' <span style="font-size:10px;color:#92400E;background:#FFFBEB;padding:1px 5px;border-radius:8px;">UPS 없음</span>'
        val_attr = "" if cv is None else f' value="{cv}"'
        dis_attr = "" if page_can_write else " disabled"
        loc_html = ""
        for _li in range(3):
            _lv = loc_vals[_li]
            _lv_attr = "" if _lv is None else f' value="{_lv}"'
            loc_html += (
                f'<td><input type="number" min="0" class="dst-loc" '
                f'data-code="{_html.escape(code)}" data-loc="{_li + 1}"{_lv_attr}{dis_attr} '
                'oninput="dstLocInput(this)" placeholder="위치" '
                'style="width:100%;padding:4px;border:1px solid #ccc;border-radius:6px;"></td>'
            )
        rows_html += (
            "<tr>"
            f"<td>{_html.escape(str(target_branch))}</td>"
            f"<td>{_html.escape(str(it['item_name'] or ''))}</td>"
            f"<td>{_html.escape(code)}</td>"
            f"<td>{qr_disp}</td>"
            f"<td>{ups_disp}{badge}</td>"
            + loc_html
            + f'<td><input type="number" min="0" class="dst-input" '
            f'data-code="{_html.escape(code)}" data-ups="{ups_attr}"{val_attr}{dis_attr} '
            'placeholder="실사" oninput="dstUpdateDiff(this)" '
            'style="width:100%;padding:4px;border:1px solid #ccc;border-radius:6px;"></td>'
            '<td class="dst-diff" style="font-weight:bold;color:#888;">-</td>'
            + _sc_adjust_cell(target_branch, code, page_can_write)
            + "</tr>"
        )

    # 저장됐지만 현재 inventory에 없는 품목 (삭제/미등록) — 읽기 전용으로 표시
    # 필터로 숨겨진 품목까지 '삭제된 품목'으로 붙지 않도록 필터 적용 전 전체 대상(items) 기준으로 판정
    eligible_codes = {it["item_code"] for it in items}
    for code, line in line_map.items():
        if code in eligible_codes:
            continue
        rows_html += (
            "<tr style=\"background:#F9FAFB;color:#888;\">"
            f"<td>{_html.escape(str(target_branch))}</td>"
            f"<td>{_html.escape(str(line['item_name'] or ''))} <span style=\"font-size:10px;\">(삭제된 품목)</span></td>"
            f"<td>{_html.escape(code)}</td>"
            f"<td>{_fmt_num(line['qr_qty'])}</td>"
            f"<td>{_fmt_num(line['ups_qty'])}</td>"
            + "<td>-</td><td>-</td><td>-</td>"
            f"<td>{_fmt_num(line['counted_qty'])}</td>"
            + _diff_html(line["diff_qty"])
            + "<td>-</td>"
            + "</tr>"
        )

    if not rows_html:
        rows_html = (
            '<tr><td colspan="11" style="text-align:center;padding:24px;color:#888;">'
            "표시할 품목이 없습니다 (소모품 제외 inventory 등록 품목 기준)</td></tr>"
        )

    # 필터 폼
    branch_select_html = ""
    if is_master_user:
        branch_options = '<option value="">-- 지점 선택 --</option>'
        for b in get_branches():
            sel = "selected" if target_branch == b["branch_code"] else ""
            branch_options += (
                f'<option value="{_html.escape(str(b["branch_code"]))}" {sel}>'
                f'{_html.escape(str(b["branch_name"]))}</option>'
            )
        branch_select_html = (
            '<div style="flex:1;min-width:140px;max-width:220px;">'
            '<label style="font-size:12px;color:#888;">지점</label>'
            f'<select name="filter_branch" style="margin-top:4px;">{branch_options}</select>'
            "</div>"
        )
    filter_html = (
        '<form method="get" action="/daily-stocktake" style="margin-bottom:16px;">'
        '<div style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;">'
        + branch_select_html
        + '<div style="flex:1;min-width:130px;max-width:170px;">'
        '<label style="font-size:12px;color:#888;">날짜</label>'
        f'<input type="date" name="date" value="{sel_date_str}" max="{today_str}" style="margin-top:4px;">'
        "</div>"
        '<div style="flex:1;min-width:120px;max-width:180px;">'
        '<label style="font-size:12px;color:#888;">거래처</label>'
        f'<select name="vendor" style="margin-top:4px;">{vendor_options}</select>'
        "</div>"
        '<div style="flex:1;min-width:110px;max-width:160px;">'
        '<label style="font-size:12px;color:#888;">품류</label>'
        f'<select name="category" style="margin-top:4px;">{category_options}</select>'
        "</div>"
        '<button class="btn" type="submit">조회</button>'
        '<a href="/daily-stocktake" style="padding:10px 14px;background:#eee;'
        'border-radius:8px;font-size:13px;text-decoration:none;color:#555;">초기화</a>'
        "</div></form>"
    )

    notices_html = ""
    notice_style = 'class="card" style="font-size:12px;margin-bottom:12px;'
    if is_closed:
        closed_at_txt = _html.escape(str(save["closed_at"] or "-"))
        closed_by_txt = _html.escape(str(save["closed_by"] or "-"))
        reopen_btn = ""
        if is_master_user:
            reopen_btn = (
                '<button class="btn" type="button" style="margin-left:8px;background:#B45309;" '
                f'onclick="dstReopen(\'{_html.escape(str(target_branch))}\', \'{sel_date_str}\')">마감 해제</button>'
            )
        notices_html += (
            f'<div {notice_style}color:#7F1D1D;background:#FEF2F2;font-weight:bold;">'
            f'🔒 마감됨 — 담당자 {_html.escape(str(save["closer_name"] or "-"))} · '
            f'마감자 {closed_by_txt} · 마감시각 {closed_at_txt}. 마감 후에는 수정할 수 없습니다.'
            + reopen_btn + "</div>"
        )
    elif save:
        notices_html += (
            f'<div {notice_style}color:#1E40AF;background:#EFF6FF;">'
            f'💾 저장된 실사 기록 있음 — 담당자 {_html.escape(str(save["closer_name"] or "-"))} · '
            f'저장자 {_html.escape(str(save["saved_by"] or "-"))} · '
            f'{_html.escape(str(save["saved_at"] or "-"))}. '
            '빈 칸으로 저장하면 기존 값이 유지됩니다.</div>'
        )
    if is_master_user:
        notices_html += (
            f'<div {notice_style}color:#475569;background:#F8FAFC;">'
            "마스터 계정으로 실사할 지점을 선택한 뒤 입력·저장할 수 있습니다. "
            '<a href="/master/daily-stocktake" style="color:#1E2761;font-weight:bold;">→ 지점별 실사 결과 보기</a></div>'
        )

    script = """
    <script>
      function dstRowTotal(tr) {
        var mi = tr.querySelector('.dst-input');
        if (!mi || mi.value === '') return null;
        var v = parseInt(mi.value, 10);
        return isNaN(v) ? null : v;
      }
      function dstLocSum(tr) {
        var sum = 0, any = false;
        tr.querySelectorAll('.dst-loc').forEach(function(li) {
          if (li.value !== '') { var lv = parseInt(li.value, 10); if (!isNaN(lv)) { sum += lv; any = true; } }
        });
        return any ? sum : null;
      }
      function dstUpdateDiff(inp) {
        var tr = inp.closest('tr');
        var cell = tr.querySelector('.dst-diff');
        var ups = inp.getAttribute('data-ups') || (tr.querySelector('.dst-input') ? tr.querySelector('.dst-input').getAttribute('data-ups') : '');
        var total = dstRowTotal(tr);
        if (total === null || ups === '') {
          cell.textContent = '-';
          cell.style.color = '#888';
          return;
        }
        var diff = total - parseInt(ups, 10);
        if (isNaN(diff)) {
          cell.textContent = '-';
          cell.style.color = '#888';
          return;
        }
        cell.textContent = (diff > 0 ? '+' : '') + diff;
        cell.style.color = diff === 0 ? '#22C55E' : (diff < 0 ? '#EF4444' : '#F59E0B');
      }

      // 위치 칸 입력 → 실사 수량 칸에 위치 합계를 자동 입력 (기존 수동값은 백업 후 복원)
      function dstLocInput(inp) {
        var tr = inp.closest('tr');
        var mi = tr ? tr.querySelector('.dst-input') : null;
        if (mi) {
          var sum = dstLocSum(tr);
          if (sum !== null) {
            if (mi.getAttribute('data-manual-bak') === null) mi.setAttribute('data-manual-bak', mi.value);
            mi.value = String(sum);
          } else if (mi.getAttribute('data-manual-bak') !== null) {
            mi.value = mi.getAttribute('data-manual-bak');
            mi.removeAttribute('data-manual-bak');
          }
        }
        dstUpdateDiff(inp);
      }
      var dstDirty = false;
      var dstDraftCodes = {};
      var dstDraftTimer = null;
      var dstLastApplied = {};
      document.addEventListener('input', function(e) {
        if (e.target && (e.target.classList.contains('dst-input') || e.target.classList.contains('dst-loc'))) {
          dstDirty = true;
          var code = e.target.getAttribute('data-code');
          if (code) { dstDraftCodes[code] = true; dstScheduleDraft(); }
        }
      });

      // 실시간 입력 드래프트: 저장 전 입력값을 다른 사용자에게 실시간 공유
      function dstScheduleDraft() {
        clearTimeout(dstDraftTimer);
        dstDraftTimer = setTimeout(dstSendDraft, 1200);
      }
      function dstRowValues(code) {
        var mi = document.querySelector('.dst-input[data-code="' + code + '"]');
        if (!mi) return null;
        var tr = mi.closest('tr');
        var l = [];
        tr.querySelectorAll('.dst-loc').forEach(function(li) {
          var v = li.value.trim();
          l.push(v === '' ? null : parseInt(v, 10));
        });
        while (l.length < 3) l.push(null);
        var mv = mi.value.trim();
        return { m: (mv === '' ? null : parseInt(mv, 10)), l: l };
      }
      async function dstSendDraft() {
        if (DST_PRESENCE !== '1') return;
        var codes = Object.keys(dstDraftCodes);
        if (!codes.length) return;
        var items = {};
        codes.forEach(function(code) {
          var v = dstRowValues(code);
          if (v) items[code] = v;
        });
        try {
          var res = await fetch('/api/daily-stocktake/draft', {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
              branch_code: DST_BRANCH, date: '__DST_DATE__',
              name: dstPresenceName(), items: items
            })
          });
          if (res.ok) { codes.forEach(function(c) { delete dstDraftCodes[c]; }); }
        } catch (e) {}
      }
      async function dstClearDraft() {
        if (DST_PRESENCE !== '1') return;
        try {
          await fetch('/api/daily-stocktake/draft', {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
              branch_code: DST_BRANCH, date: '__DST_DATE__', clear: true
            })
          });
        } catch (e) {}
      }
      function dstApplyDraftVal(el, val) {
        if (!el || document.activeElement === el) return;
        el.value = (val === null || val === undefined) ? '' : String(val);
      }
      async function dstDraftPoll() {
        if (DST_PRESENCE !== '1') return;
        try {
          var res = await fetch('/api/daily-stocktake/draft?branch_code='
            + encodeURIComponent(DST_BRANCH) + '&date=' + encodeURIComponent('__DST_DATE__')
            + '&login_id=' + encodeURIComponent('__DST_LOGIN__'));
          var d = await res.json();
          if (!res.ok || !d.ok) return;
          var drafts = d.drafts || {};
          Object.keys(drafts).forEach(function(lid) {
            var items = (drafts[lid] && drafts[lid].items) || {};
            Object.keys(items).forEach(function(code) {
              var it = items[code] || {};
              var key = lid + '|' + code;
              if (!it.ts || it.ts <= (dstLastApplied[key] || '')) return;
              dstLastApplied[key] = it.ts;
              var mi = document.querySelector('.dst-input[data-code="' + code + '"]');
              if (!mi) return;
              var tr = mi.closest('tr');
              dstApplyDraftVal(mi, it.m);
              var locs = tr.querySelectorAll('.dst-loc');
              for (var i = 0; i < locs.length && i < 3; i++) {
                dstApplyDraftVal(locs[i], it.l ? it.l[i] : null);
              }
              dstUpdateDiff(mi);
            });
          });
        } catch (e) {}
      }

      function dstCollect() {
        var closerEl = document.getElementById('dstCloser');
        var closer = closerEl ? closerEl.value.trim() : '';
        if (closer === '') {
          alert('실사 담당자 이름을 입력해주세요. (필수)');
          if (closerEl) closerEl.focus();
          return null;
        }
        var counts = {};
        document.querySelectorAll('.dst-input').forEach(function(inp) {
          if (inp.value !== '') { counts[inp.getAttribute('data-code')] = inp.value; }
        });
        var locs = {};
        document.querySelectorAll('.dst-loc').forEach(function(inp) {
          if (inp.value === '') return;
          var code = inp.getAttribute('data-code');
          var idx = parseInt(inp.getAttribute('data-loc'), 10) - 1;
          if (!locs[code]) locs[code] = ['', '', ''];
          if (idx >= 0 && idx < 3) locs[code][idx] = inp.value;
        });
        var branchEl = document.querySelector('select[name="filter_branch"]');
        var payload = {
          date: '__DST_DATE__',
          closer_name: closer,
          counts: counts,
          locs: locs
        };
        if (branchEl && branchEl.value) payload.branch_code = branchEl.value;
        return payload;
      }

      async function dstSubmit() {
        var payload = dstCollect();
        if (!payload) return;
        var filled = Object.keys(payload.counts).length + Object.keys(payload.locs || {}).length;
        if (filled === 0) {
          alert('실사 수량(수동 또는 위치)이 입력된 상품이 없습니다.');
          return;
        }
        try {
          var res = await fetch('/daily-stocktake/save', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
          });
          var data = await res.json();
          if (!res.ok) {
            alert(data.detail || '저장에 실패했습니다.');
            return;
          }
          alert(data.message || '저장되었습니다.');
          dstClearDraft();
          location.reload();
        } catch (e) {
          alert('오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
        }
      }

      function dstEsc(s) {
        return String(s == null ? '' : s).replace(/[&<>"']/g, function(c) {
          return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
        });
      }

      function dstShowMissingConfirm(missing) {
        var body = document.getElementById('dstMissingBody');
        var msg = document.getElementById('dstMissingMsg');
        if (!body || !msg) return;
        msg.textContent = '입력하지 않은 ' + missing.length + '개 품목을 0으로 입력하고 마감하시겠습니까?';
        var html = '';
        missing.forEach(function(m) {
          var zd = (m.zero_diff === null || m.zero_diff === undefined) ? '오차 없음' : String(m.zero_diff);
          html += '<tr>'
            + '<td>' + dstEsc(m.item_name) + '</td>'
            + '<td>' + dstEsc(m.item_code) + '</td>'
            + '<td style="text-align:right;">' + (m.ups_qty === null || m.ups_qty === undefined ? '-' : dstEsc(m.ups_qty)) + '</td>'
            + '<td style="text-align:right;">' + dstEsc(zd) + '</td>'
            + '</tr>';
        });
        body.innerHTML = html;
        document.getElementById('dstMissingOverlay').style.display = 'flex';
      }

      function dstHideMissingConfirm() {
        var ov = document.getElementById('dstMissingOverlay');
        if (ov) ov.style.display = 'none';
      }

      async function dstClose(confirmZero) {
        var payload = dstCollect();
        if (!payload) return;
        payload.confirm_zero = !!confirmZero;
        try {
          var res = await fetch('/daily-stocktake/close', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify(payload)
          });
          var data = await res.json();
          if (!res.ok) {
            alert(data.detail || '마감에 실패했습니다.');
            return;
          }
          if (data.needs_confirm) {
            dstShowMissingConfirm(data.missing || []);
            return;
          }
          dstHideMissingConfirm();
          alert(data.message || '마감되었습니다.');
          dstClearDraft();
          location.reload();
        } catch (e) {
          alert('오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
        }
      }

      async function dstReopen(branch, dateStr) {
        if (!confirm('마감을 해제하면 다시 수정할 수 있습니다. 해제하시겠습니까?')) return;
        try {
          var res = await fetch('/daily-stocktake/reopen', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({branch_code: branch, date: dateStr})
          });
          var data = await res.json();
          if (!res.ok) {
            alert(data.detail || '마감 해제에 실패했습니다.');
            return;
          }
          alert(data.message || '마감이 해제되었습니다.');
          location.reload();
        } catch (e) {
          alert('오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
        }
      }

      window.addEventListener('load', function() {
        document.querySelectorAll('.dst-input, .dst-loc').forEach(function(inp) {
          if (inp.value !== '') dstUpdateDiff(inp);
        });
      });

      // ── 동시 편집 presence (쓰기 가능 + 미마감일 때만) ──
      var DST_PRESENCE = '__DST_PRESENCE__';
      var DST_SAVE_AT = '__DST_SAVE_AT__';
      var DST_BRANCH = '__DST_BRANCH__';
      function dstPresenceName() {
        var el = document.getElementById('dstCloser');
        return (el && el.value.trim()) ? el.value.trim() : '__DST_LOGIN__';
      }
      function dstPresenceRender(users) {
        var box = document.getElementById('dstPresence');
        if (!box) return;
        if (!users || !users.length) { box.innerHTML = ''; return; }
        var html = '<div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12px;'
          + 'color:#1E40AF;background:#EFF6FF;border:1px solid #BFDBFE;border-radius:8px;padding:6px 10px;">'
          + '<span style="font-weight:bold;">✏️ 지금 기입 중:</span>';
        users.forEach(function(u) {
          var me = (u.login_id === '__DST_LOGIN__') ? ' <span style="color:#888;">(나)</span>' : '';
          html += '<span style="background:#fff;border:1px solid #BFDBFE;border-radius:10px;padding:1px 8px;">'
            + dstEsc(u.display_name || u.login_id) + me + '</span>';
        });
        html += '</div>';
        box.innerHTML = html;
      }
      async function dstPresenceBeat() {
        if (DST_PRESENCE !== '1') return;
        try {
          await fetch('/api/presence', {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({page: 'daily-stocktake', scope_key: '__DST_SCOPE__',
                                  name: dstPresenceName()})
          });
        } catch (e) {}
      }
      async function dstPresencePoll() {
        if (DST_PRESENCE !== '1') return;
        try {
          var res = await fetch('/api/presence?page=daily-stocktake&scope_key='
            + encodeURIComponent('__DST_SCOPE__'));
          var data = await res.json();
          if (res.ok) dstPresenceRender(data.users || []);
        } catch (e) {}
      }
      // 다른 사용자가 저장하면 자동 반영 — 입력 중(dirty)이면 알림만 표시
      async function dstSyncPoll() {
        if (DST_PRESENCE !== '1') return;
        try {
          var res = await fetch('/api/daily-stocktake/status?branch_code='
            + encodeURIComponent(DST_BRANCH) + '&date=' + encodeURIComponent('__DST_DATE__'));
          var d = await res.json();
          if (!res.ok || !d.ok) return;
          var remote = d.saved_at || '';
          if (remote && remote !== DST_SAVE_AT) {
            if (!dstDirty) { location.reload(); return; }
            var b = document.getElementById('dstPresence');
            if (b && !document.getElementById('dstSyncNote')) {
              var n = document.createElement('div');
              n.id = 'dstSyncNote';
              n.style.cssText = 'margin-top:6px;color:#B45309;font-weight:bold;';
              n.innerHTML = '⚠️ 다른 사용자가 저장했습니다. <a href="javascript:location.reload()" style="color:#1E2761;">새로고침</a>';
              b.appendChild(n);
            }
            DST_SAVE_AT = remote;
          }
        } catch (e) {}
      }
      if (DST_PRESENCE === '1') {
        dstPresenceBeat(); dstPresencePoll(); dstSyncPoll(); dstDraftPoll();
        setInterval(dstPresenceBeat, 20000);
        setInterval(dstPresencePoll, 20000);
        setInterval(dstSyncPoll, 20000);
        setInterval(dstDraftPoll, 5000);
      }
    </script>
    """.replace("__DST_DATE__", sel_date_str).replace("__DST_PRESENCE__", "1" if (page_can_write and not is_closed) else "0").replace("__DST_SCOPE__", _html.escape(str(target_branch) + "|" + sel_date_str)).replace("__DST_LOGIN__", _html.escape(str(user.get("login_id") or ""))).replace("__DST_SAVE_AT__", _html.escape(str(save["saved_at"] or "") if save else "")).replace("__DST_BRANCH__", _html.escape(str(target_branch)))


