def _sc_setting_on(key: str) -> bool:
    """system_settings 값이 'on'일 때만 True (없으면 False = 기본 꺼짐)"""
    conn = get_conn()
    row = conn.execute("SELECT value FROM system_settings WHERE key=?", (key,)).fetchone()
    conn.close()
    return bool(row and str(row["value"]).strip().lower() == "on")


