@app.post("/stock-closing/notify-toggle-branch-all")
async def stock_closing_notify_toggle_branch_all(request: Request, session_token: str = Cookie(default=None)):
    """지점별 알림 토글 전체 켜기/끄기 — 마스터 전용 (현황 목록에 보이는 지점 전체)"""
    from fastapi import HTTPException
    from fastapi.responses import JSONResponse

    user = get_session(session_token)
    if not user:
        raise HTTPException(status_code=401, detail="로그인이 필요합니다.")
    if not (user.get("role") == "master" or user.get("branch_type") == "hq"):
        raise HTTPException(status_code=403, detail="마스터 계정만 설정할 수 있습니다.")
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="요청 형식이 올바르지 않습니다.")
    enabled = bool(body.get("enabled"))
    value = "on" if enabled else "off"
    codes = []
    for b in get_branches():
        code = b["branch_code"]
        if code in STOCK_CLOSING_EXCLUDED_BRANCHES or "테스트" in str(code) or "테스트" in str(b["branch_name"]):
            continue
        codes.append(str(code))
    conn = get_conn()
    try:
        for code in codes:
            setting_key = "stock_closing_notify_branch:" + code
            row = conn.execute("SELECT value FROM system_settings WHERE key=?", (setting_key,)).fetchone()
            if row:
                conn.execute("UPDATE system_settings SET value=?, updated_at=NOW() WHERE key=?", (value, setting_key))
            else:
                conn.execute("INSERT INTO system_settings (key, value) VALUES (?, ?)", (setting_key, value))
        conn.commit()
    finally:
        conn.close()
    return JSONResponse({"ok": True, "message": "전체 " + str(len(codes)) + "개 지점 알림 " + ("켜짐" if enabled else "꺼짐")})

@app.post("/stock-closing/request")
async def stock_closing_request(request: Request, session_token: str = Cookie(default=None)):
    """재고 마감 제출 요청 팀즈 발송 — 마스터 전용. 발송 스위치가 모두 꺼져 있으면 아무것도 보내지 않는다."""
    from datetime import datetime as _dt
    from fastapi import HTTPException
    from fastapi.responses import JSONResponse

    user = get_session(session_token)
    if not user:
        raise HTTPException(status_code=401, detail="로그인이 필요합니다.")
    if not (user.get("role") == "master" or user.get("branch_type") == "hq"):
        raise HTTPException(status_code=403, detail="마스터 계정만 요청할 수 있습니다.")
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="요청 형식이 올바르지 않습니다.")
    branch_code = str(body.get("branch_code", "")).strip()
    date_str = str(body.get("date", "")).strip()
    try:
        _dt.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        raise HTTPException(status_code=400, detail="날짜 형식이 올바르지 않습니다.")

    branch = next((b for b in get_branches() if b["branch_code"] == branch_code), None)
    if (not branch or branch_code in STOCK_CLOSING_EXCLUDED_BRANCHES
            or "테스트" in str(branch_code) or "테스트" in str(branch["branch_name"])):
        raise HTTPException(status_code=400, detail="요청 대상 지점이 아닙니다.")

    conn = get_conn()
    save = conn.execute(
        "SELECT status FROM stock_closing_saves WHERE branch_code=? AND close_date=?",
        (branch_code, date_str)
    ).fetchone()
    conn.close()
    if save and (save["status"] or "draft") == "closed":
        raise HTTPException(status_code=400, detail="이미 마감이 제출된 지점입니다.")

    branch_on = _sc_setting_on("stock_closing_notify_branch")
    test_on = _sc_setting_on("stock_closing_notify_test")
    if not branch_on and not test_on:
        return JSONResponse({"ok": False, "message": "발송 스위치(지점 발송/테스트 발송)가 모두 꺼져 있어 발송하지 않았습니다."})

    base = str(request.base_url).rstrip("/")
    if base.startswith("http://") and "localhost" not in base and "127.0.0.1" not in base:
        base = "https://" + base[len("http://"):]
    link = base + "/stock-closing?date=" + date_str
    title = "📦 재고 마감 제출 요청"
    msg = f"{branch['branch_name']} {date_str} 재고 마감이 아직 제출되지 않았습니다. 실사 수량을 입력하고 마감해주세요."
    sent_by = "stock_closing_request_by_" + str(user.get("login_id") or "")

    results = []
    if branch_on:
        if not _sc_branch_on(branch_code):
            results.append("지점 발송: 이 지점의 알림 토글이 꺼져 있어 보내지 않았습니다")
        else:
            ok, detail = send_teams_notification(branch_code, title, msg, link, "재고 마감 열기", sent_by)
            results.append("지점 발송: " + ("성공" if ok else "실패(" + str(detail)[:80] + ")"))
    if test_on:
        ok, detail = send_teams_notification(
            STOCK_CLOSING_TEST_BRANCH_CODE, "[테스트] " + title,
            "[테스트 발송 — 대상: " + str(branch["branch_name"]) + "] " + msg,
            link, "재고 마감 열기", sent_by
        )
        results.append("테스트 발송: " + ("성공" if ok else "실패(" + str(detail)[:80] + ")"))
    return JSONResponse({"ok": True, "message": " / ".join(results)})

def _sc_base_url(request: Request) -> str:
    base = str(request.base_url).rstrip("/")
    if base.startswith("http://") and "localhost" not in base and "127.0.0.1" not in base:
        base = "https://" + base[len("http://"):]
    return base


def _sc_missing_branches(date_str: str) -> list:
    """해당 날짜 재고 마감이 마감 완료가 아닌 지점(미제출/임시저장). 제외 지점·테스트 지점은 뺀다."""
    conn = get_conn()
    saves = conn.execute(
        "SELECT branch_code, status FROM stock_closing_saves WHERE close_date=?", (date_str,)
    ).fetchall()
    conn.close()
    status_map = {s["branch_code"]: (s["status"] or "draft") for s in saves}
    missing = []
    for b in get_branches():
        code = b["branch_code"]
        if code in STOCK_CLOSING_EXCLUDED_BRANCHES or "테스트" in str(code) or "테스트" in str(b["branch_name"]):
            continue
        st = status_map.get(code, "none")
        if st != "closed":
            missing.append({"code": code, "name": b["branch_name"], "status": st})
    return missing


STOCK_CLOSING_MAIL_TO = "hs.yu@petdoc.co.kr"


def _sc_mismatch_branches(date_str: str) -> list:
    """해당 날짜 마감 저장 건 중 오차(mismatch_count)가 있는 지점 목록."""
    conn = get_conn()
    rows = conn.execute(
        "SELECT branch_code, mismatch_count FROM stock_closing_saves "
        "WHERE close_date=? AND COALESCE(mismatch_count,0)>0", (date_str,)
    ).fetchall()
    conn.close()
    name_of = {b["branch_code"]: b["branch_name"] for b in get_branches()}
    out = []
    for r in rows:
        cnt = int(r["mismatch_count"] or 0)
        if cnt <= 0:
            continue
        out.append({"code": r["branch_code"],
                    "name": name_of.get(r["branch_code"], r["branch_code"]),
                    "count": cnt})
    return out


def _sc_run_reminder(date_str: str, base_url: str, mode: str, sent_by: str) -> dict:
    """미제출 지점 알림 + 오차(불일치) 지점 알림. mode='auto'는 자동 발송 스위치 설정을 따르고,
    mode='test'는 스위치와 무관하게 테스트 채널(+테스트 메일)로만 보낸다.
    오차 알림은 테스트 채널+테스트 메일 요약 + 지점 발송/불일치 발송/지점별 알림이 모두 켜진 지점 채널로도 발송."""
    missing = _sc_missing_branches(date_str)
    mismatch = _sc_mismatch_branches(date_str)
    if mode == "test":
        branch_on, test_on = False, True
        mis_on = True
    else:
        branch_on = _sc_setting_on("stock_closing_notify_branch")
        test_on = _sc_setting_on("stock_closing_notify_test")
        mis_on = _sc_setting_on("stock_closing_notify_mismatch")
    result = {
        "date": date_str, "mode": mode, "missing": [m["name"] for m in missing],
        "mismatch": [m["name"] for m in mismatch],
        "branch_sent": 0, "branch_failed": [], "test_sent": None, "mail_sent": None,
        "mismatch_sent": None, "mismatch_mail_sent": None,
        "mismatch_branch_sent": 0, "mismatch_branch_failed": [],
    }
    if not missing and not mismatch:
        return result
    status_link = base_url + "/stock-closing/status?date=" + date_str
    title = "📦 재고 마감 제출 요청"

    # 오차(불일치) 알림 — auto 모드에서 '불일치 발송' 스위치가 켜져 있으면 테스트 채널+테스트 메일로만
    if mode == "auto" and mis_on and mismatch:
        mlines = [date_str + " 재고 마감 오차(불일치) 알림", "",
                  "오차 건수가 있는 지점 " + str(len(mismatch)) + "곳:"]
        for m in mismatch:
            mlines.append("- " + str(m["name"]) + " (오차 " + str(m["count"]) + "건)")
        mlines += ["", "재고 마감 현황: " + status_link]
        mbody = "\n".join(mlines)
        ok, detail = send_teams_notification(
            STOCK_CLOSING_TEST_BRANCH_CODE, "📦 재고 마감 오차 알림",
            mbody, status_link, "재고 마감 현황 열기", sent_by
        )
        result["mismatch_sent"] = bool(ok)
        if not ok:
            result["mismatch_detail"] = str(detail)[:80]
        try:
            res = send_email(
                STOCK_CLOSING_MAIL_TO,
                "재고 마감 오차 (" + date_str + ")",
                mbody
            )
            mail_ok = res[0] if isinstance(res, tuple) else bool(res)
            mail_detail = res[1] if (isinstance(res, tuple) and len(res) > 1) else ""
        except Exception as e:
            mail_ok, mail_detail = False, str(e)
        result["mismatch_mail_sent"] = bool(mail_ok)
        if not mail_ok:
            result["mismatch_mail_detail"] = str(mail_detail)[:80]

    # 불일치 지점 채널 발송 — 지점 발송+불일치 발송 스위치와 지점별 알림이 모두 켜진 경우만 (auto 모드)
    if mode == "auto" and branch_on and mis_on and mismatch:
        sc_enabled = _sc_branch_on_set()
        for m in mismatch:
            if str(m["code"]) not in sc_enabled:
                continue
            mmsg = (str(m["name"]) + " " + date_str + " 재고 마감 오차(불일치) "
                    + str(m["count"]) + "건이 있습니다. 재고 마감 화면에서 확인해주세요.")
            ok2, detail2 = send_teams_notification(
                m["code"], "📦 재고 마감 오차 알림", mmsg,
                base_url + "/stock-closing?date=" + date_str, "재고 마감 열기", sent_by
            )
            if ok2:
                result["mismatch_branch_sent"] += 1
            else:
                result["mismatch_branch_failed"].append(str(m["name"]) + "(" + str(detail2)[:60] + ")")
    if branch_on:
        link = base_url + "/stock-closing?date=" + date_str
        enabled_branches = _sc_branch_on_set()
        for m in missing:
            if str(m["code"]) not in enabled_branches:
                continue
            msg = str(m["name"]) + " " + date_str + " 재고 마감이 아직 제출되지 않았습니다. 실사 수량을 입력하고 마감해주세요."
            ok, detail = send_teams_notification(m["code"], title, msg, link, "재고 마감 열기", sent_by)
            if ok:
                result["branch_sent"] += 1
            else:
                result["branch_failed"].append(str(m["name"]) + "(" + str(detail)[:60] + ")")
    if test_on:
        prefix = "[테스트] " if mode == "test" else "[테스트 채널] "
        names = ", ".join(str(m["name"]) for m in missing)
        msg = date_str + " 재고 마감 미제출 지점 " + str(len(missing)) + "곳: " + names
        # test 모드(버튼 테스트)에서는 오차 현황도 함께 보여준다. auto 모드의 오차는 위 전용 알림이 담당한다.
        if mode == "test" and mismatch:
            mnames = ", ".join(str(m["name"]) + "(" + str(m["count"]) + "건)" for m in mismatch)
            msg += "\n오차 건수 있는 지점 " + str(len(mismatch)) + "곳: " + mnames
        ok, detail = send_teams_notification(
            STOCK_CLOSING_TEST_BRANCH_CODE, prefix + title, msg, status_link, "재고 마감 현황 열기", sent_by
        )
        result["test_sent"] = bool(ok)
        if not ok:
            result["test_detail"] = str(detail)[:80]

        # 테스트 메일 (기존 send_email 사용)
        lines = [date_str + " 재고 마감 미제출 지점 " + str(len(missing)) + "곳", ""]
        for m in missing:
            lines.append("- " + str(m["name"]) + " (" + ("임시저장" if m["status"] == "draft" else "미제출") + ")")
        if mode == "test" and mismatch:
            lines += ["", "오차 건수 있는 지점 " + str(len(mismatch)) + "곳"]
            for m in mismatch:
                lines.append("- " + str(m["name"]) + " (오차 " + str(m["count"]) + "건)")
        lines += ["", "재고 마감 현황: " + status_link]
        try:
            res = send_email(
                STOCK_CLOSING_MAIL_TO,
                prefix + "재고 마감 미제출 지점 " + str(len(missing)) + "곳 (" + date_str + ")",
                "\n".join(lines)
            )
            mail_ok = res[0] if isinstance(res, tuple) else bool(res)
            mail_detail = res[1] if (isinstance(res, tuple) and len(res) > 1) else ""
        except Exception as e:
            mail_ok, mail_detail = False, str(e)
        result["mail_sent"] = bool(mail_ok)
        if not mail_ok:
            result["mail_detail"] = str(mail_detail)[:80]
    return result


@app.post("/stock-closing/request-test")
async def stock_closing_request_test(request: Request, session_token: str = Cookie(default=None)):
    """제출 요청 테스트 — 발송 스위치와 무관하게 테스트 채널로만 발송 (마스터 전용)"""
    from datetime import datetime as _dt
    from fastapi import HTTPException
    from fastapi.responses import JSONResponse

    user = get_session(session_token)
    if not user:
        raise HTTPException(status_code=401, detail="로그인이 필요합니다.")
    if not (user.get("role") == "master" or user.get("branch_type") == "hq"):
        raise HTTPException(status_code=403, detail="마스터 계정만 사용할 수 있습니다.")
    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="요청 형식이 올바르지 않습니다.")
    branch_code = str(body.get("branch_code", "")).strip()
    date_str = str(body.get("date", "")).strip()
    try:
        _dt.strptime(date_str, "%Y-%m-%d")
    except ValueError:
        raise HTTPException(status_code=400, detail="날짜 형식이 올바르지 않습니다.")
    branch = next((b for b in get_branches() if b["branch_code"] == branch_code), None)
    if not branch:
        raise HTTPException(status_code=400, detail="지점을 찾을 수 없습니다.")

    msg = (str(branch["branch_name"]) + " " + date_str
           + " 재고 마감이 아직 제출되지 않았습니다. 실사 수량을 입력하고 마감해주세요.")
    ok, detail = send_teams_notification(
        STOCK_CLOSING_TEST_BRANCH_CODE, "[테스트] 📦 재고 마감 제출 요청",
        "[테스트 발송 — 대상: " + str(branch["branch_name"]) + "] " + msg,
        _sc_base_url(request) + "/stock-closing?date=" + date_str, "재고 마감 열기",
        "stock_closing_request_test_by_" + str(user.get("login_id") or "")
    )
    text = "테스트 발송 성공 (테스트 채널로만 발송됨)" if ok else "테스트 발송 실패(" + str(detail)[:80] + ")"
    return JSONResponse({"ok": bool(ok), "message": text})


