@app.get("/master/vendor-eval/export")
async def master_vendor_eval_export(session_token: str = Cookie(default=None), branch: str = "", month: str = ""):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)

    query = "SELECT * FROM vendor_evaluation_v2 WHERE 1=1"
    params = []
    if branch:
        query += " AND branch_code = ?"
        params.append(branch)
    if month:
        query += " AND eval_month = ?"
        params.append(month)
    query += " ORDER BY created_at DESC"

    conn = get_conn()
    evaluations = conn.execute(query, params).fetchall()

    import io
    from openpyxl import Workbook
    wb = Workbook()
    ws = wb.active
    assert ws is not None
    ws.title = "거래처평가"
    headers = ["지점", "거래처", "평가월", "문항", "점수", "사유", "총점", "등록자", "등록일시"]
    ws.append(headers)

    for ev in evaluations:
        answers = conn.execute("""
            SELECT a.score, a.comment, c.label
            FROM vendor_evaluation_answer a
            JOIN eval_criteria c ON c.id = a.criteria_id
            WHERE a.evaluation_id = ?
            ORDER BY c.display_order
        """, (ev["id"],)).fetchall()
        if not answers:
            ws.append([ev["branch_name"], ev["vendor_name"], ev["eval_month"], "-", "-", "-",
                       float(ev["total_score"]) if ev["total_score"] is not None else None,
                       ev["evaluated_by"], str(ev["created_at"]) if ev["created_at"] else ""])
        for a in answers:
            ws.append([ev["branch_name"], ev["vendor_name"], ev["eval_month"], a["label"], a["score"], a["comment"],
                       float(ev["total_score"]) if ev["total_score"] is not None else None,
                       ev["evaluated_by"], str(ev["created_at"]) if ev["created_at"] else ""])
    conn.close()

    for col_idx in range(1, len(headers) + 1):
        ws.column_dimensions[chr(64 + col_idx)].width = 18

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)

    filename = f"거래처평가_{branch or '전체'}_{month or '전체'}.xlsx"
    from urllib.parse import quote
    encoded_filename = quote(filename)

    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{encoded_filename}"}
    )


@app.get("/master/vendor-eval/summary", response_class=HTMLResponse)
async def master_vendor_eval_summary(session_token: str = Cookie(default=None), branch: str = "", month: str = ""):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)

    conn = get_conn()

    where_clause = "WHERE 1=1"
    params = []
    if branch:
        where_clause += " AND branch_code = ?"
        params.append(branch)
    if month:
        where_clause += " AND eval_month = ?"
        params.append(month)

    vendor_rows = conn.execute(f"""
        SELECT vendor_name,
               COUNT(*) as cnt,
               ROUND(AVG(total_score), 1) as avg_total
        FROM vendor_evaluation_v2
        {where_clause}
        GROUP BY vendor_name
        ORDER BY avg_total DESC
    """, params).fetchall()

    branch_rows = []
    if not branch:
        month_where = "WHERE 1=1"
        month_params = []
        if month:
            month_where += " AND eval_month = ?"
            month_params.append(month)
        branch_rows = conn.execute(f"""
            SELECT branch_name,
                   COUNT(*) as cnt,
                   ROUND(AVG(total_score), 1) as avg_total
            FROM vendor_evaluation_v2
            {month_where}
            GROUP BY branch_name
            ORDER BY avg_total DESC
        """, month_params).fetchall()
    conn.close()

    vendor_rows_html = ""
    if not vendor_rows:
        vendor_rows_html = '<tr><td colspan="4" style="text-align:center;padding:20px;color:#888;">데이터 없음</td></tr>'
    for i, r in enumerate(vendor_rows, start=1):
        vendor_rows_html += f"""
        <tr>
            <td>{i}</td><td>{r['vendor_name']}</td><td>{r['cnt']}건</td>
            <td><b>{r['avg_total']}</b></td>
        </tr>
        """

    branch_section = ""
    if branch:
        branch_name_disp = next((b["branch_name"] for b in get_branches() if b["branch_code"] == branch), branch)
        branch_section = f"""
        <div class="card">
          <p style="font-size:13px;color:#888;">지점 필터가 적용되어 있어 지점별 비교는 생략됩니다 (현재: {branch_name_disp}).</p>
        </div>
        """
    else:
        branch_rows_html = ""
        if not branch_rows:
            branch_rows_html = '<tr><td colspan="3" style="text-align:center;padding:20px;color:#888;">데이터 없음</td></tr>'
        for r in branch_rows:
            branch_rows_html += f"""
            <tr>
                <td>{r['branch_name']}</td><td>{r['cnt']}건</td>
                <td><b>{r['avg_total']}</b></td>
            </tr>
            """
        branch_section = f"""
        <div class="card">
          <h3 style="font-size:15px;margin-bottom:12px;">지점별 평가 성향 비교</h3>
          <table>
              <thead><tr><th>지점</th><th>평가건수</th><th>총점평균</th></tr></thead>
              <tbody>{branch_rows_html}</tbody>
          </table>
          <p style="font-size:12px;color:#888;margin-top:8px;">
            ※ 총점평균이 낮을수록 그 지점이 거래처를 상대적으로 엄격하게 평가하는 경향입니다.
          </p>
        </div>
        """

    filter_label = []
    if branch:
        branch_name_disp = next((b["branch_name"] for b in get_branches() if b["branch_code"] == branch), branch)
        filter_label.append(f"지점: {branch_name_disp}")
    if month:
        filter_label.append(f"기간: {month}")
    filter_display = f'<p style="color:#888;font-size:13px;margin-bottom:12px;">현재 필터 — {" / ".join(filter_label)}</p>' if filter_label else ""

    content = f"""
    <h2 style="margin-bottom:8px;">📊 거래처 평가 종합분석</h2>
    {filter_display}

    <div class="card">
      <h3 style="font-size:15px;margin-bottom:12px;">거래처별 랭킹 (총점 높은 순)</h3>
      <table>
          <thead><tr><th>순위</th><th>거래처</th><th>평가건수</th><th>총점평균</th></tr></thead>
          <tbody>{vendor_rows_html}</tbody>
      </table>
    </div>

    {branch_section}

    <a href="/master/vendor-eval?branch={branch}&month={month}" style="display:inline-block;margin-top:8px;color:#2563eb;font-size:13px;text-decoration:none;">← 상세 목록으로 돌아가기</a>
    """
    return HTMLResponse(content=render_page(content, user, "vendor-eval"))


@app.get("/master/vendor-master", response_class=HTMLResponse)
async def vendor_master_page(session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "vendor-master"):
        return RedirectResponse(url="/master", status_code=303)

    conn = get_conn()
    vendors = conn.execute("SELECT * FROM vendor_master ORDER BY vendor_name").fetchall()
    conn.close()

    rows_html = ""
    if not vendors:
        rows_html = '<tr><td colspan="3" style="text-align:center;padding:20px;color:#888;">등록된 거래처 없음</td></tr>'
    for v in vendors:
        rows_html += f"""
        <tr>
          <td style="text-align:center;">
            <input type="checkbox" name="selected_ids" value="{v['id']}" class="vm-check" style="width:16px;height:16px;">
          </td>
          <td>{v['vendor_name']}</td>
          <td>{str(v['created_at'])[:10] if v['created_at'] else '-'}</td>
        </tr>
        """

    content = f"""
    <h2 style="margin-bottom:16px;">🏢 거래처 관리</h2>
    <div class="card">
      <h3 style="margin-bottom:8px;">거래처 추가</h3>
      <div style="display:flex;gap:8px;">
        <input type="text" id="newVendorName" placeholder="거래처명 입력" style="flex:1;">
        <button class="btn" type="button" onclick="addVendor()">추가</button>
      </div>
      <div id="addResult" style="margin-top:8px;font-size:13px;"></div>
    </div>
    <div class="card">
      <form method="post" action="/master/vendor-master/delete">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
          <span style="font-size:13px;color:#888;">{len(vendors)}개 거래처</span>
          <div style="display:flex;gap:8px;">
            <button type="button" class="btn" id="vmSelectAllBtn" style="background:#64748B;font-size:12px;padding:6px 12px;">전체선택</button>
            <button type="submit" class="btn btn-red" style="font-size:12px;padding:6px 12px;"
                    onclick="return confirm('선택한 거래처를 삭제할까요? 기존 평가 기록은 유지됩니다.')">선택삭제</button>
          </div>
        </div>
        <table>
          <thead><tr>
            <th style="width:40px;text-align:center;"><input type="checkbox" id="vmAllCheck" style="width:16px;height:16px;"></th>
            <th>거래처명</th><th>등록일</th>
          </tr></thead>
          <tbody>{rows_html}</tbody>
        </table>
      </form>
    </div>
    <script>
      async function addVendor() {{
        const input = document.getElementById('newVendorName');
        const name = input.value.trim();
        if (!name) {{ alert('거래처명을 입력하세요.'); return; }}
        const res = await fetch('/master/vendor-master/add', {{
          method: 'POST',
          headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ vendor_name: name }})
        }});
        const box = document.getElementById('addResult');
        if (res.ok) {{
          box.style.color = '#22C55E';
          box.innerText = '추가되었습니다.';
          setTimeout(() => location.reload(), 800);
        }} else {{
          const err = await res.json();
          box.style.color = '#EF4444';
          box.innerText = '오류: ' + (err.detail || '추가 실패');
        }}
      }}
      (function() {{
        var allCheck = document.getElementById('vmAllCheck');
        var selectBtn = document.getElementById('vmSelectAllBtn');
        function applyAll(checked) {{
          document.querySelectorAll('.vm-check').forEach(function(c) {{ c.checked = checked; }});
          if (allCheck) allCheck.checked = checked;
        }}
        if (allCheck) {{ allCheck.addEventListener('click', function() {{ applyAll(allCheck.checked); }}); }}
        if (selectBtn) {{
          selectBtn.addEventListener('click', function() {{
            var next = !(allCheck && allCheck.checked);
            applyAll(next);
          }});
        }}
      }})();
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "master"))


@app.post("/master/vendor-master/add")
async def vendor_master_add(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    vendor_name = data.get("vendor_name", "").strip()
    if not vendor_name:
        return JSONResponse(status_code=400, content={"detail": "거래처명을 입력하세요."})

    conn = get_conn()
    try:
        conn.execute(
            "INSERT INTO vendor_master (vendor_name) VALUES (?) ON CONFLICT (vendor_name) DO NOTHING",
            (vendor_name,)
        )
        conn.commit()
    finally:
        conn.close()

    return JSONResponse(content={"status": "ok"})


@app.post("/master/vendor-master/delete")
async def vendor_master_delete(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    form = await request.form()
    ids = form.getlist("selected_ids")
    if ids:
        conn = get_conn()
        conn.execute(
            f"DELETE FROM vendor_master WHERE id IN ({','.join('?' for _ in ids)})",
            [int(i) for i in ids]
        )
        conn.commit()
        conn.close()
    return RedirectResponse(url="/master/vendor-master", status_code=303)

@app.get("/survey", response_class=HTMLResponse)
async def survey_list_page(session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user:
        return RedirectResponse(url="/login", status_code=303)
    if user["role"] == "master":
        return RedirectResponse(url="/master/survey", status_code=303)

    branch_code = user["branch_code"]

    conn = get_conn()
    surveys = conn.execute(
        "SELECT * FROM survey WHERE active = TRUE ORDER BY created_at DESC"
    ).fetchall()

    my_responses = conn.execute(
        "SELECT id, survey_id, writer_name, status FROM survey_response WHERE branch_code=?",
        (branch_code,)
    ).fetchall()
    conn.close()

    my_map: Dict[int, list] = {}
    for r in my_responses:
        my_map.setdefault(r["survey_id"], []).append(
            {"id": r["id"], "writer_name": r["writer_name"], "status": r["status"]}
        )

    if not surveys:
        content = """
        <div class="card" style="text-align:center;padding:40px;">
          <div style="font-size:32px;">📋</div>
          <p style="color:#888;margin-top:12px;">진행 중인 설문이 없습니다.</p>
        </div>
        """
        return HTMLResponse(content=render_page(content, user, "survey"))

    cards_html = ""
    for s in surveys:
        my_writers = my_map.get(s["id"], [])
        writer_count = len(my_writers)

        writer_rows_html = ""
        if my_writers:
            for w in my_writers:
                if w["status"] == "resubmit_requested":
                    badge = '<span class="badge-red">⚠️ 재제출요청</span>'
                else:
                    badge = '<span class="badge-green">✅ 완료</span>'
                safe_writer_name = w['writer_name'].replace("'", "")
                writer_rows_html += f"""
                <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #f0f0f0;">
                  <span style="font-size:13px;">{w['writer_name']}</span>
                  <div style="display:flex;gap:8px;align-items:center;">
                    {badge}
                    <a href="/survey/{s['id']}/edit/{w['id']}" class="btn" style="font-size:11px;padding:5px 10px;text-decoration:none;">수정</a>
                    <button class="btn btn-red" style="font-size:11px;padding:5px 10px;" onclick="deleteMyResponse({w['id']}, '{safe_writer_name}')">삭제</button>
                  </div>
                </div>
                """
        else:
            writer_rows_html = '<p style="font-size:12px;color:#888;padding:10px 0;">제출된 응답이 없습니다.</p>'

        new_submit_html = f"""
        <a href="/survey/{s['id']}" class="btn" style="text-decoration:none;font-size:12px;padding:8px 14px;display:inline-block;margin-top:8px;">➕ 새로 작성</a>
        """

        accordion_id = f"sv_acc_{s['id']}"
        summary_badge = f'<span style="font-size:12px;color:#888;margin-left:8px;">제출 {writer_count}건</span>' if writer_count > 0 else '<span style="font-size:12px;color:#888;margin-left:8px;">미제출</span>'

        cards_html += f"""
        <div class="card" style="padding:0;overflow:hidden;">
          <div onclick="toggleSurveyAccordion('{accordion_id}')" style="cursor:pointer;padding:16px;display:flex;justify-content:space-between;align-items:center;">
            <div>
              <span style="font-weight:bold;color:#1E2761;">{s['title']}</span>
              {summary_badge}
            </div>
            <span id="{accordion_id}_toggle" style="font-size:12px;color:#2563eb;white-space:nowrap;">펼치기 ▾</span>
          </div>
          <div id="{accordion_id}" style="display:none;padding:0 16px 16px;border-top:1px solid #eee;">
            <div style="margin-top:8px;">
              {writer_rows_html}
            </div>
            {new_submit_html}
          </div>
        </div>
        """

    content = f"""
    <h2 style="margin-bottom:16px;">📋 설문</h2>
    {cards_html}

    <script>
      function toggleSurveyAccordion(id) {{
        var body = document.getElementById(id);
        var toggle = document.getElementById(id + '_toggle');
        if (!body) return;
        var isOpen = body.style.display !== 'none';
        body.style.display = isOpen ? 'none' : 'block';
        if (toggle) toggle.innerText = isOpen ? '펼치기 ▾' : '접기 ▴';
      }}

      async function deleteMyResponse(responseId, writerName) {{
        if (!confirm(writerName + ' 님이 제출한 응답을 삭제합니다. 되돌릴 수 없습니다. 계속할까요?')) return;
        const res = await fetch('/survey/response/' + responseId + '/delete', {{ method: 'POST' }});
        if (res.ok) {{ location.reload(); }} else {{
          const err = await res.json();
          alert('오류: ' + (err.detail || '삭제 실패'));
        }}
      }}
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "survey"))

@app.get("/survey/{survey_id}", response_class=HTMLResponse)
async def survey_write_page(survey_id: int, session_token: str = Cookie(default=None)):
    user = get_session(session_token)

    conn = get_conn()
    survey = conn.execute("SELECT * FROM survey WHERE id=?", (survey_id,)).fetchone()
    if not survey:
        conn.close()
        return RedirectResponse(url="/survey", status_code=303)

    is_anonymous = bool(survey["is_anonymous"])
    is_public_mode = False
    if not user:
        if not (survey["is_public_access"] or is_anonymous):
            conn.close()
            return RedirectResponse(url="/login", status_code=303)
        is_public_mode = True
    elif user["role"] == "master":
        conn.close()
        return RedirectResponse(url=f"/master/survey/{survey_id}/responses", status_code=303)

    legend_rows = conn.execute(
        "SELECT * FROM survey_score_legend WHERE survey_id=? ORDER BY display_order", (survey_id,)
    ).fetchall()

    section_rows = conn.execute(
        "SELECT * FROM survey_section WHERE survey_id=? ORDER BY display_order", (survey_id,)
    ).fetchall()

    question_rows = conn.execute(
        "SELECT * FROM survey_question WHERE survey_id=? AND active=TRUE ORDER BY display_order", (survey_id,)
    ).fetchall()

    questions_data = []
    for q in question_rows:
        options = conn.execute(
            "SELECT * FROM survey_question_option WHERE question_id=? ORDER BY display_order", (q["id"],)
        ).fetchall()
        questions_data.append({
            "id": q["id"],
            "section_id": q["section_id"],
            "question_text": q["question_text"],
            "description": q["description"] or "",
            "image_url": q["image_url"] or "",
            "link_url": q["link_url"] or "",
            "link_label": q["link_label"] or "",
            "has_options": bool(q["has_options"]),
            "has_text_answer": bool(q["has_text_answer"]),
            "text_answer_label": q["text_answer_label"] or "기타 (서술)",
            "text_answer_required": bool(q["text_answer_required"]),
            "is_multi_select": bool(q["is_multi_select"]),
            "options": [{"value": o["option_value"], "label": o["option_label"]} for o in options]
        })

    branch_options_html = ""
    if is_public_mode and not is_anonymous:
        branches = get_branches(branch_type='branch')
        branch_options_html = '<option value="">지점을 선택하세요</option>'
        for b in branches:
            branch_options_html += f'<option value="{b["branch_code"]}">{b["branch_name"]}</option>'

    conn.close()

    if not questions_data:
        content = """
        <div class="card" style="text-align:center;padding:40px;">
          <div style="font-size:32px;">📝</div>
          <p style="color:#888;margin-top:12px;">등록된 문항이 없습니다. 마스터에게 문항 등록을 요청해주세요.</p>
        </div>
        """
        return HTMLResponse(content=render_page(content, user, "survey") if user else content)

    legend_html = ""
    if legend_rows:
        legend_items = "".join(
            f'<tr><td style="text-align:center;font-weight:bold;">{lg["score_value"]}</td><td>{lg["score_meaning"]}</td></tr>'
            for lg in legend_rows
        )
        legend_html = f"""
        <div class="card">
          <table>
            <thead><tr><th style="width:60px;text-align:center;">점수</th><th>의미</th></tr></thead>
            <tbody>{legend_items}</tbody>
          </table>
        </div>
        """

    intro_html = ""
    if survey["purpose"] or survey["method"]:
        purpose_block = f'<p style="margin-bottom:8px;"><b>진단목적</b><br>{survey["purpose"]}</p>' if survey["purpose"] else ""
        method_block = f'<p><b>진단방법</b><br>{survey["method"]}</p>' if survey["method"] else ""
        intro_html = f"""
        <div class="card" style="max-width:560px;margin:0 auto 16px;">
          {purpose_block}
          {method_block}
        </div>
        """

    questions_js = json.dumps(questions_data, ensure_ascii=False)

    section_order = [(sec["id"], sec["section_name"]) for sec in section_rows]
    section_order.append((None, None))

    global_idx = 0
    question_blocks = ""
    for sec_id, sec_name in section_order:
        sec_questions = [q for q in questions_data if q["section_id"] == sec_id]
        if not sec_questions:
            continue
        if sec_name:
            question_blocks += f'<div class="sv-section-title">📂 {sec_name}</div>'
        for q in sec_questions:
            global_idx += 1
            num = global_idx
            question_text_html = q['question_text'].replace(chr(10), '<br>')
            desc_html = f'<p style="color:#888;font-size:12px;margin-bottom:8px;">{q["description"].replace(chr(10), "<br>")}</p>' if q["description"] else ""
            image_html = f'<img src="{q["image_url"]}" style="max-width:100%;border-radius:8px;margin-bottom:10px;display:block;">' if q.get("image_url") else ""
            link_html = f'<a href="{q["link_url"]}" target="_blank" rel="noopener" style="display:inline-block;margin-bottom:10px;padding:6px 12px;background:#EFF6FF;color:#1E2761;border-radius:6px;font-size:13px;text-decoration:none;">🔗 {q["link_label"] or "링크 열기"}</a>' if q.get("link_url") else ""
            question_blocks += f"""
            <div class="sv-field">
              <label>{num}. {question_text_html}</label>
              {desc_html}
              {image_html}
              {link_html}
              <div id="options_{q['id']}"></div>
              <div id="textwrap_{q['id']}" style="display:{'block' if q['has_text_answer'] else 'none'};">
                <textarea id="text_{q['id']}" placeholder="{q['text_answer_label']}{' (필수)' if q['text_answer_required'] else ' (선택)'}"></textarea>
              </div>
            </div>
            """

    branch_select_html = ""
    if is_public_mode and not is_anonymous:
        branch_select_html = f"""
        <label style="font-size:13px;color:#555;">지점 선택 (필수)</label>
        <select id="publicBranchCode" onchange="checkAllValid()" style="width:100%;padding:10px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;font-size:14px;margin-bottom:16px;">
          {branch_options_html}
        </select>
        """

    writer_field_html = "" if is_anonymous else '<label style="font-size:13px;color:#555;">작성자 이름 (필수)</label><input type="text" id="writerName" placeholder="이름을 입력하세요" oninput="checkAllValid()">'

    inner_content = f"""
    {intro_html}
    <style>
      .sv-legend-card {{ max-width:560px; margin:0 auto 16px; }}
      .sv-card {{ background:#fff; border-radius:12px; padding:20px; max-width:560px; margin:0 auto; box-shadow:0 2px 8px rgba(0,0,0,0.08); }}
      .sv-card h2 {{ font-size:18px; margin-bottom:16px; }}
      .sv-section-title {{ font-weight:bold; font-size:15px; color:#1E2761; margin:20px 0 12px; padding-bottom:6px; border-bottom:2px solid #1E2761; }}
      .sv-field {{ margin-bottom:20px; padding-bottom:16px; border-bottom:1px solid #eee; }}
      .sv-field label {{ display:block; font-weight:bold; margin-bottom:6px; font-size:14px; }}
      .sv-option {{ display:inline-block; border:1px solid #ddd; border-radius:8px; padding:8px 14px; margin:0 6px 6px 0; cursor:pointer; font-size:13px; }}
      .sv-option.selected {{ border-color:#2563eb; background:#eff6ff; color:#2563eb; font-weight:bold; }}
      .sv-card textarea {{ width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; box-sizing:border-box; font-size:14px; min-height:60px; margin-top:8px; }}
      .sv-card input[type="text"] {{ width:100%; padding:10px; border:1px solid #ccc; border-radius:6px; box-sizing:border-box; font-size:14px; margin-bottom:16px; }}
      .sv-card button {{ padding:12px 20px; border:none; border-radius:6px; font-size:15px; cursor:pointer; width:100%; }}
      .sv-btn-submit {{ background:#2563eb; color:#fff; }}
      .sv-btn-submit:disabled {{ background:#ccc; cursor:not-allowed; }}
    </style>
    <div class="sv-legend-card">{legend_html}</div>
    <div class="sv-card">
      <h2>{survey['title']}</h2>
      {branch_select_html}
      {writer_field_html}
      {question_blocks}
      <button class="sv-btn-submit" id="submitBtn" onclick="submitSurvey()" disabled>제출</button>
    </div>

    <script>
      const questionsData = {questions_js};
      const surveyId = {survey_id};
      const isPublicMode = {json.dumps(is_public_mode)};
      const isAnonymous = {json.dumps(is_anonymous)};

      let selected = {{}};
      questionsData.forEach(q => selected[q.id] = q.is_multi_select ? [] : null);

      const draftKey = 'survey_draft_' + surveyId;
      let saveDraftTimer = null;

      function saveDraft() {{
        clearTimeout(saveDraftTimer);
        saveDraftTimer = setTimeout(() => {{
          const draft = {{
            selected: selected,
            texts: {{}},
            writerName: isAnonymous ? '' : (document.getElementById('writerName') ? document.getElementById('writerName').value : ''),
            branchCode: (isPublicMode && !isAnonymous && document.getElementById('publicBranchCode')) ? document.getElementById('publicBranchCode').value : ''
          }};
          questionsData.forEach(q => {{
            if (q.has_text_answer) {{
              const el = document.getElementById('text_' + q.id);
              if (el) draft.texts[q.id] = el.value;
            }}
          }});
          try {{
            localStorage.setItem(draftKey, JSON.stringify(draft));
          }} catch (e) {{}}
        }}, 400);
      }}

      function showDraftBanner() {{
        const card = document.querySelector('.sv-card');
        if (!card) return;
        const banner = document.createElement('div');
        banner.innerText = '📝 임시저장된 답변을 불러왔습니다';
        banner.style.cssText = 'background:#EFF6FF;color:#1E2761;padding:10px 14px;border-radius:8px;font-size:13px;margin-bottom:12px;text-align:center;';
        card.insertBefore(banner, card.firstChild);
      }}

      function restoreDraft() {{
        let raw;
        try {{
          raw = localStorage.getItem(draftKey);
        }} catch (e) {{
          return;
        }}
        if (!raw) return;
        let draft;
        try {{
          draft = JSON.parse(raw);
        }} catch (e) {{
          return;
        }}

        if (draft.selected) {{
          Object.keys(draft.selected).forEach(qid => {{
            selected[qid] = draft.selected[qid];
          }});
        }}
        questionsData.forEach(q => {{
          if (!q.has_options) return;
          const container = document.getElementById('options_' + q.id);
          if (!container) return;
          const val = selected[q.id];
          const opts = container.querySelectorAll('.sv-option');
          opts.forEach((div, i) => {{
            const optVal = q.options[i].value;
            if (q.is_multi_select) {{
              const isSel = Array.isArray(val) && val.includes(optVal);
              div.classList.toggle('selected', isSel);
              div.innerText = (isSel ? '☑ ' : '☐ ') + q.options[i].label;
            }} else {{
              div.classList.toggle('selected', val === optVal);
            }}
          }});
        }});

        if (draft.texts) {{
          Object.keys(draft.texts).forEach(qid => {{
            const el = document.getElementById('text_' + qid);
            if (el) el.value = draft.texts[qid];
          }});
        }}
        if (!isAnonymous && draft.writerName && document.getElementById('writerName')) {{
          document.getElementById('writerName').value = draft.writerName;
        }}
        if (isPublicMode && !isAnonymous && draft.branchCode && document.getElementById('publicBranchCode')) {{
          document.getElementById('publicBranchCode').value = draft.branchCode;
        }}

        showDraftBanner();
      }}

      function renderOptions(q) {{
        if (!q.has_options) return;
        const container = document.getElementById('options_' + q.id);
        q.options.forEach(opt => {{
          const div = document.createElement('div');
          div.className = 'sv-option';
          div.innerText = (q.is_multi_select ? '☐ ' : '') + opt.label;
          div.onclick = () => {{
            if (q.is_multi_select) {{
              const arr = selected[q.id];
              const pos = arr.indexOf(opt.value);
              if (pos >= 0) {{
                arr.splice(pos, 1);
                div.classList.remove('selected');
                div.innerText = '☐ ' + opt.label;
              }} else {{
                arr.push(opt.value);
                div.classList.add('selected');
                div.innerText = '☑ ' + opt.label;
              }}
            }} else {{
              selected[q.id] = opt.value;
              document.querySelectorAll('#options_' + q.id + ' .sv-option').forEach(o => o.classList.remove('selected'));
              div.classList.add('selected');
            }}
            checkAllValid();
            saveDraft();
          }};
          container.appendChild(div);
        }});
      }}

      function checkAllValid() {{
        const writerOk = isAnonymous ? true : document.getElementById('writerName').value.trim().length > 0;
        const branchOk = (isPublicMode && !isAnonymous) ? document.getElementById('publicBranchCode').value !== '' : true;
        const questionsOk = questionsData.every(q => {{
          let optOk = true;
          if (q.has_options) {{
            optOk = q.is_multi_select ? selected[q.id].length > 0 : selected[q.id] !== null;
          }}
          let textOk = true;
          if (q.has_text_answer && q.text_answer_required) {{
            const el = document.getElementById('text_' + q.id);
            textOk = el && el.value.trim().length > 0;
          }}
          return optOk && textOk;
        }});
        document.getElementById('submitBtn').disabled = !(writerOk && branchOk && questionsOk);
      }}

      questionsData.forEach(q => {{
        renderOptions(q);
        const textEl = document.getElementById('text_' + q.id);
        if (textEl) textEl.addEventListener('input', () => {{ checkAllValid(); saveDraft(); }});
      }});

      const writerNameEl = document.getElementById('writerName');
      if (writerNameEl) writerNameEl.addEventListener('input', saveDraft);
      const branchSelectEl = document.getElementById('publicBranchCode');
      if (branchSelectEl) branchSelectEl.addEventListener('change', saveDraft);

      restoreDraft();
      checkAllValid();

      async function submitSurvey() {{
        const writerName = isAnonymous ? '' : document.getElementById('writerName').value.trim();
        const answers = [];
        questionsData.forEach(q => {{
          const textVal = q.has_text_answer ? (document.getElementById('text_' + q.id).value.trim() || null) : null;
          if (q.is_multi_select) {{
            const chosen = selected[q.id];
            if (chosen.length === 0) {{
              answers.push({{ question_id: q.id, selected_option: null, answer_text: textVal }});
            }} else {{
              chosen.forEach((val, i) => {{
                answers.push({{ question_id: q.id, selected_option: val, answer_text: i === 0 ? textVal : null }});
              }});
            }}
          }} else {{
            answers.push({{ question_id: q.id, selected_option: selected[q.id], answer_text: textVal }});
          }}
        }});
        const payload = {{ writer_name: writerName, answers: answers }};
        if (isPublicMode && !isAnonymous) {{
          payload.branch_code = document.getElementById('publicBranchCode').value;
        }}
        const btn = document.getElementById('submitBtn');
        btn.disabled = true;
        btn.innerText = '제출 중...';
        const res = await fetch('/survey/' + surveyId + '/submit', {{
          method: 'POST',
          headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify(payload)
        }});
        if (res.ok) {{
          try {{ localStorage.removeItem(draftKey); }} catch (e) {{}}
          const result = await res.json();
          showResultScreen(writerName, result.results, result.show_score_result, result.total_score, result.max_score, result.is_pass);        }} else {{
          const err = await res.json();
          alert('오류: ' + (err.detail || '제출 실패'));
          btn.disabled = false;
          btn.innerText = '제출';
        }}
      }}

          function showResultScreen(writerName, results, showScoreResult, totalScore, maxScore, isPass) {{
            const container = document.querySelector('.sv-card').parentElement;
            let resultsHtml = '';
            let scoreHtml = '';

            if (showScoreResult && maxScore !== null && maxScore !== undefined && maxScore > 0) {{
              const passBadge = isPass === true
                ? '<span style="background:#D1FAE5;color:#065F46;padding:4px 12px;border-radius:12px;font-size:13px;font-weight:bold;margin-left:8px;">✅ 합격</span>'
                : (isPass === false
                    ? '<span style="background:#FEE2E2;color:#991B1B;padding:4px 12px;border-radius:12px;font-size:13px;font-weight:bold;margin-left:8px;">❌ 불합격</span>'
                    : '');
              scoreHtml = '<div style="text-align:center;padding:16px;background:#F0FDF4;border-radius:10px;margin-bottom:12px;">' +
                '<div style="font-size:13px;color:#888;">획득 점수</div>' +
                '<div style="font-size:26px;font-weight:bold;color:#166534;">' + totalScore + ' / ' + maxScore + passBadge + '</div>' +
                '</div>';
            }}

            if (results.length === 0) {{
              resultsHtml = '<p style="color:#888;font-size:14px;text-align:center;padding:20px 0;">이 설문에는 정답이 있는 문항이 없습니다.</p>';
            }} else {{
              const correctCount = results.filter(r => r.is_correct).length;
              resultsHtml += '<div style="text-align:center;padding:16px;background:#EFF6FF;border-radius:10px;margin-bottom:16px;">' +
                '<div style="font-size:13px;color:#888;">정답 결과</div>' +
                '<div style="font-size:24px;font-weight:bold;color:#1E2761;">' + correctCount + ' / ' + results.length + '</div>' +
                '</div>';
              results.forEach((r, idx) => {{
                const badge = r.is_correct
                  ? '<span style="background:#D1FAE5;color:#065F46;padding:3px 10px;border-radius:10px;font-size:12px;font-weight:bold;">✅ 정답</span>'
                  : '<span style="background:#FEE2E2;color:#991B1B;padding:3px 10px;border-radius:10px;font-size:12px;font-weight:bold;">❌ 오답</span>';
                const myAnswer = r.selected_labels.length ? r.selected_labels.join(', ') : '(응답 없음)';
                const correctAnswer = !r.is_correct ? '<p style="font-size:13px;color:#22C55E;margin-top:4px;">정답: ' + r.correct_labels.join(', ') + '</p>' : '';
                const explanationHtml = r.explanation ? '<p style="font-size:12px;color:#666;margin-top:6px;background:#f8fafc;padding:8px;border-radius:6px;">💡 ' + r.explanation + '</p>' : '';
                resultsHtml += '<div style="padding:14px 0;border-bottom:1px solid #eee;">' +
                  '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:8px;">' +
                  '<span style="font-size:14px;font-weight:bold;">' + (idx + 1) + '. ' + r.question_text + '</span>' + badge +
                  '</div>' +
                  '<p style="font-size:13px;color:#555;margin-top:6px;">내 답변: ' + myAnswer + '</p>' +
                  correctAnswer + explanationHtml +
                  '</div>';
              }});
            }}

            const listLink = isPublicMode ? '' : '<a href="/survey" class="btn sv-btn-submit" style="display:block;text-align:center;text-decoration:none;margin-top:16px;">설문 목록으로</a>';

            container.innerHTML = '<div class="sv-card">' +
              '<h2>제출 완료</h2>' +
              '<p style="color:#888;font-size:13px;margin-bottom:16px;">작성자: ' + writerName + '</p>' +
              scoreHtml +
              resultsHtml +
              listLink +
              '</div>';
            window.scrollTo({{ top: 0, behavior: 'smooth' }});
          }}
    </script>
    """

    if is_public_mode:
        page_html = f"""
        <html><head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>{survey['title']}</title>
          <style>
            * {{ box-sizing: border-box; margin: 0; padding: 0; }}
            body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #f5f7fa; padding: 20px 14px; }}
            .card {{ background: white; border-radius: 12px; padding: 16px; box-shadow: 0 1px 4px rgba(0,0,0,0.08); margin-bottom: 16px; }}
            table {{ width: 100%; border-collapse: collapse; }}
            th {{ background: #1E2761; color: white; padding: 8px 6px; text-align: left; font-size: 11px; }}
            td {{ padding: 8px 6px; border-bottom: 1px solid #eee; font-size: 11px; }}
          </style>
        </head>
        <body>{inner_content}</body></html>
        """
        return HTMLResponse(content=page_html)

    return HTMLResponse(content=render_page(inner_content, user, "survey"))


@app.post("/survey/{survey_id}/submit")
async def survey_submit(survey_id: int, request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    data = await request.json()

    conn = get_conn()
    survey = conn.execute("SELECT * FROM survey WHERE id=?", (survey_id,)).fetchone()
    if not survey:
        conn.close()
        return JSONResponse(status_code=404, content={"detail": "설문을 찾을 수 없습니다."})

    if user and user["role"] == "master":
        conn.close()
        return JSONResponse(status_code=403, content={"detail": "지점 계정만 제출 가능합니다."})

    is_anonymous = bool(survey["is_anonymous"])

    if is_anonymous:
        import uuid
        branch_code = "ANONYMOUS"
        branch_name = "무기명"
        writer_name = f"익명_{uuid.uuid4().hex[:12]}"
    elif user:
        branch_code = user["branch_code"]
        branch_name = next((b["branch_name"] for b in get_branches() if b["branch_code"] == branch_code), branch_code)
    else:
        if not survey["is_public_access"]:
            conn.close()
            return JSONResponse(status_code=403, content={"detail": "로그인이 필요합니다."})
        branch_code = (data.get("branch_code") or "").strip()
        if not branch_code:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "지점을 선택하세요."})
        matched_branch = next((b for b in get_branches(branch_type='branch') if b["branch_code"] == branch_code), None)
        if not matched_branch:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "올바르지 않은 지점입니다."})
        branch_name = matched_branch["branch_name"]

    answers = data.get("answers", [])

    if not is_anonymous:
        writer_name_input = data.get("writer_name", "").strip()
        if not writer_name_input:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "작성자 이름을 입력하세요."})
        writer_name = writer_name_input

    if not answers:
        conn.close()
        return JSONResponse(status_code=400, content={"detail": "답변이 없습니다."})

    question_map = {
        q["id"]: q for q in conn.execute(
            "SELECT * FROM survey_question WHERE survey_id=?", (survey_id,)
        ).fetchall()
    }

    answers_by_qid: Dict[int, list] = {}
    for a in answers:
        qid = a.get("question_id")
        answers_by_qid.setdefault(qid, []).append(a)

    for qid, a_list in answers_by_qid.items():
        q = question_map.get(qid)
        if not q:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "잘못된 문항이 포함되어 있습니다."})
        if q["has_options"]:
            has_selection = any(a.get("selected_option") for a in a_list)
            if not has_selection:
                conn.close()
                return JSONResponse(status_code=400, content={"detail": f'"{q["question_text"]}" 문항에 응답하지 않았습니다.'})
        if q["has_text_answer"] and q["text_answer_required"]:
            has_text = any((a.get("answer_text") or "").strip() for a in a_list)
            if not has_text:
                conn.close()
                return JSONResponse(status_code=400, content={"detail": f'"{q["question_text"]}" 문항의 서술 입력이 필요합니다.'})

    existing = conn.execute(
        "SELECT id, status FROM survey_response WHERE survey_id=? AND branch_code=? AND writer_name=?",
        (survey_id, branch_code, writer_name)
    ).fetchone()
    is_resubmit = bool(existing and existing["status"] == "resubmit_requested")
    if existing and not is_resubmit:
        conn.close()
        return JSONResponse(status_code=400, content={
            "detail": "이미 같은 이름으로 제출된 기록이 있습니다.",
            "existing_response_id": existing["id"]
        })

    # 채점 결과 생성 — 정답이 있는 문항만 대상으로 정오답 판정 + 배점 합산
    results = []
    total_score = 0
    max_score = 0
    for qid, a_list in answers_by_qid.items():
        q = question_map.get(qid)
        if not q or not q["has_answer_key"]:
            continue
        option_rows = conn.execute(
            "SELECT * FROM survey_question_option WHERE question_id=? ORDER BY display_order", (qid,)
        ).fetchall()
        correct_values = {o["option_value"] for o in option_rows if o["is_correct"]}
        selected_values = {a.get("selected_option") for a in a_list if a.get("selected_option")}
        is_correct = selected_values == correct_values

        selected_labels = [o["option_label"] for o in option_rows if o["option_value"] in selected_values]
        correct_labels = [o["option_label"] for o in option_rows if o["option_value"] in correct_values]
        explanations = [o["explanation"] for o in option_rows if o["option_value"] in selected_values and o["explanation"]]
        if not explanations:
            explanations = [o["explanation"] for o in option_rows if o["option_value"] in correct_values and o["explanation"]]

        q_points = float(q["score_points"]) if q["score_points"] is not None else 0
        max_score += q_points
        if is_correct:
            total_score += q_points

        results.append({
            "question_id": qid,
            "question_text": q["question_text"],
            "is_correct": is_correct,
            "score_points": q_points,
            "selected_labels": selected_labels,
            "correct_labels": correct_labels,
            "explanation": explanations[0] if explanations else None
        })

    # 합격여부 계산 — pass_criteria_type/value가 설정된 경우에만 계산, 그 외엔 None
    is_pass = None
    pass_type = survey["pass_criteria_type"]
    pass_value = float(survey["pass_criteria_value"]) if survey["pass_criteria_value"] is not None else None
    if pass_type and pass_value is not None and max_score > 0:
        if pass_type == "score":
            is_pass = total_score >= pass_value
        elif pass_type == "percent":
            achieved_percent = (total_score / max_score) * 100
            is_pass = achieved_percent >= pass_value

    if is_resubmit:
        response_id = existing["id"]
        conn.execute("""
            UPDATE survey_response
            SET status='completed', total_score=?, max_score=?, is_pass=?, created_at=NOW()
            WHERE id=?
        """, (total_score, max_score, is_pass, response_id))
        conn.execute("DELETE FROM survey_answer WHERE response_id=?", (response_id,))
    else:
        conn.execute("""
            INSERT INTO survey_response (survey_id, writer_name, branch_code, branch_name, status, total_score, max_score, is_pass)
            VALUES (?, ?, ?, ?, 'completed', ?, ?, ?)
        """, (survey_id, writer_name, branch_code, branch_name, total_score, max_score, is_pass))

        new_row = conn.execute(
            "SELECT id FROM survey_response WHERE survey_id=? AND branch_code=? AND writer_name=?",
            (survey_id, branch_code, writer_name)
        ).fetchone()
        response_id = new_row["id"]

    for a in answers:
        sel = a.get("selected_option")
        text = a.get("answer_text")
        if sel is None and not text:
            continue
        conn.execute(
            "INSERT INTO survey_answer (response_id, question_id, selected_option, answer_text) VALUES (?, ?, ?, ?)",
            (response_id, a.get("question_id"), sel, text)
        )

    conn.commit()
    conn.close()

    show_score = bool(survey["show_score_result"])

    return JSONResponse(content={
        "status": "ok",
        "response_id": response_id,
        "results": results,
        "show_score_result": show_score,
        "total_score": total_score if show_score else None,
        "max_score": max_score if show_score else None,
        "is_pass": is_pass if show_score else None
    })


@app.get("/survey/{survey_id}/edit/{response_id}", response_class=HTMLResponse)
async def survey_edit_page(survey_id: int, response_id: int, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] == "master":
        return RedirectResponse(url="/login", status_code=303)

    conn = get_conn()
    survey = conn.execute("SELECT * FROM survey WHERE id=?", (survey_id,)).fetchone()
    response = conn.execute("SELECT * FROM survey_response WHERE id=?", (response_id,)).fetchone()
    if not survey or not response or response["branch_code"] != user["branch_code"] or response["survey_id"] != survey_id:
        conn.close()
        return RedirectResponse(url="/survey", status_code=303)

    legend_rows = conn.execute(
        "SELECT * FROM survey_score_legend WHERE survey_id=? ORDER BY display_order", (survey_id,)
    ).fetchall()

    section_rows = conn.execute(
        "SELECT * FROM survey_section WHERE survey_id=? ORDER BY display_order", (survey_id,)
    ).fetchall()

    question_rows = conn.execute(
        "SELECT * FROM survey_question WHERE survey_id=? AND active=TRUE ORDER BY display_order", (survey_id,)
    ).fetchall()

    questions_data = []
    for q in question_rows:
        options = conn.execute(
            "SELECT * FROM survey_question_option WHERE question_id=? ORDER BY display_order", (q["id"],)
        ).fetchall()
        existing_answers = conn.execute(
            "SELECT selected_option, answer_text FROM survey_answer WHERE response_id=? AND question_id=?",
            (response_id, q["id"])
        ).fetchall()
        existing_options_list = [a["selected_option"] for a in existing_answers if a["selected_option"]]
        existing_text = next((a["answer_text"] for a in existing_answers if a["answer_text"]), "")
        questions_data.append({
          "id": q["id"],
          "section_id": q["section_id"],
          "question_text": q["question_text"],
          "description": q["description"] or "",
          "image_url": q["image_url"] or "",
          "link_url": q["link_url"] or "",
          "link_label": q["link_label"] or "",
          "has_options": bool(q["has_options"]),
          "has_text_answer": bool(q["has_text_answer"]),
          "text_answer_label": q["text_answer_label"] or "기타 (서술)",
          "text_answer_required": bool(q["text_answer_required"]),
          "is_multi_select": bool(q["is_multi_select"]),
          "options": [{"value": o["option_value"], "label": o["option_label"]} for o in options]
      })
    conn.close()

    legend_html = ""
    if legend_rows:
        legend_items = "".join(
            f'<tr><td style="text-align:center;font-weight:bold;">{lg["score_value"]}</td><td>{lg["score_meaning"]}</td></tr>'
            for lg in legend_rows
        )
        legend_html = f"""
        <div class="card">
          <table>
            <thead><tr><th style="width:60px;text-align:center;">점수</th><th>의미</th></tr></thead>
            <tbody>{legend_items}</tbody>
          </table>
        </div>
        """

    intro_html = ""
    if survey["purpose"] or survey["method"]:
        purpose_block = f'<p style="margin-bottom:8px;"><b>진단목적</b><br>{survey["purpose"]}</p>' if survey["purpose"] else ""
        method_block = f'<p><b>진단방법</b><br>{survey["method"]}</p>' if survey["method"] else ""
        intro_html = f"""
        <div class="card" style="max-width:560px;margin:0 auto 16px;">
          {purpose_block}
          {method_block}
        </div>
        """

    questions_js = json.dumps(questions_data, ensure_ascii=False)
    writer_name_js = json.dumps(response["writer_name"], ensure_ascii=False)

    section_order = [(sec["id"], sec["section_name"]) for sec in section_rows]
    section_order.append((None, None))

    global_idx = 0
    question_blocks = ""
    for sec_id, sec_name in section_order:
        sec_questions = [q for q in questions_data if q["section_id"] == sec_id]
        if not sec_questions:
            continue
        if sec_name:
            question_blocks += f'<div class="sv-section-title">📂 {sec_name}</div>'
        for q in sec_questions:
            global_idx += 1
            num = global_idx
            question_text_html = q['question_text'].replace(chr(10), '<br>')
            desc_html = f'<p style="color:#888;font-size:12px;margin-bottom:8px;">{q["description"].replace(chr(10), "<br>")}</p>' if q["description"] else ""
            image_html = f'<img src="{q["image_url"]}" style="max-width:100%;border-radius:8px;margin-bottom:10px;display:block;">' if q.get("image_url") else ""
            link_html = f'<a href="{q["link_url"]}" target="_blank" rel="noopener" style="display:inline-block;margin-bottom:10px;padding:6px 12px;background:#EFF6FF;color:#1E2761;border-radius:6px;font-size:13px;text-decoration:none;">🔗 {q["link_label"] or "링크 열기"}</a>' if q.get("link_url") else ""
            question_blocks += f"""
            <div class="sv-field">
              <label>{num}. {question_text_html}</label>
              {desc_html}
              {image_html}
              {link_html}
              <div id="options_{q['id']}"></div>
              <div id="textwrap_{q['id']}" style="display:{'block' if q['has_text_answer'] else 'none'};">
                <textarea id="text_{q['id']}" placeholder="{q['text_answer_label']}{' (필수)' if q['text_answer_required'] else ' (선택)'}"></textarea>
              </div>
            </div>
            """

    content = f"""
    {intro_html}
    <style>
      .sv-legend-card {{ max-width:560px; margin:0 auto 16px; }}
      .sv-card {{ background:#fff; border-radius:12px; padding:20px; max-width:560px; margin:0 auto; box-shadow:0 2px 8px rgba(0,0,0,0.08); }}
      .sv-card h2 {{ font-size:18px; margin-bottom:16px; }}
      .sv-section-title {{ font-weight:bold; font-size:15px; color:#1E2761; margin:20px 0 12px; padding-bottom:6px; border-bottom:2px solid #1E2761; }}
      .sv-field {{ margin-bottom:20px; padding-bottom:16px; border-bottom:1px solid #eee; }}
      .sv-field label {{ display:block; font-weight:bold; margin-bottom:6px; font-size:14px; }}
      .sv-option {{ display:inline-block; border:1px solid #ddd; border-radius:8px; padding:8px 14px; margin:0 6px 6px 0; cursor:pointer; font-size:13px; }}
      .sv-option.selected {{ border-color:#2563eb; background:#eff6ff; color:#2563eb; font-weight:bold; }}
      .sv-card textarea {{ width:100%; padding:8px; border:1px solid #ccc; border-radius:6px; box-sizing:border-box; font-size:14px; min-height:60px; margin-top:8px; }}
      .sv-card button {{ padding:12px 20px; border:none; border-radius:6px; font-size:15px; cursor:pointer; width:100%; }}
      .sv-btn-submit {{ background:#2563eb; color:#fff; }}
    </style>
    <div class="sv-legend-card">{legend_html}</div>
    <div class="sv-card">
      <h2>{survey['title']} — 수정</h2>
      <p style="color:#888;font-size:12px;margin-bottom:16px;">작성자: {response['writer_name']}</p>
      {question_blocks}
      <button class="sv-btn-submit" id="submitBtn" onclick="submitEdit()">저장</button>
    </div>

    <script>
      const questionsData = {questions_js};
      const writerName = {writer_name_js};
      const responseId = {response_id};

      let selected = {{}};
      questionsData.forEach(q => selected[q.id] = q.is_multi_select ? [...q.existing_options] : (q.existing_options[0] || null));

      function renderOptions(q) {{
        if (!q.has_options) return;
        const container = document.getElementById('options_' + q.id);
        q.options.forEach(opt => {{
          const isChecked = q.is_multi_select ? selected[q.id].includes(opt.value) : opt.value === selected[q.id];
          const div = document.createElement('div');
          div.className = 'sv-option' + (isChecked ? ' selected' : '');
          div.innerText = (q.is_multi_select ? (isChecked ? '☑ ' : '☐ ') : '') + opt.label;
          div.onclick = () => {{
            if (q.is_multi_select) {{
              const arr = selected[q.id];
              const pos = arr.indexOf(opt.value);
              if (pos >= 0) {{
                arr.splice(pos, 1);
                div.classList.remove('selected');
                div.innerText = '☐ ' + opt.label;
              }} else {{
                arr.push(opt.value);
                div.classList.add('selected');
                div.innerText = '☑ ' + opt.label;
              }}
              saveDraft();
            }} else {{
              selected[q.id] = opt.value;
              document.querySelectorAll('#options_' + q.id + ' .sv-option').forEach(o => o.classList.remove('selected'));
              div.classList.add('selected');
            }}
          }};
          container.appendChild(div);
        }});
      }}

      questionsData.forEach(q => {{
        renderOptions(q);
        const textEl = document.getElementById('text_' + q.id);
        if (textEl) textEl.value = q.existing_text || '';
      }});

      async function submitEdit() {{
        const answers = [];
        questionsData.forEach(q => {{
          const textVal = q.has_text_answer ? (document.getElementById('text_' + q.id).value.trim() || null) : null;
          if (q.is_multi_select) {{
            const chosen = selected[q.id];
            if (chosen.length === 0) {{
              answers.push({{ question_id: q.id, selected_option: null, answer_text: textVal }});
            }} else {{
              chosen.forEach((val, i) => {{
                answers.push({{ question_id: q.id, selected_option: val, answer_text: i === 0 ? textVal : null }});
              }});
            }}
          }} else {{
            answers.push({{ question_id: q.id, selected_option: selected[q.id], answer_text: textVal }});
          }}
        }});
        const payload = {{ answers: answers }};
        const res = await fetch('/survey/edit/' + responseId + '/submit', {{
          method: 'POST',
          headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify(payload)
        }});
        if (res.ok) {{
          alert('수정되었습니다.');
          window.location.href = '/survey';
        }} else {{
          const err = await res.json();
          alert('오류: ' + (err.detail || '수정 실패'));
        }}
      }}
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "survey"))


@app.post("/survey/edit/{response_id}/submit")
async def survey_edit_submit(response_id: int, request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] == "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    conn = get_conn()
    response = conn.execute("SELECT * FROM survey_response WHERE id=?", (response_id,)).fetchone()
    if not response or response["branch_code"] != user["branch_code"]:
        conn.close()
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    answers = data.get("answers", [])

    question_map = {
        q["id"]: q for q in conn.execute(
            "SELECT * FROM survey_question WHERE survey_id=?", (response["survey_id"],)
        ).fetchall()
    }

    answers_by_qid: Dict[int, list] = {}
    for a in answers:
        qid = a.get("question_id")
        answers_by_qid.setdefault(qid, []).append(a)

    for qid, a_list in answers_by_qid.items():
        q = question_map.get(qid)
        if not q:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "잘못된 문항이 포함되어 있습니다."})
        if q["has_options"]:
            has_selection = any(a.get("selected_option") for a in a_list)
            if not has_selection:
                conn.close()
                return JSONResponse(status_code=400, content={"detail": f'"{q["question_text"]}" 문항에 응답하지 않았습니다.'})
        if q["has_text_answer"] and q["text_answer_required"]:
            has_text = any((a.get("answer_text") or "").strip() for a in a_list)
            if not has_text:
                conn.close()
                return JSONResponse(status_code=400, content={"detail": f'"{q["question_text"]}" 문항의 서술 입력이 필요합니다.'})

    conn.execute("DELETE FROM survey_answer WHERE response_id=?", (response_id,))
    for a in answers:
        sel = a.get("selected_option")
        text = a.get("answer_text")
        if sel is None and not text:
            continue
        conn.execute(
            "INSERT INTO survey_answer (response_id, question_id, selected_option, answer_text) VALUES (?, ?, ?, ?)",
            (response_id, a.get("question_id"), sel, text)
        )
    conn.execute("UPDATE survey_response SET status='completed', updated_at=NOW() WHERE id=?", (response_id,))
    conn.commit()
    conn.close()

    return JSONResponse(content={"status": "ok"})

@app.get("/master/survey", response_class=HTMLResponse)
async def master_survey_list_page(session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "survey"):
        return RedirectResponse(url="/master", status_code=303)

    conn = get_conn()
    surveys = conn.execute("SELECT * FROM survey ORDER BY created_at DESC").fetchall()

    rows_html = ""
    all_surveys_data = []
    if not surveys:
        rows_html = '<tr><td colspan="5" style="text-align:center;padding:20px;color:#888;">등록된 설문이 없습니다.</td></tr>'
    else:
        for s in surveys:
            question_count = conn.execute(
                "SELECT COUNT(*) as cnt FROM survey_question WHERE survey_id=?", (s["id"],)
            ).fetchone()["cnt"]
            response_count = conn.execute(
                "SELECT COUNT(*) as cnt FROM survey_response WHERE survey_id=?", (s["id"],)
            ).fetchone()["cnt"]
            active_badge = '<span class="badge-green">활성</span>' if s["active"] else '<span class="badge-red">비활성</span>'
            safe_title = s["title"].replace("'", "")
            all_surveys_data.append({
                "id": s["id"], "title": s["title"], "purpose": s["purpose"] or "",
                "method": s["method"] or "", "allow_edit_after_submit": bool(s["allow_edit_after_submit"]),
                "is_public_access": bool(s["is_public_access"]),
                "is_anonymous": bool(s["is_anonymous"]),
                "reminder_interval_days": s["reminder_interval_days"],
                "show_score_result": bool(s["show_score_result"]),
                "pass_criteria_type": s["pass_criteria_type"],
                "pass_criteria_value": float(s["pass_criteria_value"]) if s["pass_criteria_value"] is not None else None
            })
            rows_html += f"""
            <tr>
                <td><b>{s['title']}</b> {active_badge}</td>
                <td style="text-align:center;">{question_count}개</td>
                <td style="text-align:center;">{response_count}건</td>
                <td style="font-size:11px;color:#888;">{str(s['created_at'])[:16]}</td>
                <td style="display:flex;gap:4px;flex-wrap:wrap;">
                  <button class="btn" style="font-size:11px;padding:4px 8px;background:#F59E0B;" onclick="openEditSurveyInfo({s['id']})">⚙️ 설정수정</button>                  
                  <a href="/master/survey/{s['id']}/questions" class="btn" style="font-size:11px;padding:4px 8px;text-decoration:none;">문항관리</a>
                  <a href="/master/survey/{s['id']}/responses" class="btn" style="font-size:11px;padding:4px 8px;text-decoration:none;background:#64748B;">제출현황</a>
                  <button class="btn" style="font-size:11px;padding:4px 8px;background:#0EA5E9;" onclick="copySurveyLink({s['id']}, this)">🔗 링크복사</button>
                  <button class="btn" style="font-size:11px;padding:4px 8px;background:#8B5CF6;" onclick="copyAnswerKeyLink({s['id']}, this)">🔑 정답링크복사</button>
                  <button class="btn" style="font-size:11px;padding:4px 8px;background:#22C55E;" onclick="duplicateSurvey({s['id']}, '{safe_title}', this)">📋 설문복사</button>
                  <button class="btn" style="font-size:11px;padding:4px 8px;background:#8B5CF6;" onclick="toggleSurvey({s['id']}, {str(not s['active']).lower()})">{'비활성화' if s['active'] else '활성화'}</button>
                  <button class="btn btn-red" style="font-size:11px;padding:4px 8px;" onclick="deleteSurvey({s['id']}, '{safe_title}', {response_count})">삭제</button>
                </td>
            </tr>
            """
    conn.close()

    all_surveys_json = json.dumps(all_surveys_data, ensure_ascii=False)

    content = f"""
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">
      <a href="/master" style="color:#1E2761;">← 마스터</a>
      <h2>📋 설문 관리</h2>
    </div>

    <div class="card">
      <h3 style="margin-bottom:8px;">새 설문 만들기</h3>
      <div style="display:flex;flex-direction:column;gap:8px;">
        <input type="text" id="svTitle" placeholder="설문 제목 (예: 포포즈 직책자 인재상 자가진단)">
        <textarea id="svPurpose" placeholder="진단목적 (선택, 자유서술)" style="width:100%;min-height:60px;padding:8px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;font-size:14px;"></textarea>
        <textarea id="svMethod" placeholder="진단방법 (선택, 자유서술)" style="width:100%;min-height:60px;padding:8px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;font-size:14px;"></textarea>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;">
          <input type="checkbox" id="svAllowEdit" checked style="width:18px;height:18px;flex-shrink:0;"> 제출 후 수정 허용 (해제 시 제출 즉시 결과 확정, 재수정 불가 — 퀴즈/시험용)
        </label>
        <div>
          <label style="font-size:12px;color:#888;">점수 의미표 (선택 — 표로 보여줄 점수/의미 쌍, 필요 없으면 비워두세요)</label>
          <div id="legendRows" style="display:flex;flex-direction:column;gap:6px;margin-top:6px;"></div>
          <button type="button" class="btn" style="font-size:12px;padding:6px 10px;margin-top:6px;background:#64748B;" onclick="addLegendRow()">+ 점수 행 추가</button>
        </div>
        <button class="btn" type="button" onclick="createSurvey()">설문 생성</button>
      </div>
      <div id="svCreateResult" style="margin-top:8px;font-size:13px;"></div>
    </div>

    <div class="card">
      <table>
        <thead><tr><th>설문명</th><th>문항수</th><th>제출수</th><th>생성일</th><th></th></tr></thead>
        <tbody>{rows_html}</tbody>
      </table>
    </div>

    <div id="editSurveyModal" style="display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1000;align-items:center;justify-content:center;">
      <div style="background:#fff;border-radius:12px;padding:24px;max-width:480px;width:90%;max-height:85vh;overflow-y:auto;">
        <h3 style="margin-bottom:12px;">설문 설정 수정</h3>
        <input type="hidden" id="editSvId">
        <label style="font-size:12px;color:#888;">설문 제목</label>
        <input type="text" id="editSvTitle" style="margin-bottom:8px;">
        <label style="font-size:12px;color:#888;">진단목적</label>
        <textarea id="editSvPurpose" style="width:100%;min-height:60px;padding:8px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;font-size:14px;margin-bottom:8px;"></textarea>
        <label style="font-size:12px;color:#888;">진단방법</label>
        <textarea id="editSvMethod" style="width:100%;min-height:60px;padding:8px;border:1px solid #ccc;border-radius:6px;box-sizing:border-box;font-size:14px;margin-bottom:8px;"></textarea>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;margin-bottom:8px;">
          <input type="checkbox" id="editSvAllowEdit" style="width:18px;height:18px;flex-shrink:0;"> 제출 후 수정 허용
        </label>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;margin-bottom:8px;">
          <input type="checkbox" id="editSvPublicAccess" style="width:18px;height:18px;flex-shrink:0;"> 로그인 없이 링크로 제출 허용 (공개링크, 제출 후 수정 불가)
        </label>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;margin-bottom:12px;">
          <input type="checkbox" id="editSvAnonymous" style="width:18px;height:18px;flex-shrink:0;"> 무기명 설문 (지점/작성자 정보 완전 익명, 제출·미제출 관리·재제출요청·수정·팀즈알림 자동 비활성)
        </label>
        <label style="font-size:12px;color:#888;">미제출 알림 주기 (일 단위, 비워두면 알림 사용 안함)</label>
        <p style="font-size:11px;color:#888;margin-bottom:4px;">제출 대상자 명단이 등록된 설문만 작동합니다. 예: 3 입력 시 3일마다 미제출 지점에 팀즈 알림 발송</p>
        <input type="number" id="editSvReminderDays" placeholder="예: 3" min="1" style="margin-bottom:12px;">
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;margin-bottom:8px;">
          <input type="checkbox" id="editSvShowScore" onchange="toggleScoreCriteriaSection()" style="width:18px;height:18px;flex-shrink:0;"> 제출 결과에 점수/합격여부 표시
        </label>
        <div id="scoreCriteriaSection" style="display:none;margin-bottom:12px;padding:10px;background:#f8fafc;border-radius:8px;">
          <label style="font-size:12px;color:#888;">합격 기준</label>
          <select id="editSvPassType" style="margin-bottom:8px;">
            <option value="percent">퍼센트 기준 (%)</option>
            <option value="score">점수 기준</option>
          </select>
          <input type="number" id="editSvPassValue" placeholder="예: 퍼센트면 70, 점수면 8" min="0" step="0.5">
        </div>
        <div style="display:flex;gap:8px;">
          <button class="btn" style="flex:1;background:#eee;color:#333;" onclick="closeEditSurveyInfo()">취소</button>
          <button class="btn" style="flex:1;" onclick="saveEditSurveyInfo()">저장</button>
        </div>
        <div id="editSvResult" style="margin-top:8px;font-size:13px;"></div>
      </div>
    </div>

    <script>
      const allSurveysData = {all_surveys_json};

      function toggleScoreCriteriaSection() {{
        document.getElementById('scoreCriteriaSection').style.display = document.getElementById('editSvShowScore').checked ? 'block' : 'none';
      }}

      function openEditSurveyInfo(id) {{
        const s = allSurveysData.find(x => x.id === id);
        if (!s) return;
        document.getElementById('editSvId').value = s.id;
        document.getElementById('editSvTitle').value = s.title;
        document.getElementById('editSvPurpose').value = s.purpose;
        document.getElementById('editSvMethod').value = s.method;
        document.getElementById('editSvAllowEdit').checked = s.allow_edit_after_submit;
        document.getElementById('editSvPublicAccess').checked = s.is_public_access;
        document.getElementById('editSvAnonymous').checked = s.is_anonymous;
        document.getElementById('editSvReminderDays').value = s.reminder_interval_days || '';
        document.getElementById('editSvShowScore').checked = s.show_score_result;
        document.getElementById('editSvPassType').value = s.pass_criteria_type || 'percent';
        document.getElementById('editSvPassValue').value = s.pass_criteria_value || '';
        toggleScoreCriteriaSection();
        document.getElementById('editSurveyModal').style.display = 'flex';
      }}

      function closeEditSurveyInfo() {{
        document.getElementById('editSurveyModal').style.display = 'none';
      }}

      async function saveEditSurveyInfo() {{
        const id = document.getElementById('editSvId').value;
        const title = document.getElementById('editSvTitle').value.trim();
        const purpose = document.getElementById('editSvPurpose').value.trim();
        const method = document.getElementById('editSvMethod').value.trim();
        const allowEdit = document.getElementById('editSvAllowEdit').checked;
        const publicAccess = document.getElementById('editSvPublicAccess').checked;
        const isAnonymous = document.getElementById('editSvAnonymous').checked;
        const reminderDaysRaw = document.getElementById('editSvReminderDays').value.trim();
        const reminderDays = reminderDaysRaw ? parseInt(reminderDaysRaw) : null;
        const showScore = document.getElementById('editSvShowScore').checked;
        const passType = document.getElementById('editSvPassType').value;
        const passValueRaw = document.getElementById('editSvPassValue').value.trim();
        const passValue = passValueRaw ? parseFloat(passValueRaw) : null;
        if (!title) {{ alert('설문 제목을 입력하세요.'); return; }}
        if (showScore && passValue === null) {{ alert('합격 기준값을 입력하세요.'); return; }}

        const res = await fetch('/master/survey/' + id + '/update-info', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{
            title: title, purpose: purpose, method: method,
            allow_edit_after_submit: allowEdit, is_public_access: publicAccess,
            is_anonymous: isAnonymous,
            reminder_interval_days: reminderDays,
            show_score_result: showScore, pass_criteria_type: passType, pass_criteria_value: passValue
          }})
        }});
        if (res.ok) {{ location.reload(); }} else {{
          const err = await res.json();
          document.getElementById('editSvResult').innerText = '오류: ' + (err.detail || '저장 실패');
        }}
      }}

      function addLegendRow(value, meaning) {{
        const container = document.getElementById('legendRows');
        const row = document.createElement('div');
        row.style.display = 'flex';
        row.style.gap = '6px';
        row.innerHTML = '<input type="text" class="legend-value" placeholder="점수(예: 1)" style="width:80px;" value="' + (value || '') + '">' +
          '<input type="text" class="legend-meaning" placeholder="의미(예: 전혀 그렇지 않다)" style="flex:1;" value="' + (meaning || '') + '">' +
          '<button type="button" class="btn btn-red" style="font-size:11px;padding:6px 10px;" onclick="this.parentElement.remove()">삭제</button>';
        container.appendChild(row);
      }}

      async function createSurvey() {{
        const title = document.getElementById('svTitle').value.trim();
        const purpose = document.getElementById('svPurpose').value.trim();
        const method = document.getElementById('svMethod').value.trim();
        const allowEdit = document.getElementById('svAllowEdit').checked;
        if (!title) {{ alert('설문 제목을 입력하세요.'); return; }}

        const legends = [];
        document.querySelectorAll('#legendRows > div').forEach(row => {{
          const val = row.querySelector('.legend-value').value.trim();
          const meaning = row.querySelector('.legend-meaning').value.trim();
          if (val && meaning) legends.push({{ score_value: val, score_meaning: meaning }});
        }});

        const res = await fetch('/master/survey/create', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ title: title, purpose: purpose, method: method, allow_edit_after_submit: allowEdit, legends: legends }})
        }});
        if (res.ok) {{ location.reload(); }} else {{
          const err = await res.json();
          document.getElementById('svCreateResult').innerText = '오류: ' + (err.detail || '생성 실패');
        }}
      }}

      async function copySurveyLink(id, btnEl) {{
        const url = window.location.origin + '/survey/' + id;
        try {{
          await navigator.clipboard.writeText(url);
          const original = btnEl.innerText;
          btnEl.innerText = '✅ 복사됨';
          setTimeout(() => {{ btnEl.innerText = original; }}, 1500);
        }} catch (e) {{
          prompt('아래 링크를 복사하세요:', url);
        }}
      }}

      async function copyAnswerKeyLink(id, btnEl) {{
        const original = btnEl.innerText;
        btnEl.innerText = '생성 중...';
        btnEl.disabled = true;
        try {{
          const res = await fetch('/master/survey/' + id + '/answer-key-link', {{ method: 'POST' }});
          const data = await res.json();
          if (!res.ok) {{
            alert('오류: ' + (data.detail || '링크 생성 실패'));
            btnEl.innerText = original;
            btnEl.disabled = false;
            return;
          }}
          const url = window.location.origin + '/survey/answer-key/' + data.token;
          try {{
            await navigator.clipboard.writeText(url);
            btnEl.innerText = '✅ 복사됨';
          }} catch (e) {{
            prompt('아래 링크를 복사하세요:', url);
            btnEl.innerText = original;
          }}
        }} catch (e) {{
          alert('링크 생성 중 오류가 발생했습니다.');
          btnEl.innerText = original;
        }}
        btnEl.disabled = false;
        setTimeout(() => {{ btnEl.innerText = original; }}, 1500);
      }}

      async function duplicateSurvey(id, title, btnEl) {{
        if (!confirm('"' + title + '" 설문을 복사합니다. 문항/분야/점수표가 그대로 복제되고, 제출된 응답은 복사되지 않습니다. 계속할까요?')) return;
        const original = btnEl.innerText;
        btnEl.innerText = '복사 중...';
        btnEl.disabled = true;
        try {{
          const res = await fetch('/master/survey/' + id + '/duplicate', {{ method: 'POST' }});
          if (res.ok) {{
            location.reload();
          }} else {{
            const err = await res.json();
            alert('오류: ' + (err.detail || '복사 실패'));
            btnEl.innerText = original;
            btnEl.disabled = false;
          }}
        }} catch (e) {{
          alert('복사 중 오류가 발생했습니다.');
          btnEl.innerText = original;
          btnEl.disabled = false;
        }}
      }}

      async function toggleSurvey(id, newActive) {{
        const res = await fetch('/master/survey/' + id + '/toggle', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ active: newActive }})
        }});
        if (res.ok) {{ location.reload(); }} else {{ alert('변경 실패'); }}
      }}

      async function deleteSurvey(id, title, responseCount) {{
        const msg = responseCount > 0
          ? title + ' 설문을 삭제합니다. 이미 제출된 응답 ' + responseCount + '건도 함께 완전히 삭제되며 되돌릴 수 없습니다. 계속할까요?'
          : title + ' 설문을 삭제할까요?';
        if (!confirm(msg)) return;
        const res = await fetch('/master/survey/' + id + '/delete', {{ method: 'POST' }});
        if (res.ok) {{ location.reload(); }} else {{ alert('삭제 실패'); }}
      }}
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "master"))

@app.post("/master/survey/{survey_id}/answer-key-link")
async def master_survey_answer_key_link(survey_id: int, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    conn = get_conn()
    survey = conn.execute("SELECT id, answer_key_token FROM survey WHERE id=?", (survey_id,)).fetchone()
    if not survey:
        conn.close()
        return JSONResponse(status_code=404, content={"detail": "설문을 찾을 수 없습니다."})

    token = survey["answer_key_token"]
    if not token:
        import secrets
        token = secrets.token_urlsafe(24)
        conn.execute("UPDATE survey SET answer_key_token=? WHERE id=?", (token, survey_id))
        conn.commit()

    conn.close()
    return JSONResponse(content={"token": token})


@app.get("/survey/answer-key/{token}", response_class=HTMLResponse)
async def survey_answer_key_page(token: str):
    conn = get_conn()
    survey = conn.execute("SELECT * FROM survey WHERE answer_key_token=?", (token,)).fetchone()
    if not survey:
        conn.close()
        return HTMLResponse(content="<h2 style='text-align:center;margin-top:60px;'>유효하지 않은 링크입니다.</h2>", status_code=404)

    section_rows = conn.execute(
        "SELECT * FROM survey_section WHERE survey_id=? ORDER BY display_order", (survey["id"],)
    ).fetchall()
    question_rows = conn.execute(
        "SELECT * FROM survey_question WHERE survey_id=? AND active=TRUE ORDER BY display_order", (survey["id"],)
    ).fetchall()

    questions_by_section: Dict = {}
    for q in question_rows:
        questions_by_section.setdefault(q["section_id"], []).append(q)

    section_order = [(sec["id"], sec["section_name"]) for sec in section_rows]
    section_order.append((None, None))

    blocks_html = ""
    global_idx = 0
    for sec_id, sec_name in section_order:
        sec_questions = questions_by_section.get(sec_id, [])
        if not sec_questions:
            continue
        if sec_name:
            blocks_html += f'<div style="font-weight:bold;font-size:15px;color:#1E2761;margin:20px 0 12px;padding-bottom:6px;border-bottom:2px solid #1E2761;">📂 {sec_name}</div>'
        for q in sec_questions:
            global_idx += 1
            answer_html = ""
            if q["has_options"]:
                option_rows = conn.execute(
                    "SELECT option_label, is_correct FROM survey_question_option WHERE question_id=? ORDER BY display_order",
                    (q["id"],)
                ).fetchall()
                correct_labels = [o["option_label"] for o in option_rows if o["is_correct"]]
                if correct_labels:
                    answer_html = f'<div style="margin-top:6px;padding:8px 12px;background:#F0FDF4;border-radius:6px;color:#166534;font-size:13px;"><b>정답:</b> {", ".join(correct_labels)}</div>'
                else:
                    answer_html = '<div style="margin-top:6px;padding:8px 12px;background:#F9FAFB;border-radius:6px;color:#888;font-size:13px;">정답 미설정</div>'
            else:
                answer_html = '<div style="margin-top:6px;padding:8px 12px;background:#F9FAFB;border-radius:6px;color:#888;font-size:13px;">서술형 문항 (정답 없음)</div>'

            blocks_html += f"""
            <div style="margin-bottom:16px;padding-bottom:14px;border-bottom:1px solid #eee;">
              <div style="font-weight:bold;font-size:14px;">{global_idx}. {q['question_text']}</div>
              {answer_html}
            </div>
            """

    conn.close()

    page_html = f"""
    <html><head>
      <meta charset="utf-8">
      <meta name="viewport" content="width=device-width, initial-scale=1">
      <title>{survey['title']} - 정답</title>
      <style>
        * {{ box-sizing: border-box; margin: 0; padding: 0; }}
        body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; background: #f5f7fa; padding: 20px 14px; }}
        .card {{ background: white; border-radius: 12px; padding: 20px; max-width: 560px; margin: 0 auto; box-shadow: 0 1px 4px rgba(0,0,0,0.08); }}
      </style>
    </head>
    <body>
      <div class="card">
        <h2 style="margin-bottom:16px;">🔑 {survey['title']} — 정답</h2>
        {blocks_html if blocks_html else '<p style="color:#888;text-align:center;padding:20px 0;">등록된 문항이 없습니다.</p>'}
      </div>
    </body></html>
    """
    return HTMLResponse(content=page_html)


@app.post("/master/survey/create")
async def master_survey_create(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    title = data.get("title", "").strip()
    purpose = data.get("purpose", "").strip()
    method = data.get("method", "").strip()
    allow_edit_after_submit = bool(data.get("allow_edit_after_submit", True))
    legends = data.get("legends", [])

    if not title:
        return JSONResponse(status_code=400, content={"detail": "설문 제목을 입력하세요."})

    conn = get_conn()
    conn.execute(
        "INSERT INTO survey (title, purpose, method, allow_edit_after_submit, active) VALUES (?, ?, ?, ?, TRUE)",
        (title, purpose or None, method or None, allow_edit_after_submit)
    )
    new_survey = conn.execute(
        "SELECT id FROM survey ORDER BY created_at DESC LIMIT 1"
    ).fetchone()
    survey_id = new_survey["id"]

    for idx, lg in enumerate(legends):
        conn.execute(
            "INSERT INTO survey_score_legend (survey_id, score_value, score_meaning, display_order) VALUES (?, ?, ?, ?)",
            (survey_id, lg.get("score_value", ""), lg.get("score_meaning", ""), idx)
        )

    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok", "survey_id": survey_id})


