@app.post("/master/survey/{survey_id}/question/{question_id}/delete")
async def master_survey_question_delete(survey_id: int, question_id: int, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    conn = get_conn()
    usage_count = conn.execute(
        "SELECT COUNT(*) as cnt FROM survey_answer WHERE question_id=?", (question_id,)
    ).fetchone()["cnt"]

    if usage_count > 0:
        conn.close()
        return JSONResponse(status_code=400, content={
            "detail": f"이미 {usage_count}건의 응답에 사용된 문항이라 삭제할 수 없습니다. 대신 '비활성화'를 사용해주세요."
        })

    conn.execute("DELETE FROM survey_question WHERE id=? AND survey_id=?", (question_id, survey_id))
    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok"})

@app.get("/master/survey/{survey_id}/responses", response_class=HTMLResponse)
async def master_survey_responses_page(
    survey_id: int, session_token: str = Cookie(default=None), filter_branch: str = ""
):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)

    conn = get_conn()
    survey = conn.execute("SELECT * FROM survey WHERE id=?", (survey_id,)).fetchone()
    if not survey:
        conn.close()
        return RedirectResponse(url="/master/survey", status_code=303)

    question_rows = conn.execute(
        "SELECT * FROM survey_question WHERE survey_id=? ORDER BY display_order", (survey_id,)
    ).fetchall()
    question_map = {q["id"]: q for q in question_rows}

    query = "SELECT * FROM survey_response WHERE survey_id=?"
    params: list = [survey_id]
    if filter_branch:
        query += " AND branch_code=?"
        params.append(filter_branch)
    query += " ORDER BY created_at DESC"
    responses = conn.execute(query, params).fetchall()

    all_branches = conn.execute(
        "SELECT DISTINCT branch_code, branch_name FROM survey_response WHERE survey_id=? ORDER BY branch_name", (survey_id,)
    ).fetchall()

    # ── 제출/미제출 현황 계산 ──
    target_rows = conn.execute(
        "SELECT * FROM survey_target_list WHERE survey_id=? ORDER BY branch_name, writer_name", (survey_id,)
    ).fetchall()

    submitted_keys = {(r["branch_code"], r["writer_name"]) for r in conn.execute(
        "SELECT DISTINCT branch_code, writer_name FROM survey_response WHERE survey_id=?", (survey_id,)
    ).fetchall()}

    target_status_rows_html = ""
    submitted_count = 0
    if target_rows:
        for t in target_rows:
            is_submitted = (t["branch_code"], t["writer_name"]) in submitted_keys
            if is_submitted:
                submitted_count += 1
            status_badge = '<span class="badge-green">✅ 제출완료</span>' if is_submitted else '<span class="badge-red">❌ 미제출</span>'
            target_status_rows_html += f"""
            <tr>
              <td>{t['branch_name']}</td>
              <td>{t['writer_name']}</td>
              <td>{t['contact'] or '-'}</td>
              <td>{status_badge}</td>
            </tr>
            """
    conn.close()
    is_anonymous_survey = bool(survey["is_anonymous"])

    target_section_html = ""
    if target_rows and not is_anonymous_survey:
        target_section_html = f"""
        <div class="card">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
            <h3 style="font-size:15px;">📋 제출 대상자 현황</h3>
            <span style="font-size:13px;color:#888;">{submitted_count} / {len(target_rows)}명 제출</span>
          </div>
          <table>
            <thead><tr><th>지점</th><th>이름</th><th>연락처</th><th>상태</th></tr></thead>
            <tbody>{target_status_rows_html}</tbody>
          </table>
        </div>
        """

    conn = get_conn()
    rows_html = ""
    if not responses:
        rows_html = '<tr><td colspan="6" style="text-align:center;padding:20px;color:#888;">제출된 응답이 없습니다.</td></tr>'
    for r in responses:
        answers = conn.execute(
            "SELECT * FROM survey_answer WHERE response_id=? ORDER BY question_id", (r["id"],)
        ).fetchall()
        answer_lines = []
        for a in answers:
            q = question_map.get(a["question_id"])
            if not q:
                continue
            qlabel = q["question_text"]
            parts = []
            if a["selected_option"]:
                opt_row = conn.execute(
                    "SELECT option_label FROM survey_question_option WHERE question_id=? AND option_value=?",
                    (a["question_id"], a["selected_option"])
                ).fetchone()
                parts.append(opt_row["option_label"] if opt_row else a["selected_option"])
            if a["answer_text"]:
                parts.append(f'"{a["answer_text"]}"')
            answer_lines.append(f"<b>{qlabel}</b>: {' / '.join(parts) if parts else '-'}")
        answers_html = "<br>".join(answer_lines)

        status_badge = '<span class="badge-red">⚠️ 재제출요청</span>' if r["status"] == "resubmit_requested" else '<span class="badge-green">✅ 완료</span>'

        # 정답/오답 개수 + 합격여부 계산 (정답이 있는 문항만 대상, 문항 단위로 판정 — 멀티셀렉트는 선택집합==정답집합으로 채점)
        answers_by_qid_g: Dict[int, list] = {}
        for a in answers:
            answers_by_qid_g.setdefault(a["question_id"], []).append(a)

        correct_count = 0
        graded_count = 0
        for qid_g, a_list_g in answers_by_qid_g.items():
            q = question_map.get(qid_g)
            if not q or not q["has_answer_key"]:
                continue
            graded_count += 1
            option_rows_g = conn.execute(
                "SELECT option_value, is_correct FROM survey_question_option WHERE question_id=?",
                (qid_g,)
            ).fetchall()
            correct_values_g = {o["option_value"] for o in option_rows_g if o["is_correct"]}
            selected_values_g = {a.get("selected_option") for a in a_list_g if a.get("selected_option")}
            if selected_values_g == correct_values_g:
                correct_count += 1

    
        score_badge = ""
        if graded_count > 0:
            score_badge = f'<div style="font-size:12px;color:#555;margin-top:2px;">{correct_count}/{graded_count} 정답</div>'
        if r["is_pass"] is not None:
            pass_html = '<span style="background:#D1FAE5;color:#065F46;padding:2px 8px;border-radius:8px;font-size:11px;font-weight:bold;">✅ 합격</span>' if r["is_pass"] else '<span style="background:#FEE2E2;color:#991B1B;padding:2px 8px;border-radius:8px;font-size:11px;font-weight:bold;">❌ 불합격</span>'
            score_badge += f'<div style="margin-top:2px;">{pass_html}</div>'

        rows_html += f"""
        <tr>
            <td style="text-align:center;">
              <input type="checkbox" name="selected_ids" value="{r['id']}" class="sv-resp-check" style="width:16px;height:16px;">
            </td>
            <td>{r['branch_name']}</td>
            <td>{r['writer_name']}</td>
            <td style="font-size:12px;">{answers_html}</td>
            <td>{status_badge}{score_badge}</td>
            <td style="font-size:11px;color:#888;">{str(r['created_at'])[:16]}</td>
        </tr>
        """
    conn.close()

    branch_options_html = '<option value="">전체 지점</option>'
    for b in all_branches:
        sel = "selected" if filter_branch == b["branch_code"] else ""
        branch_options_html += f'<option value="{b["branch_code"]}" {sel}>{b["branch_name"]}</option>'

    upload_section_html = "" if is_anonymous_survey else f"""
    <div class="card">
      <h3 style="font-size:15px;margin-bottom:8px;">📤 제출 대상자 명단 업로드</h3>
      <p style="font-size:12px;color:#888;margin-bottom:8px;">
        엑셀 컬럼: <b>A=지점명 / B=이름 / C=연락처(선택)</b> (1행 헤더). 업로드하면 기존 명단은 전체 교체됩니다.
      </p>
      <div style="display:flex;gap:8px;align-items:center;">
        <input type="file" id="targetListFile" accept=".xlsx,.xls" style="flex:1;">
        <button class="btn" type="button" onclick="uploadTargetList()">업로드</button>
        {'<button class="btn btn-red" type="button" onclick="clearTargetList()">명단 초기화</button>' if target_rows else ''}
      </div>
      <div id="targetUploadResult" style="margin-top:8px;font-size:13px;"></div>
    </div>
    """

    anonymous_notice_html = '<div class="card" style="background:#EFF6FF;border:1px solid #93C5FD;"><p style="font-size:13px;color:#1E40AF;">🔒 무기명 설문입니다. 응답은 완전 익명으로 저장되며, 제출자 식별·재제출요청·명단관리·팀즈알림 기능은 사용할 수 없습니다.</p></div>' if is_anonymous_survey else ""

    # 1. 상단 타이틀 및 안내 영역
    content = f"""
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">
      <a href="/master/survey" style="color:#1E2761;">← 설문 관리</a>
      <h2>📊 {survey['title']} — 제출현황</h2>
    </div>

    {anonymous_notice_html}
    {upload_section_html}
    {target_section_html}

    <div class="card">
      <form method="get" action="/master/survey/{survey_id}/responses" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;">
        <div style="flex:1;min-width:150px;">
          <label style="font-size:12px;color:#888;">지점 필터</label>
          <select name="filter_branch" style="margin-top:4px;">{branch_options_html}</select>
        </div>
        <button class="btn" type="submit">검색</button>
        <a href="/master/survey/{survey_id}/responses" style="padding:10px 14px;background:#eee;
            border-radius:8px;font-size:13px;text-decoration:none;color:#555;">초기화</a>
        <a href="/master/survey/{survey_id}/responses/export?filter_branch={filter_branch}"
            class="btn" style="text-decoration:none;background:#22C55E;">⬇️ 엑셀 다운로드</a>
      </form>
    </div>
    """

    resubmit_btn_html = '' if is_anonymous_survey else '<button type="button" class="btn" id="svRespResubmitBtn" style="background:#F59E0B;font-size:12px;padding:6px 12px;">재제출 요청</button>'

    # 2. 응답 테이블 및 폼 영역
    content += f"""
    <div class="card">
      <form method="post" action="/master/survey/{survey_id}/responses/request-resubmit" id="svResponseForm">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
          <span style="font-size:13px;color:#888;">{len(responses)}건 제출됨</span>
          <div style="display:flex;gap:8px;">
            <button type="button" class="btn" id="svRespSelectAllBtn" style="background:#64748B;font-size:12px;padding:6px 12px;">전체선택</button>
            {resubmit_btn_html}
            <button type="button" class="btn btn-red" id="svRespDeleteBtn" style="font-size:12px;padding:6px 12px;">완전삭제</button>
          </div>
        </div>
        <table>
          <thead><tr>
            <th style="width:36px;text-align:center;"><input type="checkbox" id="svRespAllCheck" style="width:16px;height:16px;"></th>
            <th>지점</th><th>작성자</th><th>답변 내역</th><th>상태</th><th>제출/수정일시</th>
          </tr></thead>
          <tbody>{rows_html}</tbody>
        </table>
      </form>
    </div>
    <form method="post" action="/master/survey/{survey_id}/responses/delete" id="svResponseDeleteForm"></form>
    <form method="post" action="/master/survey/{survey_id}/target-list/clear" id="targetListClearForm"></form>
    """

    # 3. 자바스크립트 영역
    content += f"""
    <script>
      (function() {{
        var allCheck = document.getElementById('svRespAllCheck');
        var selectBtn = document.getElementById('svRespSelectAllBtn');
        function applyAll(checked) {{
          document.querySelectorAll('.sv-resp-check').forEach(function(c) {{ c.checked = checked; }});
          if (allCheck) allCheck.checked = checked;
        }}
        if (allCheck) {{ allCheck.addEventListener('click', function() {{ applyAll(allCheck.checked); }}); }}
        if (selectBtn) {{
          selectBtn.addEventListener('click', function() {{
            var next = !(allCheck && allCheck.checked);
            applyAll(next);
          }});
        }}
        var resubmitBtn = document.getElementById('svRespResubmitBtn');
        if (resubmitBtn) {{
          resubmitBtn.addEventListener('click', function() {{
            var checked = document.querySelectorAll('.sv-resp-check:checked');
            if (checked.length === 0) {{ alert('재제출을 요청할 항목을 선택하세요.'); return; }}
            if (confirm(checked.length + '건에 대해 재제출을 요청합니다. 작성자에게 재제출 알림이 표시됩니다. 계속할까요?')) {{
              document.getElementById('svResponseForm').submit();
            }}
          }});
        }}
        var deleteBtn = document.getElementById('svRespDeleteBtn');
        if (deleteBtn) {{
          deleteBtn.addEventListener('click', function() {{
            var checked = document.querySelectorAll('.sv-resp-check:checked');
            if (checked.length === 0) {{ alert('삭제할 항목을 선택하세요.'); return; }}
            if (confirm(checked.length + '건을 완전 삭제합니다. 되돌릴 수 없습니다. 계속할까요?')) {{
              var deleteForm = document.getElementById('svResponseDeleteForm');
              checked.forEach(function(c) {{
                var hidden = document.createElement('input');
                hidden.type = 'hidden';
                hidden.name = 'selected_ids';
                hidden.value = c.value;
                deleteForm.appendChild(hidden);
              }});
              deleteForm.submit();
            }}
          }});
        }}
      }})();

      async function uploadTargetList() {{
        const fileEl = document.getElementById('targetListFile');
        if (!fileEl.files.length) {{ alert('파일을 선택하세요.'); return; }}
        const formData = new FormData();
        formData.append('file', fileEl.files[0]);
        document.getElementById('targetUploadResult').innerText = '업로드 중...';
        const res = await fetch('/master/survey/{survey_id}/target-list/upload', {{
          method: 'POST', body: formData
        }});
        const data = await res.json();
        if (res.ok) {{
          document.getElementById('targetUploadResult').innerText = '완료: ' + data.inserted + '명 등록';
          setTimeout(() => location.reload(), 1000);
        }} else {{
          document.getElementById('targetUploadResult').innerText = '오류: ' + (data.detail || '업로드 실패');
        }}
      }}

      function clearTargetList() {{
        if (!confirm('제출 대상자 명단을 전체 삭제합니다. 계속할까요?')) return;
        document.getElementById('targetListClearForm').submit();
      }}
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "master"))


@app.post("/master/survey/{survey_id}/responses/request-resubmit")
async def master_survey_responses_request_resubmit(
    survey_id: int, request: Request, session_token: str = Cookie(default=None)
):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    form = await request.form()
    ids = form.getlist("selected_ids")
    if ids:
        conn = get_conn()
        conn.execute(
            f"UPDATE survey_response SET status='resubmit_requested' WHERE id IN ({','.join('?' for _ in ids)}) AND survey_id=?",
            [int(i) for i in ids] + [survey_id]
        )
        conn.commit()
        conn.close()
    return RedirectResponse(url=f"/master/survey/{survey_id}/responses", status_code=303)


@app.post("/master/survey/{survey_id}/target-list/upload")
async def master_survey_target_list_upload(survey_id: int, request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    form = await request.form()
    file = form.get("file")
    if not file:
        return JSONResponse(status_code=400, content={"detail": "파일이 없습니다."})

    import openpyxl
    from io import BytesIO
    raw = await file.read()
    wb = openpyxl.load_workbook(BytesIO(raw), data_only=True)
    ws = wb.active
    if ws is None:
        return JSONResponse(status_code=400, content={"detail": "시트를 찾을 수 없습니다."})

    branch_map = {}
    for b in get_branches():
        branch_map[b["branch_name"]] = b["branch_code"]
        branch_map[b["branch_name"].replace(" ", "")] = b["branch_code"]
        branch_map[b["branch_code"]] = b["branch_code"]

    conn = get_conn()
    conn.execute("DELETE FROM survey_target_list WHERE survey_id=?", (survey_id,))

    inserted = 0
    for row in ws.iter_rows(min_row=2, values_only=True):
        if not row or not row[0]:
            continue
        branch_name_raw = str(row[0]).strip()
        writer_name = str(row[1]).strip() if len(row) > 1 and row[1] else ""
        contact = str(row[2]).strip() if len(row) > 2 and row[2] else None

        if not writer_name:
            continue

        branch_code = (branch_map.get(branch_name_raw)
                       or branch_map.get(branch_name_raw.replace(" ", ""))
                       or branch_name_raw)
        branch_name = next((b["branch_name"] for b in get_branches() if b["branch_code"] == branch_code), branch_name_raw)

        try:
            conn.execute("""
                INSERT INTO survey_target_list (survey_id, branch_code, branch_name, writer_name, contact)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT (survey_id, branch_code, writer_name) DO UPDATE SET contact=excluded.contact
            """, (survey_id, branch_code, branch_name, writer_name, contact))
            inserted += 1
        except Exception:
            continue

    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok", "inserted": inserted})

@app.post("/master/survey/upload-image")
async def master_survey_upload_image(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    form = await request.form()
    file = form.get("file")
    if not file:
        return JSONResponse(status_code=400, content={"detail": "파일이 없습니다."})

    filename = getattr(file, "filename", "") or ""
    ext = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    allowed_ext = {"jpg", "jpeg", "png", "gif", "webp"}
    if ext not in allowed_ext:
        return JSONResponse(status_code=400, content={"detail": "이미지 파일(jpg/jpeg/png/gif/webp)만 업로드 가능합니다."})

    raw = await file.read()
    max_size = 5 * 1024 * 1024  # 5MB
    if len(raw) > max_size:
        return JSONResponse(status_code=400, content={"detail": "파일 크기는 5MB 이하만 가능합니다."})

    content_type_map = {
        "jpg": "image/jpeg", "jpeg": "image/jpeg", "png": "image/png",
        "gif": "image/gif", "webp": "image/webp"
    }
    content_type = content_type_map.get(ext, "application/octet-stream")

    import uuid
    new_filename = f"{uuid.uuid4().hex}.{ext}"

    supabase_url = "https://fjznuesrbrwcqbdghegn.supabase.co"
    service_role_key = os.environ.get("PURCHASE_SUPABASE_SERVICE_ROLE_KEY", "")
    if not service_role_key:
        return JSONResponse(status_code=500, content={"detail": "서버 설정 오류: service_role 키가 없습니다."})

    upload_url = f"{supabase_url}/storage/v1/object/survey-images/{new_filename}"

    async with httpx.AsyncClient() as client:
        resp = await client.put(
            upload_url,
            content=raw,
            headers={
                "Authorization": f"Bearer {service_role_key}",
                "apikey": service_role_key,
                "Content-Type": content_type,
                "x-upsert": "true"
            },
            timeout=30.0
        )

    if resp.status_code not in (200, 201):
        return JSONResponse(status_code=500, content={
            "detail": f"업로드 실패 (Supabase 응답 {resp.status_code}): {resp.text[:200]}"
        })

    public_url = f"{supabase_url}/storage/v1/object/public/survey-images/{new_filename}"

    return JSONResponse(content={"status": "ok", "url": public_url})
 
 
