@app.get("/api/cron/send-scheduled-messages")
async def cron_send_scheduled_messages(authorization: str = Header(default="")):
    expected = f"Bearer {os.environ.get('CRON_SECRET', '')}"
    if authorization != expected:
        return JSONResponse(status_code=401, content={"detail": "인증 실패"})
    if not _cron_job_enabled("send-scheduled-messages"):
        return JSONResponse(content={"status": "disabled", "detail": "크론 관리 페이지에서 자동 실행이 꺼져 있습니다."})

    try:
        from datetime import date
        today = date.today()
        conn = get_conn()
        schedules = conn.execute("SELECT * FROM teams_scheduled_message WHERE active = TRUE").fetchall()

        sent_count = 0
        for s in schedules:
            start = s["start_date"] if isinstance(s["start_date"], date) else datetime.strptime(str(s["start_date"]), "%Y-%m-%d").date()
            if today < start:
                continue
            days_since_start = (today - start).days
            if days_since_start % s["interval_days"] != 0:
                continue
            if s["last_sent_date"]:
                last = s["last_sent_date"] if isinstance(s["last_sent_date"], date) else datetime.strptime(str(s["last_sent_date"]), "%Y-%m-%d").date()
                if last == today:
                    continue

            codes = s["target_codes"].split(",")
            for code in codes:
                if s["target_type"] == "branch":
                    send_teams_notification(code, s["title"] or "반복 알림", s["message"], sent_by="system_cron")
                else:
                    row = conn.execute("SELECT webhook_url, channel_name FROM teams_custom_channel WHERE id=?", (code,)).fetchone()
                    if row:
                        send_teams_notification_to_url(row["webhook_url"], s["title"] or "반복 알림", s["message"], sent_by="system_cron", target_label=f"custom:{row['channel_name']}")
            conn.execute("UPDATE teams_scheduled_message SET last_sent_date=? WHERE id=?", (today.isoformat(), s["id"]))
            sent_count += 1

        conn.commit()
        conn.close()
        return JSONResponse(content={"processed": sent_count, "date": today.isoformat()})
    except Exception as e:
        err_msg = str(e)[:500]
        report_cron_failure("send-scheduled-messages", err_msg)
        return JSONResponse(status_code=500, content={"detail": err_msg})

@app.get("/api/cron/send-unsubmitted-reminder")
async def cron_send_unsubmitted_reminder(authorization: str = Header(default="")):
    expected = f"Bearer {os.environ.get('CRON_SECRET', '')}"
    if authorization != expected:
        return JSONResponse(status_code=401, content={"detail": "인증 실패"})
    if not _cron_job_enabled("send-unsubmitted-reminder"):
        return JSONResponse(content={"status": "disabled", "detail": "크론 관리 페이지에서 자동 실행이 꺼져 있습니다."})

    try:
        from datetime import date
        today = date.today()

        conn = get_conn()

        setting_row = conn.execute(
            "SELECT value FROM system_settings WHERE key='unsubmitted_reminder_enabled'"
        ).fetchone()
        reminder_enabled = (setting_row["value"] == "true") if setting_row else True

        if not reminder_enabled:
            conn.close()
            return JSONResponse(content={"skipped": True, "reason": "reminder disabled", "date": today.isoformat()})

        # 5, 10, 15, 20, 25, 30일에만 발송 (그 외 날짜에 호출되면 조용히 스킵)
        if today.day not in (5, 10, 15, 20, 25, 30):
            conn.close()
            return JSONResponse(content={"skipped": True, "reason": "not a reminder day", "date": today.isoformat()})

        # vendor-eval/status와 동일한 "전월" 계산 로직
        prev_month_num = today.month - 1 if today.month > 1 else 12
        prev_month_year = today.year if today.month > 1 else today.year - 1
        month = f"{prev_month_year}-{prev_month_num:02d}"

        total_vendors = conn.execute("SELECT COUNT(*) as cnt FROM vendor_master").fetchone()["cnt"]

        unsubmitted_branches = []
        branches = [b for b in get_branches(branch_type='branch') if b["branch_code"] not in VENDOR_EVAL_EXCLUDED_BRANCH_CODES]
        for b in branches:
            done_cnt = conn.execute("""
                SELECT COUNT(DISTINCT vendor_name) as cnt FROM vendor_evaluation_v2
                WHERE branch_code = ? AND eval_month = ? AND status = 'completed'
            """, (b["branch_code"], month)).fetchone()["cnt"]

            is_complete = (done_cnt >= total_vendors and total_vendors > 0)
            if not is_complete:
                unsubmitted_branches.append({
                    "branch_code": b["branch_code"],
                    "branch_name": b["branch_name"],
                    "done_cnt": done_cnt,
                    "total_vendors": total_vendors
                })

        sent_count = 0
        for ub in unsubmitted_branches:
            message = (
                f"{month} 거래처평가 미제출 안내드립니다.\n"
                f"현재 진행률: {ub['done_cnt']} / {ub['total_vendors']}\n"
                f"빠른 시일 내 제출 부탁드립니다."
            )
            send_teams_notification(
                ub["branch_code"],
                "거래처평가 미제출 알림",
                message,
                link_url="https://inventory-sync-teal.vercel.app/vendor-eval",
                link_text="거래처 평가하러 가기",
                sent_by="system_cron"
            )
            sent_count += 1

        conn.close()
        return JSONResponse(content={"date": today.isoformat(), "month": month, "sent_count": sent_count})
    except Exception as e:
        err_msg = str(e)[:500]
        report_cron_failure("send-unsubmitted-reminder", err_msg)
        return JSONResponse(status_code=500, content={"detail": err_msg})

@app.get("/api/cron/send-survey-unsubmitted-reminder")
async def cron_send_survey_unsubmitted_reminder(authorization: str = Header(default="")):
    expected = f"Bearer {os.environ.get('CRON_SECRET', '')}"
    if authorization != expected:
        return JSONResponse(status_code=401, content={"detail": "인증 실패"})
    if not _cron_job_enabled("send-survey-unsubmitted-reminder"):
        return JSONResponse(content={"status": "disabled", "detail": "크론 관리 페이지에서 자동 실행이 꺼져 있습니다."})

    from datetime import date
    today = date.today()

    conn = get_conn()
    surveys = conn.execute(
        "SELECT * FROM survey WHERE reminder_interval_days IS NOT NULL AND active = TRUE"
    ).fetchall()

    public_base_url = os.getenv("PUBLIC_SERVER_URL", "https://inventory-sync-teal.vercel.app")

    total_processed = 0
    total_sent = 0

    for s in surveys:
        last_sent = s["reminder_last_sent_date"]
        if last_sent:
            days_since = (today - last_sent).days
            if days_since < s["reminder_interval_days"]:
                continue
        # last_sent가 없으면 최초 1회는 즉시 발송 대상

        target_rows = conn.execute(
            "SELECT * FROM survey_target_list WHERE survey_id=?", (s["id"],)
        ).fetchall()
        if not target_rows:
            continue

        submitted_keys = {(r["branch_code"], r["writer_name"]) for r in conn.execute(
            "SELECT DISTINCT branch_code, writer_name FROM survey_response WHERE survey_id=?", (s["id"],)
        ).fetchall()}

        unsubmitted_branch_codes = set()
        for t in target_rows:
            if (t["branch_code"], t["writer_name"]) not in submitted_keys:
                unsubmitted_branch_codes.add(t["branch_code"])

        if not unsubmitted_branch_codes:
            conn.execute(
                "UPDATE survey SET reminder_last_sent_date=? WHERE id=?", (today.isoformat(), s["id"])
            )
            total_processed += 1
            continue

        survey_link = f"{public_base_url}/survey/{s['id']}"
        message = f"{s['title']} 설문이 미제출됐습니다. 제출해주시기 바랍니다."

        for branch_code in unsubmitted_branch_codes:
            send_teams_notification(
                branch_code,
                f"{s['title']} 미제출 알림",
                message,
                link_url=survey_link,
                link_text="설문 작성하러 가기",
                sent_by="system_cron_survey_reminder"
            )
            total_sent += 1

        conn.execute(
            "UPDATE survey SET reminder_last_sent_date=? WHERE id=?", (today.isoformat(), s["id"])
        )
        total_processed += 1

    conn.commit()
    conn.close()

    return JSONResponse(content={
        "processed_surveys": total_processed,
        "sent_count": total_sent,
        "date": today.isoformat()
    })

@app.get("/api/cron/check-qr-raw-mismatch")
async def cron_check_qr_raw_mismatch(authorization: str = Header(default="")):
    expected = f"Bearer {os.environ.get('CRON_SECRET', '')}"
    if authorization != expected:
        return JSONResponse(status_code=401, content={"detail": "인증 실패"})
    if not _cron_job_enabled("check-qr-raw-mismatch"):
        return JSONResponse(content={"status": "disabled", "detail": "크론 관리 페이지에서 자동 실행이 꺼져 있습니다."})

    try:
        conn = get_conn()
        teams_setting_row = conn.execute(
            "SELECT value FROM system_settings WHERE key='qr_raw_mismatch_teams_enabled'"
        ).fetchone()
        teams_enabled = (teams_setting_row["value"] == "true") if teams_setting_row else False

        inventory_rows = conn.execute("SELECT * FROM inventory").fetchall()
        conn.close()

        raw_rows = fetch_raw_inventory()
        raw_map = {f"{r['branch_code']}|{r['item_code']}": r["quantity"] for r in raw_rows}

        mismatch_by_branch = {}
        for r in inventory_rows:
            key = f"{r['branch_code']}|{r['item_code']}"
            raw_qty = raw_map.get(key, 0)
            diff = r["quantity"] - raw_qty
            if diff != 0:
                mismatch_by_branch.setdefault(r["branch_code"], []).append({
                    "item_name": r["item_name"],
                    "item_code": r["item_code"],
                    "diff": diff
                })

        branches = get_branches(branch_type='branch')
        branch_codes_set = {b["branch_code"] for b in branches}

        sent_count = 0
        for branch_code, items in mismatch_by_branch.items():
            if branch_code not in branch_codes_set:
                continue

            count = len(items)
            preview = "\n".join(f"{it['item_name']}_{it['diff']:+d}" for it in items[:5])
            more_note = f"\n...외 {count - 5}건" if count > 5 else ""

            title = "재고 불일치 알림"
            body = f"불일치 품목 {count}건 발견\n{preview}{more_note}"

            send_push_notification(branch_code, title, body, event_type="qr_raw_mismatch", url="/")
            if teams_enabled:
                send_teams_notification(branch_code, title, body, sent_by="system_cron_qr_raw_mismatch")
            sent_count += 1

        return JSONResponse(content={
            "processed_branches": sent_count,
            "total_mismatch_branches": len(mismatch_by_branch)
        })
    except Exception as e:
        err_msg = str(e)[:500]
        report_cron_failure("check-qr-raw-mismatch", err_msg)
        return JSONResponse(status_code=500, content={"detail": err_msg})

@app.get("/api/cron/check-new-purchase")
async def cron_check_new_purchase(authorization: str = Header(default="")):
    expected = f"Bearer {os.environ.get('CRON_SECRET', '')}"
    if authorization != expected:
        return JSONResponse(status_code=401, content={"detail": "인증 실패"})
    if not _cron_job_enabled("check-new-purchase"):
        return JSONResponse(content={"status": "disabled", "detail": "크론 관리 페이지에서 자동 실행이 꺼져 있습니다."})

    try:
        conn = get_conn()
        teams_setting_row = conn.execute(
            "SELECT value FROM system_settings WHERE key='purchase_new_teams_enabled'"
        ).fetchone()
        teams_enabled = (teams_setting_row["value"] == "true") if teams_setting_row else False

        last_check_row = conn.execute(
            "SELECT value FROM system_settings WHERE key='purchase_new_last_checked_at'"
        ).fetchone()
        conn.close()

        from datetime import datetime, timedelta, timezone
        now = datetime.now(timezone.utc)
        if last_check_row and last_check_row["value"]:
            try:
                last_checked = datetime.fromisoformat(last_check_row["value"])
            except Exception:
                last_checked = now - timedelta(minutes=10)
        else:
            last_checked = now - timedelta(minutes=10)

        rows, err = await fetch_purchase_history(limit=500)
        if err:
            report_cron_failure("check-new-purchase", err)
            return JSONResponse(status_code=500, content={"detail": err})

        new_rows = [r for r in rows if r.get("registered_at") and r["registered_at"] > last_checked.isoformat()]

        branches = get_branches(branch_type='branch')
        branch_name_to_code = {b["branch_name"]: b["branch_code"] for b in branches}

        # 지점별로 신규 발주를 묶음 (요약 알림 1건으로 발송하기 위함)
        rows_by_branch: Dict[str, list] = {}
        for r in new_rows:
            branch_name = r.get("branch", "")
            branch_code = branch_name_to_code.get(branch_name)
            if not branch_code:
                continue
            rows_by_branch.setdefault(branch_code, []).append(r)

        sent_count = 0
        for branch_code, branch_rows in rows_by_branch.items():
            branch_name = branch_rows[0].get("branch", "")
            count = len(branch_rows)

            preview = "\n".join(
                f"{r.get('vendor', '-')} {r.get('product_name', '-')}_{r.get('quantity', '-')}개"
                for r in branch_rows[:10]
            )
            more_note = f"\n...외 {count - 10}건" if count > 10 else ""

            title = "발주내역 알림"
            body = f"{branch_name} 신규 발주 {count}건\n{preview}{more_note}"

            send_push_notification(branch_code, title, body, event_type="purchase_new", url="/purchase-history")
            if teams_enabled:
                send_teams_notification(branch_code, title, body, sent_by="system_cron_purchase_new")
            sent_count += 1

        conn2 = get_conn()
        existing_ts = conn2.execute(
            "SELECT value FROM system_settings WHERE key='purchase_new_last_checked_at'"
        ).fetchone()
        if existing_ts:
            conn2.execute(
                "UPDATE system_settings SET value=?, updated_at=NOW() WHERE key='purchase_new_last_checked_at'",
                (now.isoformat(),)
            )
        else:
            conn2.execute(
                "INSERT INTO system_settings (key, value) VALUES ('purchase_new_last_checked_at', ?)",
                (now.isoformat(),)
            )
        conn2.commit()
        conn2.close()

        return JSONResponse(content={"new_count": len(new_rows), "sent_count": sent_count})
    except Exception as e:
        err_msg = str(e)[:500]
        report_cron_failure("check-new-purchase", err_msg)
        return JSONResponse(status_code=500, content={"detail": err_msg})

def _eod_alert_candidates(lookback_days: int = 56) -> dict:
    """긴급발주 알럿 대상 계산 — 화요일 발주→목요일 도착 주기 기준, 수요일 전 소진 예상 지점×품번.
    안전재고 무관: 현재고(raw_inventory) < 일평균판매×도착까지일수 이면 대상.
    제외: product_master 미등록/소모품/전체미발주, 판매 0, eod_alert_exclusion 등록 건.
    반환: {"today","arrival","days_left","items":[{branch_name,branch_code,item_code,item_name,daily,stock,need,shortage,depletion,suggest_qty,moq}]}
    """
    import math
    from datetime import date, timedelta

    today = date.today()
    thu = today + timedelta(days=(3 - today.weekday()) % 7)  # 이번주 목요일
    if thu <= today:
        thu += timedelta(days=7)  # 이미 지났으면 다음주 목요일
    days_left = (thu - today).days
    start = today - timedelta(days=lookback_days)

    conn = get_conn()
    try:
        sales_rows = conn.execute("""
            SELECT branch_name, item_code, MAX(item_name) AS item_name, SUM(quantity) AS qty
            FROM sales_records
            WHERE sale_date >= ? AND sale_date < ? AND item_code IS NOT NULL AND item_code <> ''
            GROUP BY branch_name, item_code
        """, (start.isoformat(), today.isoformat())).fetchall()
        raw_rows = conn.execute(
            "SELECT branch_code, item_code, quantity FROM raw_inventory"
        ).fetchall()
        pm_rows = conn.execute("""
            SELECT DISTINCT ON (item_code) item_code, moq, is_consumable, order_excluded
            FROM product_master WHERE item_code IS NOT NULL AND item_code <> ''
            ORDER BY item_code, id
        """).fetchall()
        exc_rows = conn.execute(
            "SELECT branch_code, item_code FROM eod_alert_exclusion"
        ).fetchall()
        ss_rows = conn.execute(
            "SELECT branch_name, item_name, qty, safety_qty FROM safety_stock"
        ).fetchall()
    finally:
        conn.close()

    raw_map = {(r["branch_code"], r["item_code"]): (r["quantity"] or 0) for r in raw_rows}
    ss_map = {}
    for r in ss_rows:
        v = r["qty"] or r["safety_qty"] or 0
        ss_map[(r["branch_name"], r["item_name"])] = v
    pm_map = {r["item_code"]: r for r in pm_rows}
    exc_set = {(r["branch_code"], r["item_code"]) for r in exc_rows}
    b2c = {b["branch_name"]: b["branch_code"] for b in get_branches(branch_type='branch')}

    items = []
    for r in sales_rows:
        bn, ic = r["branch_name"], r["item_code"]
        bc = b2c.get(bn)
        if not bc:
            continue
        pm = pm_map.get(ic)
        if not pm or pm["is_consumable"] or pm["order_excluded"]:
            continue
        daily = (r["qty"] or 0) / float(lookback_days)
        if daily <= 0:
            continue
        stock = raw_map.get((bc, ic), 0) or 0
        need = daily * days_left
        if stock >= need:
            continue
        if (bc, ic) in exc_set:
            continue
        shortage = need - stock
        moq = pm["moq"] or 1
        suggest = math.ceil(shortage / moq) * moq if shortage > 0 else 0
        depletion = today if stock <= 0 else today + timedelta(days=math.ceil(stock / daily))
        items.append({
            "branch_name": bn, "branch_code": bc, "item_code": ic,
            "item_name": r["item_name"] or ic,
            "daily": round(daily, 2), "stock": stock,
            "need": round(need, 1), "shortage": round(shortage, 1),
            "safety": ss_map.get((bn, r["item_name"]), 0),
            "depletion": depletion.isoformat(), "arrival": thu.isoformat(),
            "moq": moq, "suggest_qty": suggest,
        })

    items.sort(key=lambda x: (x["branch_name"], -x["daily"]))
    return {
        "today": today.isoformat(), "arrival": thu.isoformat(),
        "days_left": days_left, "lookback_days": lookback_days,
        "items": items,
    }


@app.post("/master/teams-webhook/test-eod-alert")
async def master_test_eod_alert(request: Request, session_token: str = Cookie(default=None)):
    """긴급발주 알럿 테스트 발송 — 실제 계산 결과를 선택 채널로만 전송."""
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=401, content={"detail": "인증 실패"})

    data = await request.json()
    target_branch_code = data.get("branch_code", "").strip()
    if not target_branch_code:
        return JSONResponse(status_code=400, content={"detail": "테스트 대상 채널 코드가 필요합니다."})

    result = _eod_alert_candidates()
    by_branch: Dict[str, list] = {}
    for it in result["items"]:
        by_branch.setdefault(it["branch_name"], []).append(it)

    sent_count = 0
    for bn, its in by_branch.items():
        preview = "\n".join(
            f"- {it['item_name']}: 현재 재고 {it['stock']}개 / 예상 소진량 {it['need']}개 / 안전재고 {it['safety']}개"
            for it in its[:8]
        )
        more = f"\n...외 {len(its) - 8}건" if len(its) > 8 else ""
        title = f"🧪[테스트] 🚨 긴급발주 검토 알림 ({bn})"
        body = (
            f"[테스트] 실제 대상 지점: {bn}\n"
            f"기준일 {result['today']} / 도착 예정 {result['arrival']} (D-{result['days_left']}일)\n"
            f"수요일 전 소진 예상 {len(its)}건\n{preview}{more}"
        )
        send_teams_notification(target_branch_code, title, body, sent_by=f"test_by_{user['login_id']}")
        sent_count += 1

    return JSONResponse(content={
        "success": True,
        "item_count": len(result["items"]),
        "branch_count": sent_count,
        "arrival": result["arrival"],
    })


@app.post("/master/toggle-eod-alert")
async def master_toggle_eod_alert(session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)

    conn = get_conn()
    row = conn.execute(
        "SELECT value FROM system_settings WHERE key='eod_alert_enabled'"
    ).fetchone()
    current = (row["value"] == "true") if row else False
    new_value = "false" if current else "true"

    if row:
        conn.execute(
            "UPDATE system_settings SET value=?, updated_at=NOW() WHERE key='eod_alert_enabled'",
            (new_value,)
        )
    else:
        conn.execute(
            "INSERT INTO system_settings (key, value) VALUES ('eod_alert_enabled', ?)",
            (new_value,)
        )
    conn.commit()
    conn.close()
    return RedirectResponse(url="/master/notification-settings", status_code=303)


