@app.get("/master/purchase-order/product-settings", response_class=HTMLResponse)
async def purchase_order_product_settings_page(
    session_token: str = Cookie(default=None),
    search_item: str = "",
    filter_branch: str = "",
    filter_consumable: str = "",
    sort_by: str = "item_name",
    sort_dir: str = "asc",
    show_hidden: str = ""
):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "product-settings"):
        return RedirectResponse(url="/master", status_code=303)

    allowed_sort_cols = {"item_name", "branch_name", "lead_time_days", "moq", "is_consumable", "purchase_price"}
    if sort_by not in allowed_sort_cols:
        sort_by = "item_name"
    sort_dir_sql = "DESC" if sort_dir == "desc" else "ASC"

    conn = get_conn()
    query = "SELECT * FROM product_master WHERE 1=1"
    params: list = []
    if not show_hidden:
        query += " AND (order_excluded IS NOT TRUE)"
    if search_item:
        query += " AND (item_name LIKE ? OR item_code LIKE ?)"
        params.append(f"%{search_item}%")
        params.append(f"%{search_item}%")
    if filter_branch:
        query += " AND branch_name = ?"
        params.append(filter_branch)
    if filter_consumable == "yes":
        query += " AND is_consumable = TRUE"
    elif filter_consumable == "no":
        query += " AND is_consumable = FALSE"
    query += f" ORDER BY {sort_by} {sort_dir_sql} LIMIT 300"
    rows = conn.execute(query, params).fetchall()

    monthly_exc_rows = conn.execute(
        "SELECT item_code, item_name, branch_code FROM purchase_order_monthly_exception"
    ).fetchall()
    eod_exc_rows = conn.execute(
        "SELECT item_code, branch_code FROM eod_alert_exclusion"
    ).fetchall()
    conn.close()

    monthly_exc_map: Dict[str, list] = {}
    for r in monthly_exc_rows:
        monthly_exc_map.setdefault(r["item_code"] or r["item_name"], []).append(r["branch_code"])
    eod_exc_map: Dict[str, list] = {}
    for r in eod_exc_rows:
        eod_exc_map.setdefault(r["item_code"], []).append(r["branch_code"])
        
    branches = get_branches(branch_type='branch')
    branch_options_json = json.dumps(
        [{"code": b["branch_code"], "name": b["branch_name"]} for b in branches], ensure_ascii=False
    )
    branch_filter_options = '<option value="">전체 지점</option>'
    for b in branches:
        sel = "selected" if filter_branch == b["branch_name"] else ""
        branch_filter_options += f'<option value="{b["branch_name"]}" {sel}>{b["branch_name"]}</option>'

    import html as _h
    rows_html = ""
    if not rows:
        rows_html = '<tr><td colspan="17" style="text-align:center;padding:20px;color:#888;">등록된 상품이 없습니다.</td></tr>'
    else:
        for r in rows:
            consumable_checked = "checked" if r["is_consumable"] else ""
            exc_branches = monthly_exc_map.get(r["item_code"] or r["item_name"], [])
            exc_badge = (
                f'<span class="badge-green">{len(exc_branches)}개 지점</span>'
                if exc_branches else '<span style="color:#888;font-size:11px;">없음</span>'
            )
            eod_branches = eod_exc_map.get(r["item_code"] or "", [])
            eod_badge = (
                f'<span class="badge-green">{len(eod_branches)}개 지점</span>'
                if eod_branches else '<span style="color:#888;font-size:11px;">없음</span>'
            )
            safe_item_name = (r["item_name"] or "").replace("'", "")
            safe_item_code = (r["item_code"] or "").replace("'", "")
            item_code_attr = _h.escape(str(r["item_code"] or ""), quote=True)
            item_name_attr = _h.escape(str(r["item_name"] or ""), quote=True)
            rows_html += f"""
            <tr>
              <td style="text-align:center;"><input type="checkbox" class="pm-row-check" data-id="{r['id']}" data-itemcode="{item_code_attr}" data-itemname="{item_name_attr}" style="width:18px;height:18px;"></td>
              <td class="pm-col-branch">{r['branch_name'] or ''}</td>
              <td class="pm-col-item">{r['item_name'] or ''}</td>
              <td class="pm-col-code">{r['item_code'] or ''}</td>
              <td class="pm-col-price"><input type="number" class="pm-price" data-id="{r['id']}" value="{r['purchase_price'] or 0}"></td>
              <td class="pm-col-supplier">{r['supplier'] or ''}</td>
              <td class="pm-col-tax">{r['tax_setting'] or ''}</td>
              <td class="pm-col-leadtime"><input type="number" class="pm-leadtime" data-id="{r['id']}" value="{r['lead_time_days'] or 0}"></td>
              <td class="pm-col-moq"><input type="number" class="pm-moq" data-id="{r['id']}" value="{r['moq'] or 1}"></td>
              <td class="pm-col-minsafe"><input type="number" class="pm-minsafe" data-id="{r['id']}" value="{r['min_safety_qty'] if r['min_safety_qty'] is not None else ''}" min="0" placeholder="공통" style="width:80px;"></td>
              <td class="pm-col-consumable" style="text-align:center;"><input type="checkbox" class="pm-consumable" data-id="{r['id']}" {consumable_checked} style="width:18px;height:18px;"></td>
              <td class="pm-col-category"><input type="text" class="pm-category" data-id="{r['id']}" value="{r['category'] or ''}"></td>
              <td class="pm-col-ptype"><input type="text" class="pm-ptype" data-id="{r['id']}" value="{r['product_type'] or ''}"></td>
              <td class="pm-col-ctype"><input type="text" class="pm-ctype" data-id="{r['id']}" value="{r['consumable_type'] or ''}"></td>
              <td class="pm-col-exc">
                {exc_badge}
                <button class="btn" style="font-size:11px;padding:4px 8px;background:#8B5CF6;" onclick="openMonthlyExc('{safe_item_name}')">설정</button>
              </td>
              <td class="pm-col-eodexc">
                {eod_badge}
                <button class="btn" style="font-size:11px;padding:4px 8px;background:#F97316;" onclick="openEodExc('{safe_item_code}', '{safe_item_name}')">설정</button>
              </td>
              <td style="display:flex;gap:4px;">
                <button class="btn" style="font-size:12px;padding:6px 12px;" onclick="savePmRow({r['id']})">저장</button>
                {f'<button class="btn" style="font-size:12px;padding:6px 10px;background:#22C55E;" onclick="hidePmRow({r["id"]}, false)">숨김해제</button>' if r['order_excluded'] else f'<button class="btn" style="font-size:12px;padding:6px 10px;background:#F59E0B;" onclick="hidePmRow({r["id"]}, true)">숨기기</button>'}
              </td>
            </tr>
            """

    content = f"""
    {PRODUCT_SETTINGS_EXTRA_CSS}
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">
      <a href="/master/purchase-tracking" style="color:#1E2761;">← 발주 주기 트래킹</a>
      <h2>📝 상품 마스터 (단가/거래처/리드타임/MOQ/소모품)</h2>
    </div>
    {_po_unregistered_banner_html()}

    <div class="card" style="background:#EFF6FF;border:1px solid #93C5FD;">
      <p style="font-size:13px;color:#1E40AF;">상품별 단가, 거래처, 과세설정, 리드타임, MOQ, 소모품 여부를 관리합니다. 발주서 자동생성 시 이 정보를 사용합니다.</p>
    </div>

    <div class="card">
      <h3 style="margin-bottom:8px;">새 상품 수동 등록</h3>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        <input type="text" id="pmBranch" placeholder="지점명" style="flex:1;min-width:100px;">
        <input type="text" id="pmItemName" placeholder="상품명" style="flex:2;min-width:180px;">
        <input type="text" id="pmItemCode" placeholder="품번" style="flex:1;min-width:120px;">
        <input type="number" id="pmPrice" placeholder="구매금액" style="flex:1;min-width:100px;">
        <input type="text" id="pmSupplier" placeholder="거래처명" style="flex:1;min-width:100px;">
        <input type="text" id="pmTax" placeholder="과세설정(예: 과세)" style="flex:1;min-width:100px;">
        <input type="number" id="pmLeadTime" placeholder="리드타임(일)" style="flex:1;min-width:100px;">
        <input type="number" id="pmMoq" placeholder="MOQ(기본 1)" style="flex:1;min-width:100px;">
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;"><input type="checkbox" id="pmConsumable"> 소모품</label>
        <button class="btn" type="button" onclick="addPmItem()">추가</button>
      </div>
      <div id="pmAddResult" style="margin-top:8px;font-size:13px;"></div>
    </div>

    <div class="card pm-upload-box">
      <h3 style="margin-bottom:8px;">엑셀 업로드 (상품마스터 일괄 등록/갱신)</h3>
      <p style="font-size:12px;color:#1E40AF;margin-bottom:8px;">
        헤더 포함, 컬럼: 지점명 | 상품분류 | 상품명 | 상품내용 | 출고금액 | 구매금액 | 상품타입 | 품번 | 규격 | 판매금액 | 단위 | 과세설정 | ... | 리드타임 | ... | 구매처<br>
        (지점명+품번 기준으로 이미 있으면 덮어씁니다.)
      </p>
      <input type="file" id="pmExcelFile" accept=".xlsx,.xls">
      <button class="btn" type="button" onclick="uploadPmExcel()">업로드</button>
      <div id="pmUploadResult" style="margin-top:8px;font-size:13px;"></div>
    </div>

    <div class="card">
      <form method="get" action="/master/purchase-order/product-settings" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;">
        <input type="hidden" name="sort_by" value="{sort_by}">
        <input type="hidden" name="sort_dir" value="{sort_dir}">
        <input name="search_item" value="{search_item}" placeholder="상품명/품번 검색" style="flex:2;min-width:180px;">
        <select name="filter_branch" style="flex:1;min-width:120px;">{branch_filter_options}</select>
        <select name="filter_consumable" style="flex:1;min-width:120px;">
          <option value="" {'selected' if not filter_consumable else ''}>전체</option>
          <option value="yes" {'selected' if filter_consumable == 'yes' else ''}>소모품만</option>
          <option value="no" {'selected' if filter_consumable == 'no' else ''}>일반상품만</option>
        </select>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;white-space:nowrap;"><input type="checkbox" name="show_hidden" value="1" {'checked' if show_hidden else ''} onchange="this.form.submit()"> 숨김 상품도 보기</label>
        <button class="btn" type="submit">검색</button>
        <a href="/master/purchase-order/product-settings" style="padding:10px 14px;background:#eee;border-radius:8px;font-size:13px;text-decoration:none;color:#555;">초기화</a>
        <a href="/master/purchase-order/settings-guide" style="padding:10px 14px;background:#EFF6FF;border:1px solid #93C5FD;border-radius:8px;font-size:13px;text-decoration:none;color:#1E40AF;">📖 설정 설명</a>
      </form>
      <p style="font-size:13px;color:#888;margin-bottom:12px;">{len(rows)}건 (최대 300건까지 표시)</p>
      <div class="card" style="background:#F0FDF4;border:1px solid #86EFAC;margin-bottom:12px;">
        <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
          <button class="btn" type="button" onclick="saveAllPmRows()" style="background:#22C55E;">💾 화면 전체 저장</button>
          <span style="color:#ccc;">|</span>
          <span id="pmCheckedCount" style="font-size:13px;color:#555;">선택됨: 0건</span>
          <input type="number" id="pmBulkLeadTime" placeholder="리드타임 일괄값" style="width:130px;">
          <input type="number" id="pmBulkMoq" placeholder="MOQ 일괄값" style="width:110px;">
          <input type="number" id="pmBulkMin" placeholder="최소 안전재고 일괄값" min="0" style="width:150px;">
          <button class="btn" type="button" onclick="applyBulkToChecked()" style="background:#8B5CF6;">✓ 체크 항목에 적용</button>
          <span style="color:#ccc;">|</span>
          <button class="btn" type="button" onclick="openBulkMonthlyExc()" style="background:#8B5CF6;">📦 선택 품목 월예외 설정</button>
          <button class="btn" type="button" onclick="openBulkEodExc()" style="background:#F97316;">🚨 선택 품목 긴급발주 제외</button>
        </div>
        <p style="font-size:11px;color:#888;margin:6px 0 0 0;">체크한 행들을 품번 기준으로 묶어 같은 지점 설정을 한 번에 저장합니다. 월예외는 품명 기준으로 묶입니다.</p>
      </div>

      <table class="pm-table" data-colkey="pm-main" data-colw data-colver="2026-11-20" style="table-layout:fixed;min-width:1500px;"><colgroup><col style="width:44px"><col style="width:100px"><col style="width:180px"><col style="width:110px"><col style="width:100px"><col style="width:120px"><col style="width:80px"><col style="width:90px"><col style="width:70px"><col style="width:100px"><col style="width:70px"><col style="width:100px"><col style="width:90px"><col style="width:110px"><col style="width:140px"><col style="width:130px"><col style="width:140px"></colgroup>
        <thead><tr>
          <th style="text-align:center;"><input type="checkbox" id="pmCheckAll" onclick="togglePmCheckAll(this)" style="width:18px;height:18px;"></th>
          <th class="pm-col-branch">지점</th>
          <th class="pm-col-item" style="cursor:pointer;" onclick="sortPm('item_name')">상품명 {'▲' if sort_by=='item_name' and sort_dir=='asc' else ('▼' if sort_by=='item_name' else '')}</th>
          <th class="pm-col-code">품번</th>
          <th class="pm-col-price" style="cursor:pointer;" onclick="sortPm('purchase_price')">구매금액 {'▲' if sort_by=='purchase_price' and sort_dir=='asc' else ('▼' if sort_by=='purchase_price' else '')}</th>
          <th class="pm-col-supplier">거래처</th>
          <th class="pm-col-tax">과세설정</th>
          <th class="pm-col-leadtime" style="cursor:pointer;" onclick="sortPm('lead_time_days')">리드타임(일) {'▲' if sort_by=='lead_time_days' and sort_dir=='asc' else ('▼' if sort_by=='lead_time_days' else '')}</th>
          <th class="pm-col-moq" style="cursor:pointer;" onclick="sortPm('moq')">MOQ {'▲' if sort_by=='moq' and sort_dir=='asc' else ('▼' if sort_by=='moq' else '')}</th>
          <th class="pm-col-minsafe" title="상품별 최소 안전재고. 비워두면 안전재고 판매 기반 비교의 공통 최소값을 씁니다.">최소 안전재고</th>
          <th class="pm-col-consumable" style="cursor:pointer;" onclick="sortPm('is_consumable')">소모품 {'▲' if sort_by=='is_consumable' and sort_dir=='asc' else ('▼' if sort_by=='is_consumable' else '')}</th>
          <th class="pm-col-category">품류</th>
          <th class="pm-col-ptype">종류</th>
          <th class="pm-col-ctype">소모품종류</th>
          <th class="pm-col-exc">지방점 주발주 제외</th>
          <th class="pm-col-eodexc" title="긴급발주 알럿에서 제외할 지점. 체크된 지점은 소진 예상이 떠도 알럿이 나가지 않습니다.">긴급발주 제외</th><th></th>
        </tr></thead>
        <tbody>{rows_html}</tbody>
      </table>
    </div>

    <div id="monthlyExcModal" style="display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1000;align-items:center;justify-content:center;">
      <div style="background:#fff;border-radius:12px;padding:24px;max-width:420px;width:90%;max-height:80vh;overflow-y:auto;">
        <h3 id="monthlyExcTitle" style="margin-bottom:4px;">지방점 주발주 제외</h3>
        <p id="monthlyExcSub" style="font-size:12px;color:#888;margin:0 0 8px 0;">체크된 지점은 이 상품을 월 1회 발주로 분류합니다.</p>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;margin-bottom:6px;">
          <input type="checkbox" id="mexcSelectAll" onchange="toggleExcAll(this, 'mexc-branch')"> 전체 선택/해제
        </label>
        <div id="monthlyExcBranchList" style="margin-bottom:16px;"></div>
        <div style="display:flex;gap:8px;">
          <button class="btn" style="flex:1;background:#eee;color:#333;" onclick="closeMonthlyExc()">닫기</button>
          <button class="btn" style="flex:1;" onclick="saveMonthlyExc()">저장</button>
        </div>
      </div>
    </div>

    <div id="eodExcModal" style="display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1000;align-items:center;justify-content:center;">
      <div style="background:#fff;border-radius:12px;padding:24px;max-width:420px;width:90%;max-height:80vh;overflow-y:auto;">
        <h3 id="eodExcTitle" style="margin-bottom:4px;">긴급발주 제외</h3>
        <p id="eodExcSub" style="font-size:12px;color:#888;margin:0 0 8px 0;">체크된 지점은 이 상품의 소진 예상이 떠도 긴급발주 알럿이 발송되지 않습니다.</p>
        <label style="display:flex;align-items:center;gap:6px;font-size:13px;font-weight:600;margin-bottom:6px;">
          <input type="checkbox" id="eodexcSelectAll" onchange="toggleExcAll(this, 'eodexc-branch')"> 전체 선택/해제
        </label>
        <div id="eodExcBranchList" style="margin-bottom:16px;"></div>
        <div style="display:flex;gap:8px;">
          <button class="btn" style="flex:1;background:#eee;color:#333;" onclick="closeEodExc()">닫기</button>
          <button class="btn" style="flex:1;background:#F97316;" onclick="saveEodExc()">저장</button>
        </div>
      </div>
    </div>

    <script>
      const allBranches = {branch_options_json};

      function sortPm(col) {{
        const params = new URLSearchParams(window.location.search);
        const curSort = params.get('sort_by') || 'item_name';
        const curDir = params.get('sort_dir') || 'asc';
        const newDir = (curSort === col && curDir === 'asc') ? 'desc' : 'asc';
        params.set('sort_by', col);
        params.set('sort_dir', newDir);
        window.location.search = params.toString();
      }}

      let currentExcItemName = '';
      let currentMonthlyItems = [];   // name 목록 — 1개 또는 일괄
      let currentEodItems = [];       // code+name 목록 — 1개 또는 일괄

      function toggleExcAll(el, cls) {{
        document.querySelectorAll('.' + cls).forEach(cb => cb.checked = el.checked);
      }}

      function renderExcBranches(containerId, checkedSet, cls) {{
        const container = document.getElementById(containerId);
        container.innerHTML = allBranches.map(b =>
          '<label style="display:block;font-size:13px;margin-bottom:6px;"><input type="checkbox" class="' + cls + '" value="' + b.code + '" ' +
          (checkedSet.has(b.code) ? 'checked' : '') + ' style="margin-right:6px;">' + b.name + '</label>'
        ).join('');
      }}

      function checkedExcBranches(cls) {{
        return Array.from(document.querySelectorAll('.' + cls + ':checked')).map(c => c.value);
      }}

      function collectCheckedPmItems() {{
        const seenCode = new Set(), seenName = new Set();
        const codes = [], names = [];
        document.querySelectorAll('.pm-row-check:checked').forEach(cb => {{
          const code = cb.dataset.itemcode || '';
          const name = cb.dataset.itemname || '';
          if (code && !seenCode.has(code)) {{ seenCode.add(code); codes.push({{ code: code, name: name }}); }}
          if (name && !seenName.has(name)) {{ seenName.add(name); names.push(name); }}
        }});
        return {{ codes: codes, names: names }};
      }}

      async function openMonthlyExc(itemName) {{
        currentExcItemName = itemName;
        currentMonthlyItems = [{{ name: itemName }}];
        document.getElementById('monthlyExcTitle').innerText = itemName + ' — 월1회 예외 지점';
        document.getElementById('monthlyExcSub').innerText = '체크된 지점은 이 상품을 월 1회 발주로 분류합니다.';
        document.getElementById('mexcSelectAll').checked = false;
        const res = await fetch('/master/purchase-order/monthly-exception/list?item_name=' + encodeURIComponent(itemName));
        const data = await res.json();
        renderExcBranches('monthlyExcBranchList', new Set(data.branches || []), 'mexc-branch');
        document.getElementById('monthlyExcModal').style.display = 'flex';
      }}

      function openBulkMonthlyExc() {{
        const items = collectCheckedPmItems();
        if (!items.names.length) {{ alert('체크된 품목이 없습니다. 표의 체크박스로 품목을 선택하세요.'); return; }}
        currentMonthlyItems = items.names.map(n => ({{ name: n }}));
        document.getElementById('monthlyExcTitle').innerText = items.names.length + '개 품목 — 월1회 예외 지점';
        document.getElementById('monthlyExcSub') && (document.getElementById('monthlyExcSub').innerText =
          '선택한 ' + items.names.length + '개 품목의 월예외 지점이 체크한 내용으로 모두 동일하게 저장됩니다.');
        document.getElementById('mexcSelectAll').checked = false;
        renderExcBranches('monthlyExcBranchList', new Set(), 'mexc-branch');
        document.getElementById('monthlyExcModal').style.display = 'flex';
      }}

      function closeMonthlyExc() {{
        document.getElementById('monthlyExcModal').style.display = 'none';
      }}

      async function saveMonthlyExc() {{
        const checked = checkedExcBranches('mexc-branch');
        for (const it of currentMonthlyItems) {{
          const res = await fetch('/master/purchase-order/monthly-exception/save', {{
            method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
            body: JSON.stringify({{ item_name: it.name, branch_codes: checked }})
          }});
          if (!res.ok) {{ alert('저장 실패: ' + it.name); return; }}
        }}
        location.reload();
      }}

      async function openEodExc(itemCode, itemName) {{
        currentEodItems = [{{ code: itemCode, name: itemName }}];
        document.getElementById('eodExcTitle').innerText = itemName + ' — 긴급발주 제외 지점';
        document.getElementById('eodExcSub').innerText = '체크된 지점은 이 상품의 소진 예상이 떠도 긴급발주 알럿이 발송되지 않습니다.';
        document.getElementById('eodexcSelectAll').checked = false;
        const res = await fetch('/master/purchase-order/eod-exception/list?item_code=' + encodeURIComponent(itemCode));
        const data = await res.json();
        renderExcBranches('eodExcBranchList', new Set(data.branches || []), 'eodexc-branch');
        document.getElementById('eodExcModal').style.display = 'flex';
      }}

      function openBulkEodExc() {{
        const items = collectCheckedPmItems();
        const uniq = [];
        const seen = new Set();
        items.codes.forEach(c => {{ if (c.code && !seen.has(c.code)) {{ seen.add(c.code); uniq.push(c); }} }});
        if (!uniq.length) {{ alert('체크된 품목이 없습니다. 표의 체크박스로 품목을 선택하세요.'); return; }}
        currentEodItems = uniq;
        document.getElementById('eodExcTitle').innerText = uniq.length + '개 품목 — 긴급발주 제외 지점';
        document.getElementById('eodExcSub').innerText =
          '선택한 ' + uniq.length + '개 품목의 제외 지점이 체크한 내용으로 모두 동일하게 저장됩니다.';
        document.getElementById('eodexcSelectAll').checked = false;
        renderExcBranches('eodExcBranchList', new Set(), 'eodexc-branch');
        document.getElementById('eodExcModal').style.display = 'flex';
      }}

      function closeEodExc() {{
        document.getElementById('eodExcModal').style.display = 'none';
      }}

      async function saveEodExc() {{
        const checked = checkedExcBranches('eodexc-branch');
        for (const it of currentEodItems) {{
          const res = await fetch('/master/purchase-order/eod-exception/save', {{
            method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
            body: JSON.stringify({{ item_code: it.code, item_name: it.name, branch_codes: checked }})
          }});
          if (!res.ok) {{ alert('저장 실패: ' + (it.name || it.code)); return; }}
        }}
        location.reload();
      }}

      async function addPmItem() {{
        const branch = document.getElementById('pmBranch').value.trim();
        const name = document.getElementById('pmItemName').value.trim();
        const code = document.getElementById('pmItemCode').value.trim();
        const price = parseFloat(document.getElementById('pmPrice').value) || 0;
        const supplier = document.getElementById('pmSupplier').value.trim();
        const tax = document.getElementById('pmTax').value.trim();
        const leadTime = parseInt(document.getElementById('pmLeadTime').value) || 0;
        const moq = parseInt(document.getElementById('pmMoq').value) || 1;
        const consumable = document.getElementById('pmConsumable').checked;
        if (!branch || !name) {{ alert('지점명과 상품명을 입력하세요.'); return; }}
        const res = await fetch('/master/purchase-order/product-master/save', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{
            branch_name: branch, item_name: name, item_code: code, purchase_price: price,
            supplier: supplier, tax_setting: tax, lead_time_days: leadTime, moq: moq, is_consumable: consumable
          }})
        }});
        if (res.ok) {{ location.reload(); }} else {{
          const err = await res.json();
          document.getElementById('pmAddResult').innerText = '오류: ' + (err.detail || '추가 실패');
        }}
      }}

      async function savePmRow(id) {{
        const priceEl = document.querySelector('.pm-price[data-id="' + id + '"]');
        const leadTimeEl = document.querySelector('.pm-leadtime[data-id="' + id + '"]');
        const moqEl = document.querySelector('.pm-moq[data-id="' + id + '"]');
        const minEl = document.querySelector('.pm-minsafe[data-id="' + id + '"]');
        const consumableEl = document.querySelector('.pm-consumable[data-id="' + id + '"]');
        const categoryEl = document.querySelector('.pm-category[data-id="' + id + '"]');
        const ptypeEl = document.querySelector('.pm-ptype[data-id="' + id + '"]');
        const ctypeEl = document.querySelector('.pm-ctype[data-id="' + id + '"]');
        const res = await fetch('/master/purchase-order/product-master/save', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{
            id: id,
            purchase_price: parseFloat(priceEl.value) || 0,
            lead_time_days: parseInt(leadTimeEl.value) || 0,
            moq: parseInt(moqEl.value) || 1,
            min_safety_qty: (minEl && minEl.value.trim() !== '') ? Math.max(0, parseInt(minEl.value) || 0) : null,
            is_consumable: consumableEl.checked,
            category: categoryEl.value.trim(),
            product_type: ptypeEl.value.trim(),
            consumable_type: ctypeEl.value.trim()
          }})
        }});
        if (res.ok) {{ alert('저장되었습니다.'); }} else {{ alert('저장 실패'); }}
      }}

      async function hidePmRow(id, hidden) {{
        const msg = hidden
          ? '이 상품을 목록에서 숨기시겠습니까? (발주 대상에서도 제외됩니다. 나중에 "숨김 상품도 보기"로 다시 볼 수 있습니다)'
          : '이 상품의 숨김을 해제하시겠습니까? (다시 발주 대상에 포함됩니다)';
        if (!confirm(msg)) return;
        const res = await fetch('/master/purchase-order/product-master/hide', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ id: id, hidden: hidden }})
        }});
        if (res.ok) {{ location.reload(); }} else {{ alert('처리 실패'); }}
      }}

      async function uploadPmExcel() {{
        const fileEl = document.getElementById('pmExcelFile');
        if (!fileEl.files.length) {{ alert('파일을 선택하세요.'); return; }}
        const formData = new FormData();
        formData.append('file', fileEl.files[0]);
        document.getElementById('pmUploadResult').innerText = '업로드 중...';
        const res = await fetch('/master/purchase-order/product-master/upload', {{
          method: 'POST', body: formData
        }});
        const data = await res.json();
        if (res.ok) {{
          document.getElementById('pmUploadResult').innerText = '완료: ' + data.inserted + '건 등록/갱신';
          setTimeout(() => location.reload(), 1200);
        }} else {{
          document.getElementById('pmUploadResult').innerText = '오류: ' + (data.detail || '업로드 실패');
        }}
      }}

      function togglePmCheckAll(el) {{
        document.querySelectorAll('.pm-row-check').forEach(cb => cb.checked = el.checked);
        updatePmCheckedCount();
      }}

      function updatePmCheckedCount() {{
        const count = document.querySelectorAll('.pm-row-check:checked').length;
        document.getElementById('pmCheckedCount').innerText = '선택됨: ' + count + '건';
      }}

      document.addEventListener('change', function(e) {{
        if (e.target.classList.contains('pm-row-check')) updatePmCheckedCount();
      }});

      async function saveAllPmRows() {{
        const ids = Array.from(document.querySelectorAll('.pm-price[data-id]')).map(el => el.dataset.id);
        const rows = ids.map(id => {{
          const priceEl = document.querySelector('.pm-price[data-id="' + id + '"]');
          const leadTimeEl = document.querySelector('.pm-leadtime[data-id="' + id + '"]');
          const moqEl = document.querySelector('.pm-moq[data-id="' + id + '"]');
        const minEl = document.querySelector('.pm-minsafe[data-id="' + id + '"]');
          const consumableEl = document.querySelector('.pm-consumable[data-id="' + id + '"]');
          const categoryEl = document.querySelector('.pm-category[data-id="' + id + '"]');
          const ptypeEl = document.querySelector('.pm-ptype[data-id="' + id + '"]');
          const ctypeEl = document.querySelector('.pm-ctype[data-id="' + id + '"]');
          return {{
            id: id,
            purchase_price: parseFloat(priceEl.value) || 0,
            lead_time_days: parseInt(leadTimeEl.value) || 0,
            moq: parseInt(moqEl.value) || 1,
            min_safety_qty: (minEl && minEl.value.trim() !== '') ? Math.max(0, parseInt(minEl.value) || 0) : null,
            is_consumable: consumableEl.checked,
            category: categoryEl.value.trim(),
            product_type: ptypeEl.value.trim(),
            consumable_type: ctypeEl.value.trim()
          }};
        }});
        if (!rows.length) {{ alert('저장할 항목이 없습니다.'); return; }}
        if (!confirm(rows.length + '건을 전체 저장하시겠습니까?')) return;
        const res = await fetch('/master/purchase-order/product-master/bulk-save', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ rows: rows }})
        }});
        const data = await res.json();
        if (res.ok) {{
          alert('저장 완료: ' + data.success + '건' + (data.errors && data.errors.length ? ' / 오류 ' + data.errors.length + '건' : ''));
        }} else {{
          alert('저장 실패: ' + (data.detail || '오류'));
        }}
      }}

      async function applyBulkToChecked() {{
        const ids = Array.from(document.querySelectorAll('.pm-row-check:checked')).map(cb => cb.dataset.id);
        if (!ids.length) {{ alert('체크된 품목이 없습니다.'); return; }}
        const leadTimeVal = document.getElementById('pmBulkLeadTime').value;
        const moqVal = document.getElementById('pmBulkMoq').value;
        const minVal = document.getElementById('pmBulkMin').value;
        if (!leadTimeVal && !moqVal && !minVal) {{ alert('리드타임, MOQ, 최소 안전재고 중 하나 이상을 입력하세요.'); return; }}
        const payload = {{ ids: ids }};
        if (leadTimeVal) payload.lead_time_days = parseInt(leadTimeVal);
        if (moqVal) payload.moq = parseInt(moqVal);
        if (minVal) payload.min_safety_qty = Math.max(0, parseInt(minVal) || 0);
        if (!confirm(ids.length + '건에 값을 일괄 적용하시겠습니까? (즉시 DB에 저장됩니다)')) return;
        const res = await fetch('/master/purchase-order/product-master/bulk-apply', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify(payload)
        }});
        const data = await res.json();
        if (res.ok) {{
          alert('적용 완료: ' + data.success + '건');
          location.reload();
        }} else {{
          alert('적용 실패: ' + (data.detail || '오류'));
        }}
      }}
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "master"))


@app.get("/master/purchase-order/settings-guide", response_class=HTMLResponse)
async def purchase_order_settings_guide(
    session_token: str = Cookie(default=None),
    q: str = "",
):
    """발주 규칙 설명 페이지 — 품번별로 실제 적용되는 예외 변수(소모품/미발주/리드타임/MOQ/월예외 등)를 시각화."""
    from html import escape as _esc
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "product-settings"):
        return RedirectResponse(url="/master", status_code=303)

    conn = get_conn()
    try:
        pm_rows = conn.execute("""
            SELECT item_code,
                   MAX(item_name) AS item_name,
                   MAX(CASE WHEN is_consumable THEN 1 ELSE 0 END) AS is_consumable,
                   MAX(CASE WHEN order_excluded THEN 1 ELSE 0 END) AS order_excluded,
                   MIN(NULLIF(lead_time_days, 0)) AS lead_time_days,
                   MAX(COALESCE(NULLIF(moq, 0), 1)) AS moq,
                   MAX(min_safety_qty) AS min_safety_qty,
                   COUNT(*) AS branch_rows
            FROM product_master
            WHERE item_code IS NOT NULL AND item_code <> ''
            GROUP BY item_code
            ORDER BY item_code
        """).fetchall()
        monthly_exc_rows = conn.execute(
            "SELECT item_code, item_name, branch_code FROM purchase_order_monthly_exception"
        ).fetchall()
    finally:
        conn.close()

    code_to_name = {b["branch_code"]: b["branch_name"] for b in get_branches(branch_type=None)}
    monthly_map: Dict[str, set] = {}
    monthly_name_map: Dict[str, set] = {}
    for r in monthly_exc_rows:
        nm = code_to_name.get(r["branch_code"], r["branch_code"] or "?")
        if r["item_code"]:
            monthly_map.setdefault(r["item_code"], set()).add(nm)
        elif r["item_name"]:
            monthly_name_map.setdefault(r["item_name"], set()).add(nm)

    q = (q or "").strip()
    trs = []
    for r in pm_rows:
        code = r["item_code"] or ""
        name = r["item_name"] or ""
        if q and q not in code and q not in name:
            continue
        lt = r["lead_time_days"]
        lt_val = int(lt) if lt is not None else 0
        mo = monthly_map.get(code, set()) | monthly_name_map.get(name, set())
        ci = set()  # 소모품 지점 예외는 발주 판정에 사용하지 않음 (레거시)

        if r["order_excluded"]:
            klass = ("전체 미발주", "#DC2626")
        elif not r["is_consumable"]:
            klass = ("소모품 미체크 — 발주 제외", "#D97706")
        elif lt_val >= 35:
            klass = ("월발주 (리드타임 35일↑)", "#7C3AED")
        elif lt_val <= 0:
            klass = ("리드타임 없음 — 계산 제외", "#64748B")
        else:
            klass = ("주발주", "#065F46")
        if mo:
            klass = (klass[0] + " + 월예외", klass[1])

        def _exc_cells(branches_set):
            if not branches_set:
                return '<span style="color:#999;">-</span>'
            return _esc(", ".join(sorted(branches_set)))

        trs.append(
            "<tr>"
            f"<td style='font-family:monospace;'>{_esc(code)}</td>"
            f"<td>{_esc(name)}</td>"
            f"<td style='text-align:center;'>{r['branch_rows']}</td>"
            f"<td><span style='background:{klass[1]};color:#fff;padding:2px 8px;border-radius:10px;font-size:11px;white-space:nowrap;'>{_esc(klass[0])}</span></td>"
            f"<td style='text-align:center;'>{'예' if r['is_consumable'] else '-'}</td>"
            f"<td style='text-align:center;'>{'예' if r['order_excluded'] else '-'}</td>"
            f"<td style='text-align:center;'>{lt_val if lt_val else '-'}</td>"
            f"<td style='text-align:center;'>{int(r['moq'] or 1)}</td>"
            f"<td style='text-align:center;'>{r['min_safety_qty'] if r['min_safety_qty'] is not None else '<span style=\'color:#999;\'>공통</span>'}</td>"
            f"<td style='font-size:12px;'>{_exc_cells(mo)}</td>"
            f"<td style='font-size:12px;'>{_exc_cells(ci)}</td>"
            "</tr>"
        )

    rows_html = "".join(trs) if trs else (
        "<tr><td colspan='11' style='text-align:center;padding:24px;color:#888;'>"
        "등록된 품번이 없습니다.</td></tr>")

    content = f"""
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;flex-wrap:wrap;">
      <a href="/master/purchase-order/product-settings" style="color:#1E2761;">← 상품 설정</a>
      <h2>📖 발주 설정 설명</h2>
      <span style="font-size:12px;color:#888;">품번 {len(pm_rows)}개 기준 (지점 행 {sum(int(r['branch_rows']) for r in pm_rows)}개 집계)</span>
    </div>

    <div class="card" style="background:#EFF6FF;border:1px solid #93C5FD;">
      <p style="font-size:13px;color:#1E40AF;margin:0 0 8px 0;"><b>발주 판정 순서</b> (발주 미리보기/검수 공통)</p>
      <ol style="font-size:13px;color:#1E3A8A;margin:0;padding-left:20px;line-height:1.8;">
        <li><b>전체 미발주</b>(order_excluded=예) → 항상 제외</li>
        <li><b>현재고 ≥ 안전재고</b> → 제외 (재고 충분)</li>
        <li><b>소모품 체크</b> → 체크된 품목만 발주 대상. 미체크 품목은 발주 제외 (모든 지점 공통)</li>
        <li><b>미입고 발주(접수/승인)</b> 존재 → 제외 + 별도 보고</li>
        <li>통과 시 <b>주/월 분류</b>: 리드타임 ≥35일 또는 월예외 등록 → 월발주, 나머지 주발주</li>
        <li>최종수량 = 안전재고를 <b>MOQ 배수</b>로 올림</li>
      </ol>
    </div>

    <div class="card" style="background:#FFFBEB;border:1px solid #FCD34D;">
      <p style="font-size:13px;color:#92400E;margin:0;"><b>예외 변수 컨트롤 위치</b><br>
      · 소모품 / 리드타임 / MOQ / 최소 안전재고 / 전체 미발주(숨기기) →
        <a href="/master/purchase-order/product-settings" style="color:#1E40AF;">상품 설정</a> 페이지 (품번 단위 일괄 적용 권장)<br>
      · 월 1회 예외(지점×상품) → 상품 설정 표의 '지방점 주발주 제외' 열 '설정' 버튼<br>
      · <b>소모품 체크된 품목만 발주 대상</b>입니다. 미체크 품목은 모든 지점에서 발주 제외됩니다.</p>
    </div>

    <div class="card">
      <form method="get" action="/master/purchase-order/settings-guide" style="display:flex;gap:8px;margin-bottom:12px;">
        <input name="q" value="{_esc(q)}" placeholder="품번/상품명 검색" style="flex:1;min-width:200px;">
        <button class="btn" type="submit">검색</button>
        <a href="/master/purchase-order/settings-guide" style="padding:10px 14px;background:#eee;border-radius:8px;font-size:13px;text-decoration:none;color:#555;">초기화</a>
      </form>
      <table data-colkey="guide-main" data-colw data-colver="2026-11-20" style="table-layout:fixed;min-width:1250px;"><colgroup><col style="width:110px"><col style="width:200px"><col style="width:80px"><col style="width:160px"><col style="width:70px"><col style="width:80px"><col style="width:70px"><col style="width:70px"><col style="width:100px"><col style="width:150px"><col style="width:150px"></colgroup>
        <thead><tr>
          <th>품번</th><th>상품명</th><th>지점행</th><th>적용 분류</th>
          <th>소모품</th><th>전체미발주</th><th>리드타임</th><th>MOQ</th><th>최소안전재고</th>
          <th>월예외 지점</th><th>소모품 지점 예외(미사용)</th>
        </tr></thead>
        <tbody>{rows_html}</tbody>
      </table>
    </div>
    """
    return HTMLResponse(content=render_page(content, user, "master"))


# ============================================================
# 미등록 상품 감지 / 등록 (상품 설정 페이지)
# ============================================================

PO_MASTER_DEFAULT_BRANCH = "본사"

PO_UNREG_TEMPLATE = """
<style>
.unreg-f { margin-bottom:10px; }
.unreg-f label { display:block; font-size:12px; color:#555; margin-bottom:4px; }
.unreg-f input, .unreg-f select { width:100%; box-sizing:border-box; }
.unreg-f input[readonly] { background:#F3F4F6; color:#555; }
.unreg-req { color:#DC2626; }
</style>
<div id="unregBanner" style="background:#FEF3C7;border:1px solid #F59E0B;border-radius:10px;padding:14px 16px;margin-bottom:14px;display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
  <div style="font-size:14px;color:#92400E;">⚠️ <b>상품 설정에 미등록 상품이 __COUNT__개 있습니다.</b> 등록해주세요.</div>
  <button type="button" class="btn" style="background:#F59E0B;" onclick="unregOpen()">등록하기</button>
</div>

<div id="unregModal" style="display:none;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);z-index:1000;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:12px;padding:22px;max-width:480px;width:92%;max-height:88vh;overflow-y:auto;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;">
      <h3 style="margin:0;">미등록 상품 등록</h3>
      <span id="unregProgress" style="font-size:12px;color:#888;"></span>
    </div>
    <p style="font-size:12px;color:#888;margin:0 0 12px 0;">품번·상품명은 크론 데이터 값입니다. <span class="unreg-req">*</span> 항목은 필수입니다. (등록 지점: 본사)</p>

    <div class="unreg-f"><label>품번</label><input type="text" id="unregCode" readonly></div>
    <div class="unreg-f"><label>상품명</label><input type="text" id="unregName" readonly></div>
    <div class="unreg-f"><label>구매금액 <span class="unreg-req">*</span></label><input type="number" id="unregPrice" min="0" step="any"></div>
    <div class="unreg-f"><label>거래처 <span class="unreg-req">*</span></label><input type="text" id="unregSupplier"></div>
    <div class="unreg-f"><label>과세설정 <span class="unreg-req">*</span></label>
      <select id="unregTax"><option value="">선택</option><option value="과세">과세</option><option value="면세">면세</option></select></div>
    <div class="unreg-f"><label>리드타임(일) <span class="unreg-req">*</span></label><input type="number" id="unregLead" min="0" step="1"></div>
    <div class="unreg-f"><label>MOQ <span class="unreg-req">*</span></label><input type="number" id="unregMoq" min="1" step="1"></div>
    <div class="unreg-f"><label>소모품 여부 <span class="unreg-req">*</span></label>
      <select id="unregConsumable"><option value="">선택</option><option value="Y">예 (소모품)</option><option value="N">아니오</option></select></div>
    <div class="unreg-f"><label>품류 (선택)</label><input type="text" id="unregCategory"></div>
    <div class="unreg-f"><label>종류 (선택)</label><input type="text" id="unregPtype"></div>
    <div class="unreg-f"><label>소모품종류 (선택)</label><input type="text" id="unregCtype"></div>

    <div id="unregHint" style="font-size:12px;color:#1E40AF;margin-bottom:6px;"></div>
    <div id="unregError" style="color:#DC2626;font-size:13px;margin-bottom:8px;"></div>
    <div style="display:flex;gap:8px;">
      <button type="button" class="btn" style="flex:1;background:#eee;color:#333;" onclick="unregClose()">닫기</button>
      <button type="button" class="btn" style="flex:1;background:#64748B;" onclick="unregSkip()">건너뛰기</button>
      <button type="button" class="btn" style="flex:2;" id="unregSaveBtn" onclick="unregSave()">저장 후 다음</button>
    </div>
  </div>
</div>

<script>
var UNREG_ITEMS = __DATA__;
var unregIdx = 0;

function unregEl(id) { return document.getElementById(id); }

function unregOpen() {
  unregIdx = 0;
  unregLoad();
  unregEl('unregModal').style.display = 'flex';
}

function unregClose() {
  unregEl('unregModal').style.display = 'none';
}

function unregLoad() {
  var it = UNREG_ITEMS[unregIdx];
  var hasPrice = !(it.last_price === '' || it.last_price === null || it.last_price === undefined);
  unregEl('unregProgress').innerText = (unregIdx + 1) + ' / ' + UNREG_ITEMS.length;
  unregEl('unregCode').value = it.item_code;
  unregEl('unregName').value = it.item_name;
  unregEl('unregSupplier').value = it.last_vendor || '';
  unregEl('unregPrice').value = hasPrice ? it.last_price : '';
  unregEl('unregTax').value = '';
  unregEl('unregLead').value = '';
  unregEl('unregMoq').value = '';
  unregEl('unregConsumable').value = '';
  unregEl('unregCategory').value = '';
  unregEl('unregPtype').value = '';
  unregEl('unregCtype').value = '';
  unregEl('unregError').innerText = '';
  unregEl('unregHint').innerText = (it.last_vendor || hasPrice) ? '구매내역 최근값(거래처/구매금액)을 미리 채웠습니다. 확인 후 수정하세요.' : '';
  unregEl('unregSaveBtn').disabled = false;
}

function unregNext() {
  unregIdx++;
  if (unregIdx >= UNREG_ITEMS.length) {
    location.reload();
    return;
  }
  unregLoad();
}

function unregSkip() {
  unregNext();
}

async function unregSave() {
  var err = unregEl('unregError');
  err.innerText = '';
  var price = unregEl('unregPrice').value.trim();
  var supplier = unregEl('unregSupplier').value.trim();
  var tax = unregEl('unregTax').value;
  var lead = unregEl('unregLead').value.trim();
  var moq = unregEl('unregMoq').value.trim();
  var cons = unregEl('unregConsumable').value;

  if (price === '' || isNaN(Number(price)) || Number(price) < 0) { err.innerText = '구매금액을 입력하세요. (0 이상 숫자)'; return; }
  if (!supplier) { err.innerText = '거래처를 입력하세요.'; return; }
  if (tax !== '과세' && tax !== '면세') { err.innerText = '과세설정을 선택하세요.'; return; }
  if (!/^[0-9]+$/.test(lead)) { err.innerText = '리드타임(일)을 입력하세요. (0 이상 정수)'; return; }
  if (!/^[0-9]+$/.test(moq) || parseInt(moq, 10) < 1) { err.innerText = 'MOQ를 입력하세요. (1 이상 정수)'; return; }
  if (cons !== 'Y' && cons !== 'N') { err.innerText = '소모품 여부를 선택하세요.'; return; }

  var payload = {
    item_code: unregEl('unregCode').value,
    item_name: unregEl('unregName').value,
    purchase_price: Number(price),
    supplier: supplier,
    tax_setting: tax,
    lead_time_days: parseInt(lead, 10),
    moq: parseInt(moq, 10),
    is_consumable: (cons === 'Y'),
    category: unregEl('unregCategory').value.trim(),
    product_type: unregEl('unregPtype').value.trim(),
    consumable_type: unregEl('unregCtype').value.trim()
  };

  var btn = unregEl('unregSaveBtn');
  btn.disabled = true;
  try {
    var res = await fetch('/master/purchase-order/product-master/register-new', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    var data = {};
    try { data = await res.json(); } catch (e) {}
    if (!res.ok) {
      err.innerText = data.detail || '저장에 실패했습니다.';
      btn.disabled = false;
      return;
    }
    unregNext();
  } catch (e) {
    err.innerText = '저장 중 오류가 발생했습니다.';
    btn.disabled = false;
  }
}
</script>
"""


def _po_get_unregistered_products() -> list:
    """크론 데이터(재고·구매내역)와 안전재고에 있는 품번 중 product_master에 없는 품번 목록.
    상품명은 크론 최신 데이터(raw_inventory) 우선. 품번이 없어 자동 생성된 '미지정' 코드는 제외."""
    conn = get_conn()
    rows = conn.execute("""
        WITH cand AS (
            SELECT item_code, item_name, 1 AS prio, 'raw_inventory' AS src,
                   CAST(uploaded_at AS text) AS ts FROM raw_inventory
            UNION ALL
            SELECT item_code, item_name, 2 AS prio, 'purchase_records' AS src,
                   CAST(purchase_datetime AS text) AS ts FROM purchase_records
            UNION ALL
            SELECT item_code, item_name, 3 AS prio, 'safety_stock' AS src,
                   CAST(updated_at AS text) AS ts FROM safety_stock
        )
        SELECT DISTINCT ON (c.item_code) c.item_code, c.item_name, c.src
        FROM cand c
        WHERE COALESCE(c.item_code, '') <> ''
          AND LEFT(c.item_code, 3) <> '미지정'
          AND NOT EXISTS (SELECT 1 FROM product_master p WHERE p.item_code = c.item_code)
        ORDER BY c.item_code, c.prio, c.ts DESC NULLS LAST
    """).fetchall()

    items = [{"item_code": r["item_code"], "item_name": r["item_name"] or "", "src": r["src"]} for r in rows]
    if not items:
        conn.close()
        return []

    codes = [it["item_code"] for it in items]
    placeholders = ",".join("?" for _ in codes)
    last_rows = conn.execute(
        "SELECT DISTINCT ON (item_code) item_code, vendor, unit_price FROM purchase_records "
        "WHERE item_code IN (" + placeholders + ") ORDER BY item_code, purchase_datetime DESC",
        codes
    ).fetchall()
    conn.close()

    last_map = {r["item_code"]: r for r in last_rows}
    for it in items:
        lr = last_map.get(it["item_code"])
        it["last_vendor"] = (lr["vendor"] or "").strip() if lr else ""
        price = ""
        if lr and lr["unit_price"] is not None:
            f = float(lr["unit_price"])
            price = int(f) if f == int(f) else f
        it["last_price"] = price
    return items


def _po_unregistered_banner_html() -> str:
    """상품 설정 페이지 상단: 미등록 상품 알럿 + 등록 창. 조회 실패해도 페이지 자체는 정상 표시."""
    import json
    try:
        items = _po_get_unregistered_products()
    except Exception as e:
        print("[unregistered] 조회 실패: " + str(e)[:200])
        return ""
    if not items:
        return ""
    data_json = (json.dumps(items, ensure_ascii=False)
                 .replace("<", "\\u003c")
                 .replace("\u2028", "\\u2028")
                 .replace("\u2029", "\\u2029"))
    return PO_UNREG_TEMPLATE.replace("__COUNT__", str(len(items))).replace("__DATA__", data_json)


@app.post("/master/purchase-order/product-master/register-new")
async def purchase_order_product_master_register_new(request: Request, session_token: str = Cookie(default=None)):
    """미등록 상품 신규 등록 (필수값 서버 검증, 지점은 '본사' 고정, 이미 있는 품번은 거부)"""
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})
    if not has_menu_permission(user["login_id"], "product-settings"):
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    item_code = str(data.get("item_code") or "").strip()
    item_name = str(data.get("item_name") or "").strip()
    supplier = str(data.get("supplier") or "").strip()
    tax_setting = str(data.get("tax_setting") or "").strip()
    is_consumable = data.get("is_consumable")

    if not item_code or not item_name:
        return JSONResponse(status_code=400, content={"detail": "품번/상품명이 없습니다."})
    if not supplier:
        return JSONResponse(status_code=400, content={"detail": "거래처를 입력하세요."})
    if tax_setting not in ("과세", "면세"):
        return JSONResponse(status_code=400, content={"detail": "과세설정을 선택하세요."})
    if not isinstance(is_consumable, bool):
        return JSONResponse(status_code=400, content={"detail": "소모품 여부를 선택하세요."})
    try:
        purchase_price = float(data.get("purchase_price"))
        lead_time_days = int(data.get("lead_time_days"))
        moq = int(data.get("moq"))
    except (TypeError, ValueError):
        return JSONResponse(status_code=400, content={"detail": "구매금액/리드타임/MOQ는 숫자로 입력하세요."})
    if purchase_price < 0 or lead_time_days < 0 or moq < 1:
        return JSONResponse(status_code=400, content={"detail": "구매금액·리드타임은 0 이상, MOQ는 1 이상이어야 합니다."})

    category = str(data.get("category") or "").strip() or None
    product_type = str(data.get("product_type") or "").strip() or None
    consumable_type = str(data.get("consumable_type") or "").strip() or None

    now = datetime.now().isoformat()
    conn = get_conn()
    exists = conn.execute("SELECT 1 AS x FROM product_master WHERE item_code=? LIMIT 1", (item_code,)).fetchone()
    if exists:
        conn.close()
        return JSONResponse(status_code=409, content={"detail": "이미 상품 마스터에 등록된 품번입니다."})
    conn.execute("""
        INSERT INTO product_master
            (branch_name, item_name, item_code, purchase_price, supplier, tax_setting,
             lead_time_days, moq, is_consumable, category, product_type, consumable_type, updated_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    """, (PO_MASTER_DEFAULT_BRANCH, item_name, item_code, purchase_price, supplier, tax_setting,
          lead_time_days, moq, is_consumable, category, product_type, consumable_type, now))
    conn.commit()
    conn.close()
    return {"success": True}

def _parse_min_safety_qty(v):
    """상품별 최소 안전재고 입력값 변환. 비어 있으면 None(= 공통 최소값 사용), 아니면 0 이상 정수. 잘못된 값이면 ValueError."""
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip()
        if v == "":
            return None
    n = int(float(v))
    if n < 0:
        raise ValueError("min_safety_qty must be >= 0")
    return n


def _set_min_safety_qty(conn, row_ids, value, now):
    """선택한 행과 품번이 같은 모든 지점 행에 상품별 최소 안전재고를 함께 저장한다.
    (비교 계산이 품번 단위로 지점 간 MAX를 쓰기 때문에, 일부 행만 바꾸면 값을 낮출 수 없다.)
    품번이 없는 행은 그 행만 바꾼다. value가 None이면 값을 비운다."""
    ids = [int(i) for i in row_ids]
    if not ids:
        return
    ph = ",".join("?" for _ in ids)
    found = conn.execute(
        f"SELECT id, item_code FROM product_master WHERE id IN ({ph})", ids
    ).fetchall()
    codes = sorted({r["item_code"] for r in found if (r["item_code"] or "").strip()})
    no_code_ids = [int(r["id"]) for r in found if not (r["item_code"] or "").strip()]
    if codes:
        cph = ",".join("?" for _ in codes)
        conn.execute(
            f"UPDATE product_master SET min_safety_qty=?, updated_at=? WHERE item_code IN ({cph})",
            [value, now] + codes
        )
    if no_code_ids:
        nph = ",".join("?" for _ in no_code_ids)
        conn.execute(
            f"UPDATE product_master SET min_safety_qty=?, updated_at=? WHERE id IN ({nph})",
            [value, now] + no_code_ids
        )


@app.post("/master/purchase-order/product-master/save")
async def purchase_order_product_master_save(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    row_id = data.get("id")
    branch_name = (data.get("branch_name") or "").strip()
    item_name = (data.get("item_name") or "").strip()
    item_code = (data.get("item_code") or "").strip()
    purchase_price = data.get("purchase_price", 0)
    supplier = (data.get("supplier") or "").strip()
    tax_setting = (data.get("tax_setting") or "").strip()
    lead_time_days = data.get("lead_time_days", 0)
    moq = data.get("moq", 1)
    is_consumable = bool(data.get("is_consumable", False))
    category = (data.get("category") or "").strip() or None
    product_type = (data.get("product_type") or "").strip() or None
    consumable_type = (data.get("consumable_type") or "").strip() or None

    # 최소 안전재고는 요청에 키가 있을 때만 반영한다(키가 없으면 기존 값 유지)
    min_provided = "min_safety_qty" in data
    min_safety_qty = None
    if min_provided:
        try:
            min_safety_qty = _parse_min_safety_qty(data.get("min_safety_qty"))
        except (ValueError, TypeError):
            return JSONResponse(status_code=400, content={"detail": "최소 안전재고는 0 이상의 정수로 입력하세요."})

    now = datetime.now().isoformat()
    conn = get_conn()
    if row_id:
        conn.execute(
            """UPDATE product_master
               SET purchase_price=?, lead_time_days=?, moq=?, is_consumable=?,
                   category=?, product_type=?, consumable_type=?, updated_at=?
               WHERE id=?""",
            (purchase_price, lead_time_days, moq, is_consumable,
             category, product_type, consumable_type, now, row_id)
        )
        if min_provided:
            _set_min_safety_qty(conn, [row_id], min_safety_qty, now)
    else:
        if not branch_name or not item_name:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "지점명과 상품명을 입력하세요."})
        conn.execute("""
            INSERT INTO product_master
                (branch_name, item_name, item_code, purchase_price, supplier,
                 tax_setting, lead_time_days, moq, is_consumable,
                 category, product_type, consumable_type, updated_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT (branch_name, item_code) DO UPDATE SET
                item_name=excluded.item_name, purchase_price=excluded.purchase_price,
                supplier=excluded.supplier, tax_setting=excluded.tax_setting,
                lead_time_days=excluded.lead_time_days, moq=excluded.moq,
                is_consumable=excluded.is_consumable,
                category=excluded.category, product_type=excluded.product_type,
                consumable_type=excluded.consumable_type, updated_at=excluded.updated_at
        """, (branch_name, item_name, item_code, purchase_price, supplier,
              tax_setting, lead_time_days, moq, is_consumable,
              category, product_type, consumable_type, now))
        if min_provided and item_code:
            conn.execute(
                "UPDATE product_master SET min_safety_qty=?, updated_at=? WHERE item_code=?",
                (min_safety_qty, now, item_code)
            )
    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok"})

@app.post("/master/purchase-order/product-master/bulk-save")
async def purchase_order_product_master_bulk_save(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    rows = data.get("rows", [])
    if not rows:
        return JSONResponse(status_code=400, content={"detail": "저장할 항목이 없습니다."})

    now = datetime.now().isoformat()
    conn = get_conn()

    # 최소 안전재고는 저장 전 DB 값과 비교해 '바뀐 행'만 반영한다
    # (화면에 같은 품번의 행이 여러 개일 때 바뀌지 않은 행이 새 값을 덮어쓰지 않도록)
    snap = {}
    try:
        id_list = [int(r.get("id")) for r in rows if r.get("id")]
    except (ValueError, TypeError):
        conn.close()
        return JSONResponse(status_code=400, content={"detail": "잘못된 id가 포함되어 있습니다."})
    if id_list:
        sph = ",".join("?" for _ in id_list)
        for s in conn.execute(
            f"SELECT id, min_safety_qty FROM product_master WHERE id IN ({sph})", id_list
        ).fetchall():
            snap[int(s["id"])] = s["min_safety_qty"]

    updated = 0
    errors = []
    min_changes = {}
    for r in rows:
        row_id = r.get("id")
        if not row_id:
            continue
        try:
            conn.execute(
                """UPDATE product_master
                   SET purchase_price=?, lead_time_days=?, moq=?, is_consumable=?,
                       category=?, product_type=?, consumable_type=?, updated_at=?
                   WHERE id=?""",
                (
                    r.get("purchase_price", 0), r.get("lead_time_days", 0), r.get("moq", 1),
                    bool(r.get("is_consumable", False)),
                    (r.get("category") or "").strip() or None,
                    (r.get("product_type") or "").strip() or None,
                    (r.get("consumable_type") or "").strip() or None,
                    now, row_id
                )
            )
            updated += 1
        except Exception as e:
            errors.append(f"id={row_id}: {str(e)}")
            continue
        if "min_safety_qty" in r:
            try:
                new_min = _parse_min_safety_qty(r.get("min_safety_qty"))
            except (ValueError, TypeError):
                errors.append(f"id={row_id}: 최소 안전재고는 0 이상의 정수여야 합니다")
                continue
            if new_min != snap.get(int(row_id)):
                min_changes[int(row_id)] = new_min

    for rid, val in min_changes.items():
        try:
            _set_min_safety_qty(conn, [rid], val, now)
        except Exception as e:
            errors.append(f"id={rid} 최소 안전재고: {str(e)}")

    conn.commit()
    conn.close()
    return {"success": updated, "errors": errors}


@app.post("/master/purchase-order/product-master/bulk-apply")
async def purchase_order_product_master_bulk_apply(request: Request, session_token: str = Cookie(default=None)):
    """체크된 품목들에 리드타임/MOQ/최소 안전재고 값을 일괄 적용"""
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    ids = data.get("ids", [])
    lead_time_days = data.get("lead_time_days")
    moq = data.get("moq")
    min_provided = data.get("min_safety_qty") is not None
    min_safety_qty = None
    if min_provided:
        try:
            min_safety_qty = _parse_min_safety_qty(data.get("min_safety_qty"))
        except (ValueError, TypeError):
            return JSONResponse(status_code=400, content={"detail": "최소 안전재고는 0 이상의 정수로 입력하세요."})
        if min_safety_qty is None:
            min_provided = False

    if not ids:
        return JSONResponse(status_code=400, content={"detail": "선택된 품목이 없습니다."})
    if lead_time_days is None and moq is None and not min_provided:
        return JSONResponse(status_code=400, content={"detail": "변경할 값을 입력하세요."})
    try:
        id_list = [int(i) for i in ids]
    except (ValueError, TypeError):
        return JSONResponse(status_code=400, content={"detail": "잘못된 id가 포함되어 있습니다."})

    now = datetime.now().isoformat()
    conn = get_conn()

    sets = []
    vals = []
    if lead_time_days is not None:
        sets.append("lead_time_days=?")
        vals.append(lead_time_days)
    if moq is not None:
        sets.append("moq=?")
        vals.append(moq)
    if sets:
        placeholders = ",".join("?" for _ in id_list)
        conn.execute(
            f"UPDATE product_master SET {', '.join(sets)}, updated_at=? WHERE id IN ({placeholders})",
            vals + [now] + id_list
        )
    if min_provided:
        _set_min_safety_qty(conn, id_list, min_safety_qty, now)

    conn.commit()
    conn.close()
    return {"success": len(ids)}

