def _sync_item_names_by_code() -> dict:
    """품번(item_code) 기준으로 items / inventory / safety_stock / product_master 의
    item_name 을 크론 원본(raw_inventory)의 최신 이름으로 맞춘다.
    - raw_inventory 에 없는 품번(예: 서비스 상품 SVSTSC-000001)은 건드리지 않는다.
    - 이름이 실제로 다른 행만 UPDATE 한다.
    - 반환: {테이블명: 변경 건수}
    """
    latest_sql = """
        SELECT DISTINCT ON (item_code) item_code, item_name
        FROM raw_inventory
        WHERE item_code IS NOT NULL AND item_code <> ''
          AND item_name IS NOT NULL AND item_name <> ''
        ORDER BY item_code, uploaded_at DESC NULLS LAST
    """
    result = {}
    conn = get_conn()
    try:
        for tbl in ("items", "inventory", "safety_stock", "product_master"):
            cnt_row = conn.execute(
                f"""SELECT COUNT(*) AS c FROM {tbl} t
                    JOIN ({latest_sql}) l ON l.item_code = t.item_code
                    WHERE t.item_name IS DISTINCT FROM l.item_name"""
            ).fetchone()
            cnt = int(cnt_row["c"]) if cnt_row else 0
            if cnt > 0:
                conn.execute(
                    f"""UPDATE {tbl} SET item_name = l.item_name
                        FROM ({latest_sql}) l
                        WHERE {tbl}.item_code = l.item_code
                          AND {tbl}.item_name IS DISTINCT FROM l.item_name"""
                )
            result[tbl] = cnt
        conn.commit()
        if any(result.values()):
            print(f"[item-name-sync] 품번 기준 이름 갱신: {result}")
    except Exception as e:
        print(f"[item-name-sync] 실패: {e}")
    finally:
        conn.close()
    return result

# ── 고아 재고 자동 정리 (raw_inventory에 없는 inventory 행) ──
# 모드: INVENTORY_ORPHAN_MODE = dry(기본, 기록만) | live(실삭제) | off
# 유예: INVENTORY_ORPHAN_GRACE_DAYS일 이내 갱신된 행은 보호 (QR 선등록 → 유비 후등록 플로우)
# 안전: 후보가 대상 지점 전체 재고의 INVENTORY_ORPHAN_MAX_RATIO 초과 시 삭제 중단 + 알림
INVENTORY_ORPHAN_MODE = os.getenv("INVENTORY_ORPHAN_MODE", "dry")
INVENTORY_ORPHAN_GRACE_DAYS = int(os.getenv("INVENTORY_ORPHAN_GRACE_DAYS", "7"))
INVENTORY_ORPHAN_MAX_RATIO = float(os.getenv("INVENTORY_ORPHAN_MAX_RATIO", "0.2"))
INVENTORY_ORPHAN_LOG_LIMIT = 5000


def _cleanup_orphan_inventory(branch_codes, source_label: str) -> dict:
    """이번에 raw_inventory가 갱신된 지점들에 한해, raw에 없는 inventory 행을 정리.
    반환 dict는 호출부 결과에 병합용."""
    from datetime import timedelta as _td
    mode = (os.getenv("INVENTORY_ORPHAN_MODE", INVENTORY_ORPHAN_MODE) or "dry").strip().lower()
    if mode in ("off", "disabled", "false", "0"):
        return {"mode": mode, "skipped": "disabled"}
    branches = [str(b) for b in (branch_codes or []) if b]
    if not branches:
        return {"mode": mode, "skipped": "no_branches"}

    conn = get_conn()
    try:
        ph = ",".join("?" for _ in branches)
        total_row = conn.execute(
            f"SELECT COUNT(*) AS c FROM inventory WHERE branch_code IN ({ph})", branches
        ).fetchone()
        total = int(total_row["c"] or 0)
        inv_rows = conn.execute(
            f"SELECT id, branch_code, item_code, item_name, quantity, last_updated "
            f"FROM inventory WHERE branch_code IN ({ph})", branches
        ).fetchall()
        raw_keys = set()
        for r in conn.execute("SELECT branch_code, item_code FROM raw_inventory").fetchall():
            raw_keys.add((str(r["branch_code"]), str(r["item_code"])))

        cutoff = datetime.now() - _td(days=INVENTORY_ORPHAN_GRACE_DAYS)
        now_iso = datetime.now().isoformat()
        candidates = []
        for r in inv_rows:
            if (str(r["branch_code"]), str(r["item_code"])) in raw_keys:
                continue
            lu = r["last_updated"]
            if lu:
                try:
                    lu_dt = datetime.fromisoformat(str(lu).replace("Z", "+00:00"))
                    if lu_dt.tzinfo is not None:
                        lu_dt = lu_dt.astimezone().replace(tzinfo=None)
                    if lu_dt > cutoff:
                        continue  # 유예 기간 내 갱신 → 보호
                except Exception:
                    continue  # 파싱 불가 → 보호 (삭제하지 않음)
            candidates.append(r)

        result = {"mode": mode, "total": total, "candidates": len(candidates),
                  "deleted": 0, "logged": 0}
        if not candidates:
            return result

        ratio = len(candidates) / total if total else 1.0
        exceed = total > 0 and ratio > INVENTORY_ORPHAN_MAX_RATIO

        def _log_row(r, action, detail):
            conn.execute(
                "INSERT INTO inventory_orphan_cleanup_log "
                "(run_at, source, branch_code, item_code, item_name, quantity, last_updated, action, detail) "
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (now_iso, source_label, str(r["branch_code"]), str(r["item_code"]),
                 str(r["item_name"] or ""), r["quantity"], str(r["last_updated"] or ""),
                 action, detail)
            )

        if mode == "live" and exceed:
            detail = (f"삭제 중단: 후보 {len(candidates)}건이 대상 지점 재고 {total}건의 "
                      f"{ratio:.0%}로 한도 {INVENTORY_ORPHAN_MAX_RATIO:.0%} 초과")
            for r in candidates[:INVENTORY_ORPHAN_LOG_LIMIT]:
                _log_row(r, "skipped_ratio", detail)
            conn.commit()
            try:
                report_cron_failure("inventory-orphan-cleanup", detail)
            except Exception:
                pass
            result["skipped"] = "ratio_guard"
            result["logged"] = min(len(candidates), INVENTORY_ORPHAN_LOG_LIMIT)
            return result

        action = "deleted" if mode == "live" else "dry_run"
        detail = ("유비플러스(raw_inventory) 미등록 품목" if mode == "live"
                  else "dry-run: 삭제 예정 대상 (실삭제하려면 INVENTORY_ORPHAN_MODE=live)")
        for r in candidates[:INVENTORY_ORPHAN_LOG_LIMIT]:
            _log_row(r, action, detail)
        result["logged"] = min(len(candidates), INVENTORY_ORPHAN_LOG_LIMIT)

        if mode == "live":
            ids = [int(r["id"]) for r in candidates]
            for i in range(0, len(ids), 500):
                chunk = ids[i:i + 500]
                conn.execute(
                    f"DELETE FROM inventory WHERE id IN ({','.join('?' for _ in chunk)})", chunk
                )
            result["deleted"] = len(ids)

        conn.commit()
        if mode == "live" and len(candidates) > INVENTORY_ORPHAN_LOG_LIMIT:
            result["log_truncated"] = True
        return result
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        err = "고아 재고 정리 실패: " + str(e)[:300]
        try:
            report_cron_failure("inventory-orphan-cleanup", err)
        except Exception:
            pass
        return {"mode": mode, "error": err}
    finally:
        conn.close()


async def _fetch_and_process_s3_csv():
    """S3의 유비플러스 재고현황 CSV를 다운로드하여 재고수불부 형식과 동일하게 파싱/반영"""
    import httpx
    import csv
    import io as io_module

    try:
        CSV_URL = _cron_source_url("sync-raw-inventory")

        async with httpx.AsyncClient(timeout=30.0) as client:
            resp = await client.get(CSV_URL)
            resp.raise_for_status()
            raw_bytes = resp.content

        # 인코딩 자동 판별 (한글 CSV는 보통 cp949 또는 utf-8-sig)
        try:
            text = raw_bytes.decode('utf-8-sig')
        except UnicodeDecodeError:
            text = raw_bytes.decode('cp949')

        reader = csv.reader(io_module.StringIO(text))
        rows_raw = list(reader)

        header_row_idx = None
        col_map = {}
        KEYWORDS = {
            "branch": ["지점"],
            "item_name": ["상품명"],
            "item_code": ["품번"],
            "qty": ["기말수량"],
            "h": ["증가수량"],
            "q": ["재고조정"],
        }
        for row_idx in range(min(5, len(rows_raw))):
            row_vals = rows_raw[row_idx]
            found = {}
            for col_idx, cell_val in enumerate(row_vals):
                if not cell_val:
                    continue
                text_val = str(cell_val).strip()
                for key, keywords in KEYWORDS.items():
                    if key in found:
                        continue
                    if any(kw in text_val for kw in keywords):
                        found[key] = col_idx
            if all(k in found for k in ("branch", "item_name", "item_code")):
                header_row_idx = row_idx
                col_map = found
                break

        if header_row_idx is None:
            return {"success": 0, "skipped": 0, "errors": ["CSV 헤더를 찾을 수 없습니다."]}

        branch_map = {}
        branches = get_branches()
        for b in branches:
            branch_map[b["branch_name"]] = b["branch_code"]
            branch_map[b["branch_name"].replace(" ", "")] = b["branch_code"]
            branch_map[b["branch_code"]] = b["branch_code"]

        now = datetime.now().isoformat()
        success, skipped, errors = 0, 0, []
        hq_adjustments = []
        debug_hq_log = []
        data_start_row = header_row_idx + 1

        branches_in_file = set()
        parsed_rows = []
        for idx in range(data_start_row, len(rows_raw)):
            row = rows_raw[idx]
            branch_col = col_map.get("branch")
            if branch_col is None or branch_col >= len(row) or not row[branch_col]:
                continue
            branch_name = str(row[branch_col]).strip()
            branch_code = (branch_map.get(branch_name)
                           or branch_map.get(branch_name.replace(" ", ""))
                           or branch_name)
            branches_in_file.add(branch_code)
            parsed_rows.append((idx, row, branch_code, branch_name))

        if not branches_in_file:
            return {"success": 0, "skipped": 0, "errors": ["CSV에서 유효한 지점 데이터를 찾지 못했습니다."]}

        conn = get_conn()
        for bc in branches_in_file:
            conn.execute("DELETE FROM raw_inventory WHERE branch_code=?", (bc,))
        old_hq_rows = conn.execute("SELECT * FROM hq_bonus_log").fetchall()
        old_hq_map = {f"{r['branch_code']}|{r['item_code']}": r["last_hq_total"] for r in old_hq_rows}
        for bc in branches_in_file:
            conn.execute("DELETE FROM hq_bonus_log WHERE branch_code=?", (bc,))
        conn.commit()

        for idx, row, branch_code, branch_name in parsed_rows:
            try:
                item_name = str(row[col_map["item_name"]]).strip() if col_map["item_name"] < len(row) and row[col_map["item_name"]] else ""
                item_code = str(row[col_map["item_code"]]).strip() if col_map["item_code"] < len(row) and row[col_map["item_code"]] else ""

                if not item_code:
                    import hashlib
                    name_hash = hashlib.md5(item_name.encode('utf-8')).hexdigest()[:8]
                    item_code = f"미지정_{name_hash}"

                qty_n = row[col_map["qty"]] if "qty" in col_map and col_map["qty"] < len(row) else None
                qty_h = row[col_map["h"]] if "h" in col_map and col_map["h"] < len(row) else None
                qty_q = row[col_map["q"]] if "q" in col_map and col_map["q"] < len(row) else None

                raw_quantity = int(float(str(qty_n))) if qty_n not in (None, "") else 0
                add_h = int(float(str(qty_h))) if qty_h not in (None, "") else 0
                add_q = int(float(str(qty_q))) if qty_q not in (None, "") else 0
                hq_total = add_h + add_q

                conn.execute("""
                    INSERT INTO raw_inventory
                      (branch_code, branch_name, item_name, item_code, quantity, source, uploaded_at)
                    VALUES (?, ?, ?, ?, ?, 'auto_s3', ?)
                    ON CONFLICT(branch_code, item_code) DO UPDATE SET
                      quantity=excluded.quantity,
                      item_name=excluded.item_name,
                      branch_name=excluded.branch_name,
                      source=excluded.source,
                      uploaded_at=excluded.uploaded_at
                """, (branch_code, branch_name, item_name, item_code, raw_quantity, now))

                existing_item = conn.execute(
                    "SELECT id FROM items WHERE branch_code=? AND item_code=?",
                    (branch_code, item_code)
                ).fetchone()
                if not existing_item:
                    conn.execute("""
                        INSERT INTO items (branch_code, branch_name, item_name, item_code, created_at)
                        VALUES (?, ?, ?, ?, ?)
                        ON CONFLICT(branch_code, item_code) DO UPDATE SET item_name=excluded.item_name
                    """, (branch_code, branch_name, item_name, item_code, now))
                    conn.execute("""
                        INSERT INTO inventory (branch_code, item_name, item_code, quantity, last_updated)
                        VALUES (?, ?, ?, 0, ?)
                        ON CONFLICT(branch_code, item_code) DO NOTHING
                    """, (branch_code, item_name, item_code, now))

                if item_code.startswith("미지정_") or is_item_consumable(conn, branch_code, item_code):
                    conn.execute("""
                        UPDATE inventory SET quantity=?, last_updated=?
                        WHERE branch_code=? AND item_code=?
                    """, (raw_quantity, now, branch_code, item_code))

                if hq_total != 0:
                    hq_adjustments.append((branch_code, item_name, item_code, hq_total))
                    debug_hq_log.append(f"{item_name}({item_code}): 증가={add_h}, 조정={add_q}, 합계={hq_total}")

                success += 1
            except Exception as e:
                errors.append(f"행 {idx}: {str(e)[:50]}")
                skipped += 1

        conn.commit()
        conn.close()

        for branch_code, item_name, item_code, new_hq_total in hq_adjustments:
            conn2 = get_conn()
            prev_hq_total = old_hq_map.get(f"{branch_code}|{item_code}", 0)
            net_delta = new_hq_total - prev_hq_total
            if net_delta != 0:
                new_qty = adjust_quantity(branch_code, item_code, net_delta, absolute=False)
                conn2.execute(
                    "INSERT INTO adjustment_log (branch_code, item_name, item_code, delta, result_quantity, adjusted_at) VALUES (?, ?, ?, ?, ?, ?)",
                    (branch_code, item_name, item_code, net_delta, new_qty, now)
                )
            conn2.execute("""
                INSERT INTO hq_bonus_log (branch_code, item_code, last_hq_total, updated_at)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(branch_code, item_code) DO UPDATE SET
                  last_hq_total=excluded.last_hq_total, updated_at=excluded.updated_at
            """, (branch_code, item_code, new_hq_total, now))
            conn2.commit()
            conn2.close()

        name_sync = _sync_item_names_by_code()
        orphan_cleanup = None
        if success > 0:
            try:
                orphan_cleanup = _cleanup_orphan_inventory(branches_in_file, "s3_csv")
            except Exception as e:
                orphan_cleanup = {"error": str(e)[:300]}
        return {"success": success, "skipped": skipped, "errors": errors[:10],
                "header_row_used": header_row_idx,
                "hq_debug": debug_hq_log[:20],
                "name_sync": name_sync,
                "orphan_cleanup": orphan_cleanup,
                "synced_at": now}
    except Exception as e:
        err_msg = str(e)[:500]
        report_cron_failure("sync-raw-inventory", err_msg)
        return {"success": 0, "skipped": 0, "errors": [err_msg]}

