                        miss = [r[0] for r in cmp_rows
                                if (r[1] != r[3] or r[2] != r[4]) and not memos.get(r[0], "").strip()]
                        lines_b = ["⚠️ 불일치 항목의 메모를 모두 입력해야 마감 저장할 수 있습니다. (입력한 메모는 저장되었습니다)"]
                        if miss:
                            lines_b.append("메모가 비어 있는 항목: " + ", ".join(miss))
