@app.post("/closing/cash-save")
async def closing_cash_save(request: Request, session_token: str = Cookie(default=None)):
    """현금시재 저장: 실제 시재 + 수기 행(기타 입금/시재 사용)을 지점×일자 단위로 교체 저장.
    마감 저장된 일자는 잠긴다(영수증 사진과 동일 규칙)."""
    import json as _json
    import re

    user = get_session(session_token)
    if not user:
        return RedirectResponse(url="/login", status_code=303)
    is_all = user["role"] == "master" or user.get("branch_type") == "hq"
    if is_all and not has_menu_permission(user["login_id"], "closing"):
        return RedirectResponse(url="/", status_code=303)

    form = await request.form()
    pay_date = str(form.get("date") or "").strip()
    branch_param = str(form.get("branch") or "").strip()
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", pay_date):
        return RedirectResponse(url="/closing", status_code=303)

    actual_raw = str(form.get("cash_actual") or "").replace(",", "").strip()
    actual = None
    if actual_raw:
        try:
            actual = max(0, int(float(actual_raw)))
        except ValueError:
            actual = None

    lines = []
    try:
        raw_lines = _json.loads(str(form.get("cash_lines") or "[]"))
        if isinstance(raw_lines, list):
            for i, l in enumerate(raw_lines[:50]):
                if not isinstance(l, dict):
                    continue
                kind = "deposit" if l.get("kind") == "deposit" else "use"
                try:
                    amt = max(0, int(float(str(l.get("amount") or 0))))
                except (TypeError, ValueError):
                    amt = 0
                cust = str(l.get("customer") or "").strip()[:50]
                note = str(l.get("note") or "").strip()[:100]
                if amt > 0 or cust or note:
                    lines.append((kind, amt, cust, note, i))
    except Exception:
        lines = []

    now_iso = _kst_now().strftime("%Y-%m-%d %H:%M:%S")
    conn = get_conn()
    try:
        resolved = _closing_resolve_branch(conn, user, is_all, branch_param)
        if not resolved:
            return RedirectResponse(url="/closing", status_code=303)
        key, name = resolved
        if _closing_get_save(conn, key, pay_date):
            return RedirectResponse(url=_closing_back_url(pay_date, branch_param, "locked"), status_code=303)

        conn.execute(
            "INSERT INTO closing_cash (branch_key, branch_name, pay_date, actual_cash, updated_by, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?) "
            "ON CONFLICT(branch_key, pay_date) DO UPDATE SET "
            "actual_cash=excluded.actual_cash, branch_name=excluded.branch_name, "
            "updated_by=excluded.updated_by, updated_at=excluded.updated_at",
            (key, name, pay_date, actual, user["login_id"], now_iso)
        )
        conn.execute("DELETE FROM closing_cash_lines WHERE branch_key=? AND pay_date=?", (key, pay_date))
        for kind, amt, cust, note, i in lines:
            conn.execute(
                "INSERT INTO closing_cash_lines (branch_key, pay_date, kind, amount, customer, note, "
                "sort_order, updated_by, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (key, pay_date, kind, amt, cust, note, i, user["login_id"], now_iso)
            )
        conn.commit()
    finally:
        conn.close()
    return RedirectResponse(url=_closing_back_url(pay_date, branch_param, "cash_saved"), status_code=303)


@app.post("/closing/save")
async def closing_save(request: Request, session_token: str = Cookie(default=None)):
    """마감 저장: 영수증 값 입력 필수, 불일치 행은 메모 필수. 저장하면 그 시점의 값이 고정된다."""
    import re

    user = get_session(session_token)
    if not user:
        return RedirectResponse(url="/login", status_code=303)
    is_all = user["role"] == "master" or user.get("branch_type") == "hq"
    if is_all and not has_menu_permission(user["login_id"], "closing"):
        return RedirectResponse(url="/", status_code=303)

    form = await request.form()
    pay_date = str(form.get("date") or "").strip()
    branch_param = str(form.get("branch") or "").strip()
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", pay_date):
        return RedirectResponse(url="/closing", status_code=303)

    msg = "closed"
    conn = get_conn()
    try:
        resolved = _closing_resolve_branch(conn, user, is_all, branch_param)
        if not resolved:
            return RedirectResponse(url="/closing", status_code=303)
        key, name = resolved

        # 지점 계정은 마감 담당자 이름 필수(stock closing의 closer_name과 같은 개념)
        closer_name = str(form.get("closer_name") or "").strip()[:30]
        if user["role"] != "master" and not closer_name:
            return RedirectResponse(url=_closing_back_url(pay_date, branch_param, "closer_required"), status_code=303)

        if _closing_get_save(conn, key, pay_date):
            return RedirectResponse(url=_closing_back_url(pay_date, branch_param, "already"), status_code=303)

        # 비교표에서 직접 입력한 영수증 값을 먼저 반영한 뒤 최신 영수증 기준으로 검증한다
        _closing_save_receipt_groups(conn, key, name, pay_date, user["login_id"], form)

        data = _closing_load_all(conn, pay_date)
        rc = data["receipts"].get(key)
        if rc is None:
            return RedirectResponse(url=_closing_back_url(pay_date, branch_param, "no_receipt"), status_code=303)

        now_iso = _kst_now().strftime("%Y-%m-%d %H:%M:%S")
        # 입력한 메모를 먼저 저장(검사에서 막혀도 입력값이 사라지지 않게)
        for lb, memo in _closing_collect_memos(form).items():
            _closing_save_memo(conn, key, name, pay_date, lb, memo, user["login_id"], now_iso)
        conn.commit()

        pay = data["pay"].get(key)
        pg = pay["groups"] if pay else {}
        rows = _closing_compare(pg, rc["groups"])
        _crow = _closing_cash_compare_row(conn, pay_date, data["slot"], key)
        if _crow is not None:
            rows.append(_crow)
        mism = [r for r in rows if r[1] != r[3] or r[2] != r[4]]
        memos = _closing_get_memos(conn, key, pay_date)
        if any(not (memos.get(r[0], "").strip()) for r in mism):
            return RedirectResponse(url=_closing_back_url(pay_date, branch_param, "memo_required"), status_code=303)

        snap_rows = []
        for lb, pc, pa, rcc, rca in rows:
            snap_rows.append({
                "label": lb, "pay_cnt": pc, "pay_amt": pa, "rc_cnt": rcc, "rc_amt": rca,
                "diff_cnt": pc - rcc, "diff_amt": pa - rca, "memo": memos.get(lb, ""),
            })
        snapshot = {
            "slot": data["slot"], "received_at": data["received_at"],
            "receipt_entry_id": rc["id"], "receipt_method": rc["method"],
            "receipt_lines": rc["lines"], "rows": snap_rows,
            "closer_name": closer_name or None,
        }
        try:
            conn.execute(
                "INSERT INTO closing_saves (branch_key, branch_name, pay_date, payment_slot, receipt_entry_id, "
                "pay_total_cnt, pay_total_amt, rc_total_cnt, rc_total_amt, snapshot_json, saved_by, saved_at, "
                "version, mismatch_count) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                (key, name, pay_date, data["slot"], rc["id"],
                 sum(r[1] for r in rows), sum(r[2] for r in rows), sum(r[3] for r in rows), sum(r[4] for r in rows),
                 json.dumps(snapshot, ensure_ascii=False), user["login_id"], now_iso, 1, len(mism))
            )
            conn.commit()
            save_row = conn.execute(
                "SELECT id FROM closing_saves WHERE branch_key=? AND pay_date=? AND version=1", (key, pay_date)
            ).fetchone()
            save_id = save_row["id"]
            for lb, pc, pa, rcc, rca in mism:
                conn.execute(
                    "INSERT INTO closing_issues (save_id, branch_key, branch_name, pay_date, row_label, pay_cnt, pay_amt, "
                    "rc_cnt, rc_amt, diff_cnt, diff_amt, memo, status, created_at) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (save_id, key, name, pay_date, lb, pc, pa, rcc, rca, pc - rcc, pa - rca,
                     memos.get(lb, ""), "open", now_iso)
                )
            conn.commit()
        except Exception:
            msg = "already"
    finally:
        conn.close()
    return RedirectResponse(url=_closing_back_url(pay_date, branch_param, msg), status_code=303)


# =====================================================================
# 일 마감: 영수증 사진 업로드/보기(비공개 Storage 버킷) + 결제내역 보기
# - 사진은 브라우저에서 줄인 뒤 올린다(긴 변 1600px, JPEG 품질 0.8). 서버는 3MB 초과를 거부한다.
# - 비공개 버킷이라 앱이 로그인·권한을 확인한 뒤 /closing/image로만 보여 준다.
# - 마감 저장 후에는 사진 추가·삭제가 막힌다.
# =====================================================================
CLOSING_SUPABASE_URL = "https://fjznuesrbrwcqbdghegn.supabase.co"
CLOSING_IMG_BUCKET = "closing-receipts"
CLOSING_IMG_MAX_BYTES = 3 * 1024 * 1024
CLOSING_IMG_MAX_PER_DAY = 10
# 사진 압축/업로드 스크립트(f-string 아님: 중괄호 이스케이프 불필요)
CLOSING_UPLOAD_JS = """<script>
async function closingCompress(file) {
  var max = 1600;
  var source = null, w = 0, h = 0;
  try {
    source = await createImageBitmap(file, { imageOrientation: 'from-image' });
    w = source.width; h = source.height;
  } catch (e) {
    source = await new Promise(function (resolve, reject) {
      var img = new Image();
      var url = URL.createObjectURL(file);
      img.onload = function () { URL.revokeObjectURL(url); resolve(img); };
      img.onerror = reject;
      img.src = url;
    });
    w = source.naturalWidth; h = source.naturalHeight;
  }
  var scale = Math.min(1, max / Math.max(w, h));
  var cw = Math.max(1, Math.round(w * scale)), ch = Math.max(1, Math.round(h * scale));
  var canvas = document.createElement('canvas');
  canvas.width = cw; canvas.height = ch;
  var ctx = canvas.getContext('2d');
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(0, 0, cw, ch);
  ctx.drawImage(source, 0, 0, cw, ch);
  return await new Promise(function (resolve) { canvas.toBlob(resolve, 'image/jpeg', 0.8); });
}

async function closingUploadFiles(files, btn) {
  var status = document.getElementById('closing-upload-status');
  if (!files || !files.length) { status.textContent = '사진을 선택해 주세요.'; return; }
  btn.disabled = true;
  var ok = 0, fail = 0, total = 0, lastErr = '';
  for (var i = 0; i < files.length; i++) {
    status.textContent = (i + 1) + '/' + files.length + ' 올리는 중...';
    try {
      var blob = await closingCompress(files[i]);
      var fd = new FormData();
      fd.append('file', blob, 'receipt.jpg');
      fd.append('date', btn.dataset.date);
      fd.append('branch', btn.dataset.branch);
      var res = await fetch('/closing/upload', { method: 'POST', body: fd });
      var data = await res.json();
      if (res.ok) { ok++; total += blob.size; } else { fail++; lastErr = data.detail || '업로드 실패'; }
    } catch (e) {
      fail++; lastErr = '사진을 처리하지 못했습니다.';
    }
  }
  status.textContent = ok + '장 업로드 완료 (' + Math.round(total / 1024) + 'KB)'
    + (fail ? ' / 실패 ' + fail + '장: ' + lastErr : '');
  btn.disabled = false;
  if (ok) { setTimeout(function () { location.reload(); }, 900); }
}

function closingUpload(btn) {
  var input = document.getElementById('closing-photo');
  return closingUploadFiles(input.files, btn);
}

// ---------- 영수증 촬영·스캔 (jscanify + OpenCV.js, 첫 사용 시 CDN 로드) ----------
// 사용 요령: 평평한 곳에 단색 배경 위에 영수증을 놓고 촬영. 윤곽이 "충분히" 잡힐 때만 자동 크롭,
// 아니면 원본 그대로 저장한다. 실시간 오버레이는 400px 축소 프레임으로 800ms마다 처리한다.
var _clScan = {loading:false, queue:[], stream:null, scanner:null, video:null,
               overlay:null, timer:null, tickBusy:false, busy:false, found:false};

function clScanEnsure(cb) {
  if (window.jscanify && window.cv) { cb(); return; }
  _clScan.queue.push(cb);
  if (_clScan.loading) { return; }
  _clScan.loading = true;
  function done() {
    _clScan.loading = false;
    var q = _clScan.queue; _clScan.queue = [];
    q.forEach(function (f) { f(); });
  }
  var s1 = document.createElement('script');
  s1.src = 'https://cdn.jsdelivr.net/npm/jscanify@1.4.3/src/opencv.js';
  s1.onload = function () {
    var s2 = document.createElement('script');
    s2.src = 'https://cdn.jsdelivr.net/npm/jscanify@1.4.3/src/jscanify.js';
    s2.onload = done; s2.onerror = done;
    document.head.appendChild(s2);
  };
  s1.onerror = done;
  document.head.appendChild(s1);
}

function clScanStatus(t) {
  var el = document.getElementById('cl-scan-status');
  if (el) { el.textContent = t; }
}

function clScanFrame(maxW) {
  var v = _clScan.video;
  var w = v.videoWidth || 640, h = v.videoHeight || 480;
  var scale = maxW ? Math.min(1, maxW / w) : 1;
  var c = document.createElement('canvas');
  c.width = Math.max(1, Math.round(w * scale));
  c.height = Math.max(1, Math.round(h * scale));
  c.getContext('2d').drawImage(v, 0, 0, c.width, c.height);
  return c;
}

// 윤곽 품질 판정: 면적 비율(8~95%)과 bounding box 채움률(40%↑)을 모두 만족해야 "인식됨"으로 본다.
// (임의의 4점 윤곽을 문서로 오인해 이상하게 크롭되는 것을 막기 위함)
function clScanContourOk(img, contour) {
  if (!contour) { return false; }
  var area = 0;
  try { area = cv.contourArea(contour); } catch (e) { return false; }
  var imgArea = img.rows * img.cols;
  if (imgArea <= 0) { return false; }
  var ratio = area / imgArea;
  if (ratio < 0.08 || ratio > 0.95) { return false; }
  var rect = null;
  try { rect = cv.boundingRect(contour); } catch (e) { return false; }
  var bbox = (rect && rect.width > 0 && rect.height > 0) ? rect.width * rect.height : 0;
  if (bbox <= 0) { return false; }
  return (area / bbox) > 0.4;
}

// 실시간 오버레이: 프레임에서 윤곽을 찾아 모서리 4점을 화면 좌표로 그린다.
// object-fit:contain 기준으로 letterbox 오프셋을 계산해 정확히 맞춘다.
function clScanTick() {
  if (!_clScan.scanner || !_clScan.video || !_clScan.overlay) { return; }
  if (_clScan.tickBusy || _clScan.video.readyState < 2 || document.hidden) { return; }
  _clScan.tickBusy = true;
  var img = null, contour = null;
  try {
    var frame = clScanFrame(400);
    img = cv.imread(frame);
    contour = _clScan.scanner.findPaperContour(img);
    var ov = _clScan.overlay, v = _clScan.video;
    var dpr = window.devicePixelRatio || 1;
    var boxW = v.clientWidth, boxH = v.clientHeight;
    var cw = Math.round(boxW * dpr), ch = Math.round(boxH * dpr);
    if (ov.width !== cw || ov.height !== ch) { ov.width = cw; ov.height = ch; }
    var ctx = ov.getContext('2d');
    ctx.clearRect(0, 0, ov.width, ov.height);
    var ok = clScanContourOk(img, contour);
    _clScan.found = ok;
    if (ok) {
      var cp = _clScan.scanner.getCornerPoints(contour);
      if (cp && cp.topLeftCorner && cp.topRightCorner && cp.bottomLeftCorner && cp.bottomRightCorner) {
        var va = frame.width / frame.height, ba = boxW / boxH;
        var drawW, drawH, offX, offY;
        if (va > ba) { drawW = boxW; drawH = boxW / va; offX = 0; offY = (boxH - drawH) / 2; }
        else { drawH = boxH; drawW = boxH * va; offX = (boxW - drawW) / 2; offY = 0; }
        var sx = drawW / frame.width * dpr, sy = drawH / frame.height * dpr;
        var ox = offX * dpr, oy = offY * dpr;
        var pts = [cp.topLeftCorner, cp.topRightCorner, cp.bottomRightCorner, cp.bottomLeftCorner];
        ctx.strokeStyle = '#7C3AED'; ctx.lineWidth = 5 * dpr;
        ctx.shadowColor = 'rgba(0,0,0,.6)'; ctx.shadowBlur = 4 * dpr;
        ctx.beginPath();
        pts.forEach(function (p, i) {
          var x = ox + p.x * sx, y = oy + p.y * sy;
          if (i === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); }
        });
        ctx.closePath(); ctx.stroke();
        ctx.shadowBlur = 0;
      } else { ok = false; _clScan.found = false; }
    }
    clScanStatus(ok
      ? '윤곽 감지됨 — "촬영·저장"을 누르세요.'
      : '영수증 윤곽을 찾는 중... (단색 배경에 평평하게 놓아주세요)');
  } catch (e) { /* 프레임 처리 실패는 무시하고 다음 틱에 재시도 */ }
  finally {
    if (contour) { try { contour.delete(); } catch (e) {} }
    if (img) { try { img.delete(); } catch (e) {} }
    _clScan.tickBusy = false;
  }
}

function clScanCapture(btn) {
  if (_clScan.busy || !_clScan.video) { return; }
  _clScan.busy = true;
  btn.disabled = true;
  clScanStatus('촬영 중...');
  var img = null, contour = null;
  try {
    var frame = clScanFrame(0);
    var w = frame.width, h = frame.height;
    var out = null, cropped = false;
    if (_clScan.scanner) {
      try {
        img = cv.imread(frame);
        contour = _clScan.scanner.findPaperContour(img);
        if (clScanContourOk(img, contour)) {
          var cp = _clScan.scanner.getCornerPoints(contour);
          if (cp && cp.topLeftCorner && cp.bottomRightCorner) {
            var pw = 1200, ph = Math.max(200, Math.round(pw * h / w));
            out = _clScan.scanner.extractPaper(frame, pw, ph);
            cropped = !!out;
          }
        }
      } catch (e) { out = null; cropped = false; }
      finally {
        if (contour) { try { contour.delete(); } catch (e) {} }
        if (img) { try { img.delete(); } catch (e) {} }
      }
    }
    var src = out || frame;
    src.toBlob(function (blob) {
      _clScan.busy = false; btn.disabled = false;
      if (!blob) { clScanStatus('이미지 변환에 실패했습니다. 다시 시도하세요.'); return; }
      var file = new File([blob], cropped ? 'scanned-receipt.jpg' : 'receipt.jpg', {type: 'image/jpeg'});
      var upBtn = document.getElementById('closing-upload-btn');
      clScanStatus(cropped ? '윤곽을 잡아 잘라냈습니다 — 업로드 중...' : '윤곽이 확실하지 않아 원본 그대로 업로드 중...');
      closingUploadFiles([file], upBtn).then(function () { clScanClose(); });
    }, 'image/jpeg', 0.85);
  } catch (e) {
    _clScan.busy = false; btn.disabled = false;
    clScanStatus('촬영 실패: ' + e.message);
  }
}

function clScanClose() {
  if (_clScan.timer) { clearInterval(_clScan.timer); _clScan.timer = null; }
  if (_clScan.stream) {
    _clScan.stream.getTracks().forEach(function (t) { t.stop(); });
    _clScan.stream = null;
  }
  var m = document.getElementById('cl-scan-modal');
  if (m) { m.remove(); }
  _clScan.video = null; _clScan.overlay = null; _clScan.scanner = null; _clScan.found = false;
}

function clScanOpen() {
  if (document.getElementById('cl-scan-modal')) { return; }
  var modal = document.createElement('div');
  modal.id = 'cl-scan-modal';
  modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:#000;display:flex;flex-direction:column;';
  modal.innerHTML =
    '<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 12px;color:#fff;flex:0 0 auto;">'
    + '<span style="font-size:14px;font-weight:bold;">📄 영수증 촬영·스캔</span>'
    + '<button type="button" id="cl-scan-x" class="btn" style="background:#6B7280;padding:4px 10px;">✕</button></div>'
    + '<div style="position:relative;flex:1 1 auto;min-height:0;background:#000;">'
    + '<video id="cl-scan-video" autoplay playsinline muted style="position:absolute;inset:0;width:100%;height:100%;object-fit:contain;"></video>'
    + '<canvas id="cl-scan-overlay" style="position:absolute;inset:0;width:100%;height:100%;pointer-events:none;"></canvas></div>'
    + '<div style="flex:0 0 auto;background:#111;color:#eee;padding:10px 12px;">'
    + '<div id="cl-scan-status" style="font-size:12px;min-height:16px;margin-bottom:8px;color:#DDD;"></div>'
    + '<div style="display:flex;gap:8px;">'
    + '<button type="button" class="btn" id="cl-scan-cap" style="flex:1;background:#10B981;">📷 촬영·저장</button>'
    + '<button type="button" class="btn" id="cl-scan-reload" style="background:#334155;display:none;">다시 시도</button>'
    + '</div>'
    + '<div style="font-size:11px;color:#999;margin-top:6px;line-height:1.5;">평평한 곳에 <b>단색 배경</b>을 깔고 영수증을 놓아주세요. '
    + '윤곽이 확실히 잡힐 때만 잘라서 저장하고, 애매하면 원본 그대로 저장합니다. '
    + '(카메라가 없으면 파일 선택을 이용하세요)</div></div>';
  document.body.appendChild(modal);
  document.getElementById('cl-scan-x').addEventListener('click', clScanClose);
  document.getElementById('cl-scan-cap').addEventListener('click', function () { clScanCapture(this); });
  document.getElementById('cl-scan-reload').addEventListener('click', clScanOpen);
  modal.addEventListener('click', function (e) { if (e.target === modal) { clScanClose(); } });

  clScanStatus('카메라·스캔 라이브러리를 여는 중... (최초 1회 수십 초 걸릴 수 있습니다)');
  clScanEnsure(function () {
    if (!window.jscanify || !window.cv) {
      clScanStatus('스캔 라이브러리 로딩 실패 — 네트워크 확인 후 "다시 시도"를 누르세요.');
      document.getElementById('cl-scan-reload').style.display = '';
      return;
    }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      clScanStatus('이 브라우저는 카메라를 지원하지 않습니다 — 파일 선택을 이용하세요.');
      return;
    }
    navigator.mediaDevices.getUserMedia({video: {facingMode: 'environment', width: {ideal: 1920}}})
      .then(function (stream) {
        _clScan.stream = stream;
        var v = document.getElementById('cl-scan-video');
        v.srcObject = stream;
        _clScan.video = v;
        _clScan.overlay = document.getElementById('cl-scan-overlay');
        try { _clScan.scanner = new jscanify(); } catch (e) { _clScan.scanner = null; }
        clScanStatus(_clScan.scanner
          ? '준비 완료 — 영수증을 비추고 "촬영·저장"을 누르세요.'
          : '스캐너 초기화 실패 — 촬영하면 원본 그대로 저장됩니다.');
        _clScan.timer = setInterval(clScanTick, 800);
      })
      .catch(function (e) {
        clScanStatus('카메라를 열 수 없습니다(' + e.message + ') — 파일 선택을 이용하세요.');
      });
  });
}

(function () {
  var btn = document.getElementById('closing-upload-btn');
  if (!btn) { return; }
  var scan = document.createElement('button');
  scan.type = 'button';
  scan.className = 'btn';
  scan.style.background = '#065F46';
  scan.textContent = '📷 촬영·스캔';
  scan.title = '카메라로 영수증을 비추면 윤곽을 자동 인식해 잘라 저장합니다';
  scan.addEventListener('click', clScanOpen);
  btn.parentNode.insertBefore(scan, btn);
})();
</script>"""


def _closing_sniff_image(raw: bytes):
    """파일 앞부분으로 이미지 종류를 판별한다. 반환: (확장자, content-type) 또는 None"""
    if raw[:3] == b"\xff\xd8\xff":
        return "jpg", "image/jpeg"
    if raw[:8] == b"\x89PNG\r\n\x1a\n":
        return "png", "image/png"
    if raw[:4] == b"RIFF" and raw[8:12] == b"WEBP":
        return "webp", "image/webp"
    return None


def _closing_storage_headers(content_type: str = "") -> dict:
    key = os.environ.get("PURCHASE_SUPABASE_SERVICE_ROLE_KEY", "")
    headers = {"Authorization": "Bearer " + key, "apikey": key}
    if content_type:
        headers["Content-Type"] = content_type
    return headers


@app.post("/closing/upload")
async def closing_upload(request: Request, session_token: str = Cookie(default=None)):
    """영수증 사진 1장 업로드(브라우저에서 줄여서 보낸 파일). 마감 저장 전에만 가능."""
    import re
    import uuid

    user = get_session(session_token)
    if not user:
        return JSONResponse(status_code=401, content={"detail": "로그인이 필요합니다."})
    is_all = user["role"] == "master" or user.get("branch_type") == "hq"
    if is_all and not has_menu_permission(user["login_id"], "closing"):
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    form = await request.form()
    pay_date = str(form.get("date") or "").strip()
    branch_param = str(form.get("branch") or "").strip()
    file = form.get("file")
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", pay_date) or not file:
        return JSONResponse(status_code=400, content={"detail": "요청이 올바르지 않습니다."})

    raw = await file.read()
    if len(raw) > CLOSING_IMG_MAX_BYTES:
        return JSONResponse(status_code=400, content={"detail": "사진 크기가 너무 큽니다(3MB 이하)."})
    kind = _closing_sniff_image(raw)
    if not kind:
        return JSONResponse(status_code=400, content={"detail": "이미지 파일(jpg/png/webp)만 올릴 수 있습니다."})
    if not os.environ.get("PURCHASE_SUPABASE_SERVICE_ROLE_KEY", ""):
        return JSONResponse(status_code=500, content={"detail": "서버 설정 오류: 저장소 키가 없습니다."})

    ext, ctype = kind
    conn = get_conn()
    try:
        resolved = _closing_resolve_branch(conn, user, is_all, branch_param)
        if not resolved:
            return JSONResponse(status_code=403, content={"detail": "지점을 확인할 수 없습니다."})
        key, name = resolved
        if _closing_get_save(conn, key, pay_date):
            return JSONResponse(status_code=403, content={"detail": "마감 저장된 일자는 사진을 추가할 수 없습니다."})
        cnt_row = conn.execute(
            "SELECT COUNT(*) AS c FROM receipt_images WHERE branch_key=? AND pay_date=?", (key, pay_date)
        ).fetchone()
        if int(cnt_row["c"] or 0) >= CLOSING_IMG_MAX_PER_DAY:
            return JSONResponse(status_code=400, content={"detail": "하루 최대 " + str(CLOSING_IMG_MAX_PER_DAY) + "장까지 올릴 수 있습니다."})

        path = pay_date + "/" + uuid.uuid4().hex + "." + ext
        upload_url = CLOSING_SUPABASE_URL + "/storage/v1/object/" + CLOSING_IMG_BUCKET + "/" + path
        async with httpx.AsyncClient(timeout=30) as client:
            resp = await client.put(upload_url, content=raw, headers=_closing_storage_headers(ctype))
        if resp.status_code >= 300:
            return JSONResponse(status_code=502, content={
                "detail": "사진 저장에 실패했습니다(" + str(resp.status_code) + "): " + resp.text[:120]})

        now_iso = _kst_now().strftime("%Y-%m-%d %H:%M:%S")
        conn.execute(
            "INSERT INTO receipt_images (branch_key, branch_name, pay_date, storage_path, original_name, "
            "content_type, size_bytes, uploaded_by, uploaded_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (key, name, pay_date, path, (getattr(file, "filename", "") or "")[:120], ctype, len(raw),
             user["login_id"], now_iso)
        )
        conn.commit()
    finally:
        conn.close()
    return JSONResponse(content={"ok": True})


@app.get("/closing/image")
async def closing_image(id: int = 0, session_token: str = Cookie(default=None)):
    """비공개 버킷의 영수증 사진을 로그인·권한 확인 후 내려 준다."""
    from fastapi.responses import Response

    user = get_session(session_token)
    if not user:
        return Response(status_code=401)
    is_all = user["role"] == "master" or user.get("branch_type") == "hq"
    if is_all and not has_menu_permission(user["login_id"], "closing"):
        return Response(status_code=403)

    conn = get_conn()
    try:
        row = conn.execute(
            "SELECT branch_key, storage_path, content_type FROM receipt_images WHERE id=?", (id,)
        ).fetchone()
    finally:
        conn.close()
    if not row:
        return Response(status_code=404)
    if not is_all and row["branch_key"] != _closing_norm(user.get("branch_code")):
        return Response(status_code=403)

    url = CLOSING_SUPABASE_URL + "/storage/v1/object/authenticated/" + CLOSING_IMG_BUCKET + "/" + row["storage_path"]
    async with httpx.AsyncClient(timeout=30) as client:
        resp = await client.get(url, headers=_closing_storage_headers())
    if resp.status_code != 200:
        return Response(status_code=404)
    return Response(content=resp.content, media_type=row["content_type"] or "image/jpeg",
                    headers={"Cache-Control": "private, max-age=3600"})


@app.post("/closing-guide/upload")
async def closing_guide_upload(request: Request, session_token: str = Cookie(default=None)):
    """마감 가이드 파일 업로드 — 마스터 전용. 매출/재고 마감 페이지별로 최신 파일 1개를 보여 준다."""
    import uuid

    user = get_session(session_token)
    if not user:
        return RedirectResponse(url="/login", status_code=303)
    if user.get("role") != "master":
        return RedirectResponse(url="/", status_code=303)
    if not os.environ.get("PURCHASE_SUPABASE_SERVICE_ROLE_KEY", ""):
        return HTMLResponse(content=render_page(
            '<div class="card">서버 설정 오류: 저장소 키가 없습니다.</div>', user, ""), status_code=500)

    form = await request.form()
    page = str(form.get("page") or "").strip()
    nxt = str(form.get("next") or "").strip()
    file = form.get("file")
    back = "/" + (nxt if nxt in CLOSING_GUIDE_PAGES else "closing")
    if page not in CLOSING_GUIDE_PAGES or not file:
        return RedirectResponse(url=back, status_code=303)

    raw = await file.read()
    if len(raw) > CLOSING_GUIDE_MAX_BYTES or len(raw) == 0:
        return RedirectResponse(url=back, status_code=303)
    fname = (getattr(file, "filename", "") or "")
    ext = fname.rsplit(".", 1)[-1].lower() if "." in fname else ""
    ctype = CLOSING_GUIDE_TYPES.get(ext)
    if not ctype:
        return RedirectResponse(url=back, status_code=303)

    path = "guides/" + page + "/" + uuid.uuid4().hex + "." + ext
    upload_url = CLOSING_SUPABASE_URL + "/storage/v1/object/" + CLOSING_IMG_BUCKET + "/" + path
    async with httpx.AsyncClient(timeout=60) as client:
        resp = await client.put(upload_url, content=raw, headers=_closing_storage_headers(ctype))
    if resp.status_code >= 300:
        return HTMLResponse(content=render_page(
            '<div class="card">가이드 업로드에 실패했습니다(' + str(resp.status_code) + ").</div>",
            user, ""), status_code=502)

    now_iso = _kst_now().strftime("%Y-%m-%d %H:%M:%S")
    conn = get_conn()
    try:
        conn.execute(
            "INSERT INTO closing_guide_files (page, storage_path, original_name, content_type, "
            "size_bytes, uploaded_by, uploaded_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
            (page, path, fname[:200], ctype, len(raw), user["login_id"], now_iso)
        )
        conn.commit()
    finally:
        conn.close()
    return RedirectResponse(url=back, status_code=303)


