SAFETY_COMPARE_STATUSES = [
    "상향", "하향", "동일", "신규 후보", "판매 없음(유지)", "리드타임 없음",
    "제외(소모품)", "제외(발주 제외)", "제외(마스터 없음)",
]


def _compute_safety_recommendations(start_date: str, end_date: str, factor: float, min_qty: int, moq_mode: str = "show") -> list:
    """판매내역 기준 안전재고 추천값 계산(읽기 전용).
    추천 안전재고 = max(최소값, 올림(기간 일평균 순판매량 x 리드타임 x 안전계수))
    최소값: 상품 마스터 min_safety_qty(품번 단위, 지점 간 MAX)가 있으면 그 값, 비어 있으면 화면의 공통 min_qty
    moq_mode: "show"  = 추천값은 그대로 두고 MOQ 적용 발주 수량만 따로 표시
              "round" = 추천값을 MOQ 배수로 올림
              "floor" = 추천값이 MOQ보다 작으면 MOQ로 올림
    본사는 판매 지점이 아니므로 제외한다. 현재값과 판매가 모두 0인 조합은 목록에서 뺀다.
    """
    import math
    from datetime import date as _date

    d0 = _date.fromisoformat(start_date)
    d1 = _date.fromisoformat(end_date)
    days = (d1 - d0).days + 1

    conn = get_conn()
    try:
        safety_rows = conn.execute(
            "SELECT id, branch_name, item_name, item_code, qty FROM safety_stock WHERE branch_name <> '본사'"
        ).fetchall()
        pm_rows = conn.execute(
            "SELECT item_code, MAX(item_name) AS item_name, MIN(NULLIF(lead_time_days, 0)) AS lead_time_days, "
            "MAX(COALESCE(NULLIF(moq, 0), 1)) AS moq, "
            "MAX(min_safety_qty) AS min_safety_qty, "
            "BOOL_OR(COALESCE(is_consumable, FALSE)) AS is_consumable, "
            "BOOL_OR(COALESCE(order_excluded, FALSE)) AS order_excluded "
            "FROM product_master WHERE item_code IS NOT NULL AND item_code <> '' GROUP BY item_code"
        ).fetchall()
        sales_rows = conn.execute(
            "SELECT branch_name, item_code, SUM(quantity) AS sold FROM sales_records "
            "WHERE sale_date >= ? AND sale_date <= ? AND item_code <> '' GROUP BY branch_name, item_code",
            (start_date, end_date)
        ).fetchall()
    finally:
        conn.close()

    pm = {r["item_code"]: r for r in pm_rows}
    sold_map = {(r["branch_name"], r["item_code"]): int(r["sold"] or 0) for r in sales_rows}
    branches = {r["branch_name"] for r in safety_rows}

    def _make_row(row_id, branch, name, code, cur, sold):
        p = pm.get(code)
        lead = int(p["lead_time_days"]) if p and p["lead_time_days"] else 0
        moq = int(p["moq"]) if p and p["moq"] else 1
        item_min = int(p["min_safety_qty"]) if p and p["min_safety_qty"] is not None else None
        min_used = item_min if item_min is not None else min_qty
        avg = sold / days
        rec = None
        if p is None:
            status = "제외(마스터 없음)"
        elif p["is_consumable"]:
            status = "제외(소모품)"
        elif p["order_excluded"]:
            status = "제외(발주 제외)"
        elif lead <= 0:
            status = "리드타임 없음"
        elif sold <= 0:
            status = "판매 없음(유지)"
        else:
            rec = max(min_used, math.ceil(round(avg * lead * factor, 6)))
            if moq_mode == "round":
                rec = math.ceil(rec / moq) * moq
            elif moq_mode == "floor":
                rec = max(rec, moq)
            if cur <= 0:
                status = "신규 후보"
            elif rec > cur:
                status = "상향"
            elif rec < cur:
                status = "하향"
            else:
                status = "동일"
        order_qty = (math.ceil(rec / moq) * moq) if rec is not None else None
        return {
            "id": row_id, "branch_name": branch, "item_name": name, "item_code": code,
            "lead_time": lead, "moq": moq, "sold": sold, "avg_daily": avg, "current": cur,
            "min_used": min_used, "min_custom": item_min is not None,
            "recommended": rec, "order_qty": order_qty,
            "diff": (rec - cur) if rec is not None else None, "status": status,
        }

    out = []
    seen = set()
    for r in safety_rows:
        code = r["item_code"] or ""
        branch = r["branch_name"]
        cur = int(r["qty"] or 0)
        seen.add((branch, code))
        sold = sold_map.get((branch, code), 0)
        if cur <= 0 and sold <= 0:
            continue
        out.append(_make_row(r["id"], branch, r["item_name"], code, cur, sold))

    # 판매는 있는데 안전재고 행 자체가 없는 조합(신규 후보)
    for (branch, code), sold in sold_map.items():
        if (branch, code) in seen or branch not in branches or sold <= 0:
            continue
        p = pm.get(code)
        if p is None or p["is_consumable"] or p["order_excluded"]:
            continue
        out.append(_make_row(None, branch, p["item_name"], code, 0, sold))
    return out


def _safety_compare_load(start, end, factor, min_qty, moq_mode, filter_branch, filter_status, search_item, sort):
    """판매 기반 비교 화면과 엑셀 다운로드가 함께 쓰는 조회·필터 처리.
    판매내역 데이터가 없으면 None을 돌려준다. rows는 필터·정렬을 적용한 결과(건수 제한 없음)."""
    import collections
    from datetime import date as _date

    conn = get_conn()
    rng = conn.execute("SELECT MIN(sale_date) AS d0, MAX(sale_date) AS d1 FROM sales_records").fetchone()
    conn.close()
    if not rng or not rng["d0"]:
        return None
    data_start, data_end = rng["d0"], rng["d1"]

    def _valid_date(s: str, default: str) -> str:
        try:
            _date.fromisoformat(s)
            return s
        except Exception:
            return default

    start_v = _valid_date((start or "").strip(), data_start)
    end_v = _valid_date((end or "").strip(), data_end)
    if start_v > end_v:
        start_v, end_v = end_v, start_v
    try:
        factor_v = float(factor)
        if factor_v <= 0 or factor_v > 10:
            factor_v = 1.05
    except ValueError:
        factor_v = 1.05
    try:
        min_v = max(0, int(min_qty))
    except ValueError:
        min_v = 1

    moq_mode_v = moq_mode if moq_mode in ("show", "round", "floor") else "show"
    all_rows = _compute_safety_recommendations(start_v, end_v, factor_v, min_v, moq_mode_v)
    days = (_date.fromisoformat(end_v) - _date.fromisoformat(start_v)).days + 1

    counts = collections.Counter(r["status"] for r in all_rows)
    cur_total = sum(r["current"] for r in all_rows if r["recommended"] is not None)
    rec_total = sum(r["recommended"] for r in all_rows if r["recommended"] is not None)

    rows = all_rows
    if filter_branch:
        rows = [r for r in rows if r["branch_name"] == filter_branch]
    if filter_status:
        rows = [r for r in rows if r["status"] == filter_status]
    kw = (search_item or "").strip().lower()
    if kw:
        rows = [r for r in rows if kw in (r["item_name"] or "").lower() or kw in (r["item_code"] or "").lower()]
    if sort == "diff":
        rows = sorted(rows, key=lambda r: -abs(r["diff"]) if r["diff"] is not None else 0)
    else:
        rows = sorted(rows, key=lambda r: (r["branch_name"], r["item_name"] or ""))

    return {
        "start_v": start_v, "end_v": end_v, "factor_v": factor_v, "min_v": min_v,
        "moq_mode_v": moq_mode_v, "data_start": data_start, "data_end": data_end,
        "days": days, "all_rows": all_rows, "rows": rows, "counts": counts,
        "cur_total": cur_total, "rec_total": rec_total,
    }


SAFETY_COMPARE_APPLY_STATUSES = ("상향", "하향", "신규 후보")

SAFETY_COMPARE_APPLY_JS = r"""
const SC_PARAMS = __PARAMS__;

function scPicked() {
  return Array.from(document.querySelectorAll('.sc-pick:checked'));
}

function scUpdateCount() {
  const els = scPicked();
  let up = 0, down = 0, nw = 0;
  els.forEach(function (e) {
    const s = e.dataset.status;
    if (s === '상향') up++;
    else if (s === '하향') down++;
    else nw++;
  });
  document.getElementById('scPickedCount').innerText =
    '선택됨: ' + els.length + '건 (상향 ' + up + ' / 하향 ' + down + ' / 신규 ' + nw + ')';
}

document.addEventListener('change', function (e) {
  if (e.target.classList && e.target.classList.contains('sc-pick')) scUpdateCount();
});

function scPickAll(mode) {
  document.querySelectorAll('.sc-pick').forEach(function (cb) {
    if (mode === 'none') cb.checked = false;
    else if (mode === 'up' && cb.dataset.status === '상향') cb.checked = true;
    else if (mode === 'down' && cb.dataset.status === '하향') cb.checked = true;
  });
  scUpdateCount();
}

async function scApply() {
  const els = scPicked();
  if (!els.length) { alert('선택된 항목이 없습니다.'); return; }
  const maxDown = parseInt(document.getElementById('scMaxDown').value) || 0;
  let up = 0, down = 0, nw = 0;
  const items = els.map(function (e) {
    const s = e.dataset.status;
    if (s === '상향') up++;
    else if (s === '하향') down++;
    else nw++;
    return { key: e.dataset.key, cur: parseInt(e.dataset.cur), rec: parseInt(e.dataset.rec) };
  });
  const msg = '안전재고를 실제로 변경합니다.\n\n상향 ' + up + '건 / 하향 ' + down + '건 / 신규 ' + nw + '건\n'
    + '하향 1회 최대 폭: ' + (maxDown > 0 ? (maxDown + '%') : '제한 없음') + '\n\n'
    + '계속하시겠습니까? (변경 이력이 기록됩니다)';
  if (!confirm(msg)) return;
  const btn = document.getElementById('scApplyBtn');
  btn.disabled = true;
  const payload = Object.assign({}, SC_PARAMS, { items: items, max_down_pct: maxDown });
  let res, data = {};
  try {
    res = await fetch('/master/purchase-order/safety-stock/compare/apply', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    try { data = await res.json(); } catch (err) { data = {}; }
  } catch (err) {
    alert('요청 실패: ' + err);
    btn.disabled = false;
    return;
  }
  if (res.ok) {
    let text = '적용 완료: ' + data.applied + '건 (상향 ' + data.applied_up + ' / 하향 ' + data.applied_down + ' / 신규 ' + data.applied_new + ')\n배치 ID: ' + data.batch_id;
    if (data.skipped && data.skipped.length) {
      text += '\n\n건너뜀 ' + data.skipped.length + '건:\n';
      text += data.skipped.slice(0, 10).map(function (s) { return '- ' + s.key.replace('||', ' / ') + ': ' + s.reason; }).join('\n');
      if (data.skipped.length > 10) text += '\n... 외 ' + (data.skipped.length - 10) + '건';
    }
    alert(text);
    location.reload();
  } else {
    alert('적용 실패: ' + (data.detail || '오류'));
    btn.disabled = false;
  }
}

scUpdateCount();
"""


@app.get("/master/purchase-order/safety-stock/compare", response_class=HTMLResponse)
async def safety_stock_compare_page(
    session_token: str = Cookie(default=None),
    start: str = "",
    end: str = "",
    factor: str = "1.05",
    min_qty: str = "1",
    filter_branch: str = "",
    filter_status: str = "",
    search_item: str = "",
    sort: str = "name",
    moq_mode: str = "show"
):
    from html import escape as _esc
    from datetime import date as _date, timedelta
    from urllib.parse import urlencode
    import json as _json

    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "safety-stock"):
        return RedirectResponse(url="/master", status_code=303)

    res = _safety_compare_load(start, end, factor, min_qty, moq_mode, filter_branch, filter_status, search_item, sort)
    if res is None:
        content = '<div class="card"><p>판매내역 데이터가 없습니다. 먼저 판매내역을 적재해 주세요.</p></div>'
        return HTMLResponse(content=render_page(content, user, "master"))

    start_v = res["start_v"]
    end_v = res["end_v"]
    factor_v = res["factor_v"]
    min_v = res["min_v"]
    moq_mode_v = res["moq_mode_v"]
    data_start = res["data_start"]
    data_end = res["data_end"]
    days = res["days"]
    all_rows = res["all_rows"]
    counts = res["counts"]
    cur_total = res["cur_total"]
    rec_total = res["rec_total"]

    rows = res["rows"]
    total_rows = len(rows)
    rows = rows[:2000]

    export_qs = urlencode({
        "start": start_v, "end": end_v, "factor": factor_v, "min_qty": min_v,
        "moq_mode": moq_mode_v, "filter_branch": filter_branch or "",
        "filter_status": filter_status or "", "search_item": search_item or "", "sort": sort,
    })
    export_url = _esc("/master/purchase-order/safety-stock/compare/export?" + export_qs)

    apply_params = _json.dumps(
        {"start": start_v, "end": end_v, "factor": factor_v, "min_qty": min_v, "moq_mode": moq_mode_v},
        ensure_ascii=False
    )
    script_js = SAFETY_COMPARE_APPLY_JS.replace("__PARAMS__", apply_params)

    branch_names = sorted({r["branch_name"] for r in all_rows})
    branch_opts = '<option value="">전체 지점</option>' + "".join(
        f'<option value="{_esc(b)}" {"selected" if b == filter_branch else ""}>{_esc(b)}</option>' for b in branch_names
    )
    status_opts = '<option value="">전체 상태</option>' + "".join(
        f'<option value="{_esc(s)}" {"selected" if s == filter_status else ""}>{_esc(s)} ({counts.get(s, 0)})</option>'
        for s in SAFETY_COMPARE_STATUSES
    )

    def _preset(label: str, n_days: int) -> str:
        e = _date.fromisoformat(data_end)
        s = max(_date.fromisoformat(data_start), e - timedelta(days=n_days - 1))
        return (f'<a href="?start={s.isoformat()}&end={e.isoformat()}&factor={factor_v}&min_qty={min_v}&moq_mode={moq_mode_v}" '
                f'style="font-size:12px;color:#1E2761;margin-right:10px;">{label}</a>')

    presets = (_preset("최근 28일", 28) + _preset("최근 56일", 56)
               + f'<a href="?start={data_start}&end={data_end}&factor={factor_v}&min_qty={min_v}&moq_mode={moq_mode_v}" '
                 f'style="font-size:12px;color:#1E2761;">전체 보관기간</a>')

    body = ""
    for r in rows:
        diff = r["diff"]
        diff_cls = "sc-up" if (diff is not None and diff > 0) else ("sc-down" if (diff is not None and diff < 0) else "")
        diff_txt = "-" if diff is None else f"{diff:+d}"
        rec_txt = "-" if r["recommended"] is None else str(r["recommended"])
        ord_txt = "-" if r["order_qty"] is None else str(r["order_qty"])
        if r["recommended"] is None:
            min_txt = "-"
        else:
            min_txt = str(r["min_used"]) + ("★" if r["min_custom"] else "")
        selectable = (r["status"] in SAFETY_COMPARE_APPLY_STATUSES) and (r["recommended"] is not None)
        if selectable:
            key_raw = (r["branch_name"] or "") + "||" + (r["item_code"] or "")
            pick_td = (
                '<td style="text-align:center;"><input type="checkbox" class="sc-pick" '
                'data-key="' + _esc(key_raw) + '" data-cur="' + str(r["current"]) + '" '
                'data-rec="' + str(r["recommended"]) + '" data-status="' + _esc(r["status"]) + '" '
                'style="width:16px;height:16px;"></td>'
            )
        else:
            pick_td = "<td></td>"
        body += (
            "<tr>"
            + pick_td +
            f'<td>{_esc(r["branch_name"])}</td>'
            f'<td>{_esc(r["item_name"] or "")}</td>'
            f'<td>{_esc(r["item_code"] or "")}</td>'
            f'<td class="sc-num">{r["lead_time"] or "-"}</td>'
            f'<td class="sc-num">{r["sold"]}</td>'
            f'<td class="sc-num">{r["avg_daily"]:.2f}</td>'
            f'<td class="sc-num">{r["moq"]}</td>'
            f'<td class="sc-num">{min_txt}</td>'
            f'<td class="sc-num">{r["current"]}</td>'
            f'<td class="sc-num"><b>{rec_txt}</b></td>'
            f'<td class="sc-num">{ord_txt}</td>'
            f'<td class="sc-num {diff_cls}">{diff_txt}</td>'
            f'<td><span class="sc-chip">{_esc(r["status"])}</span></td>'
            "</tr>"
        )
    if not body:
        body = '<tr><td colspan="14" style="text-align:center;padding:20px;color:#888;">조건에 맞는 항목이 없습니다.</td></tr>'

    chips = "".join(f'<div>{_esc(s)} <b>{counts.get(s, 0)}</b></div>' for s in SAFETY_COMPARE_STATUSES)

    content = f"""
    {SAFETY_COMPARE_CSS}
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">
      <a href="/master/purchase-order/safety-stock" style="color:#1E2761;">← 안전재고 관리</a>
      <h2>📊 안전재고 판매 기반 비교</h2>
    </div>
    <div class="card" style="background:#EFF6FF;border:1px solid #93C5FD;">
      <p style="font-size:13px;color:#1E40AF;">
        추천 안전재고 = 올림(기간 일평균 순판매량 × 리드타임 × 안전계수), 최소값 적용. 리드타임에 발주 주기가 포함돼 있다고 보고 별도로 더하지 않습니다.
        발주 시 수량은 추천값을 MOQ 배수로 올린 값으로, 발주 계산과 같은 방식입니다.
        최소 열의 ★는 상품 설정에서 상품별 최소값을 입력한 행이고, 표시가 없는 행은 위 입력창의 공통 최소값을 씁니다.
        표의 체크박스로 고른 행만 <b>선택 적용</b>으로 실제 안전재고에 반영할 수 있고, 반영 내역은 변경 이력에 기록됩니다.
        신규 후보(현재 안전재고 0)는 자동 선택되지 않으며 직접 체크한 경우에만 반영됩니다. 소모품·발주 제외·본사는 계산에서 제외하고 기존 값을 유지합니다.
      </p>
    </div>
    <div class="card">
      <form method="get" action="/master/purchase-order/safety-stock/compare" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;">
        <div><label style="font-size:12px;color:#888;">시작일</label><input type="date" name="start" value="{start_v}"></div>
        <div><label style="font-size:12px;color:#888;">종료일</label><input type="date" name="end" value="{end_v}"></div>
        <div><label style="font-size:12px;color:#888;">안전계수</label><input type="number" step="0.01" name="factor" value="{factor_v}" style="width:90px;"></div>
        <div><label style="font-size:12px;color:#888;">공통 최소값</label><input type="number" name="min_qty" value="{min_v}" style="width:80px;"></div>
        <div><label style="font-size:12px;color:#888;">MOQ 반영</label>
          <select name="moq_mode">
            <option value="show" {"selected" if moq_mode_v == "show" else ""}>표시만 (추천은 그대로)</option>
            <option value="round" {"selected" if moq_mode_v == "round" else ""}>추천을 MOQ 배수로 올림</option>
            <option value="floor" {"selected" if moq_mode_v == "floor" else ""}>추천 최소값을 MOQ로</option>
          </select></div>
        <div><label style="font-size:12px;color:#888;">지점</label><select name="filter_branch">{branch_opts}</select></div>
        <div><label style="font-size:12px;color:#888;">상태</label><select name="filter_status">{status_opts}</select></div>
        <div><label style="font-size:12px;color:#888;">검색</label><input type="text" name="search_item" value="{_esc(search_item or '')}" placeholder="상품명/품번"></div>
        <div><label style="font-size:12px;color:#888;">정렬</label>
          <select name="sort"><option value="name" {"selected" if sort != "diff" else ""}>지점·상품명</option><option value="diff" {"selected" if sort == "diff" else ""}>변화 큰 순</option></select></div>
        <button class="btn" type="submit">조회</button>
        <a href="{export_url}" class="btn" style="background:#22C55E;text-decoration:none;display:inline-block;">📥 엑셀 다운로드</a>
      </form>
      <p style="margin-top:8px;">{presets}</p>
      <p style="font-size:12px;color:#666;margin-top:6px;">
        적용 기간 {start_v} ~ {end_v} ({days}일) · 보관 데이터 {data_start} ~ {data_end} · 엑셀과 선택 적용은 마지막으로 조회한 조건 그대로 동작합니다(조건을 바꿨다면 먼저 조회를 누르세요).
      </p>
    </div>
    <div class="sc-sum">{chips}
      <div>계산 대상 현재 합계 <b>{cur_total}</b></div><div>추천 합계 <b>{rec_total}</b></div>
    </div>
    <div class="card" style="background:#FEF2F2;border:1px solid #FCA5A5;">
      <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
        <button type="button" class="btn" style="background:#64748B;" onclick="scPickAll('up')">상향 전체 선택</button>
        <button type="button" class="btn" style="background:#64748B;" onclick="scPickAll('down')">하향 전체 선택</button>
        <button type="button" class="btn" style="background:#94A3B8;" onclick="scPickAll('none')">선택 해제</button>
        <span id="scPickedCount" style="font-size:13px;color:#555;">선택됨: 0건</span>
        <label style="font-size:13px;color:#555;">하향 1회 최대 폭(%)
          <input type="number" id="scMaxDown" value="30" min="0" max="100" style="width:70px;"></label>
        <span style="font-size:12px;color:#888;">0이면 제한 없음. 예: 30이면 현재값의 70% 아래로는 한 번에 낮추지 않음</span>
        <button type="button" class="btn" id="scApplyBtn" style="background:#EF4444;margin-left:auto;" onclick="scApply()">⚠️ 선택 적용</button>
      </div>
    </div>
    <div class="card">
      <p style="font-size:12px;color:#666;margin-bottom:8px;">표시 {len(rows)}건 / 조건 일치 {total_rows}건{' (상위 2000건만 표시, 엑셀은 전체)' if total_rows > 2000 else ''}</p>
      <div class="sc-wrap">
        <table class="sc-table">
          <thead><tr>
            <th>선택</th><th>지점</th><th>상품명</th><th>품번</th><th class="sc-num">리드타임</th><th class="sc-num">기간 판매</th>
            <th class="sc-num">일평균</th><th class="sc-num">MOQ</th><th class="sc-num">최소</th><th class="sc-num">현재</th><th class="sc-num">추천</th><th class="sc-num">발주 시 수량</th><th class="sc-num">증감</th><th>상태</th>
          </tr></thead>
          <tbody>{body}</tbody>
        </table>
      </div>
    </div>
    <script>{script_js}</script>
    """
    return HTMLResponse(content=render_page(content, user, "master"))


@app.post("/master/purchase-order/safety-stock/compare/apply")
async def safety_stock_compare_apply(request: Request, session_token: str = Cookie(default=None)):
    """선택한 추천값을 실제 안전재고에 반영한다.
    - 화면 숫자는 믿지 않고 서버가 같은 조건으로 다시 계산한다.
    - 화면에서 본 현재값·추천값과 서버 값이 다르면 그 행은 건너뛴다.
    - 하향은 max_down_pct가 있으면 현재값의 (100-N)% 아래로 한 번에 낮추지 않는다.
    - 반영 결과는 safety_stock_change_log에 batch_id로 묶어 기록한다. 중간 오류가 나면 아무것도 반영하지 않는다."""
    import math
    import uuid
    from datetime import date as _date

    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})
    if not has_menu_permission(user["login_id"], "safety-stock"):
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    items = data.get("items") or []
    if not items:
        return JSONResponse(status_code=400, content={"detail": "선택된 항목이 없습니다."})
    if len(items) > 1000:
        return JSONResponse(status_code=400, content={"detail": "한 번에 1000건까지만 적용할 수 있습니다."})

    try:
        start_v = str(data.get("start") or "")
        end_v = str(data.get("end") or "")
        d0 = _date.fromisoformat(start_v)
        d1 = _date.fromisoformat(end_v)
        factor_v = float(data.get("factor"))
        min_v = max(0, int(data.get("min_qty")))
        max_down = int(data.get("max_down_pct") or 0)
    except (ValueError, TypeError):
        return JSONResponse(status_code=400, content={"detail": "조회 조건 값이 올바르지 않습니다."})
    if d0 > d1 or factor_v <= 0 or factor_v > 10 or max_down < 0 or max_down > 100:
        return JSONResponse(status_code=400, content={"detail": "조회 조건 값이 올바르지 않습니다."})
    moq_mode_v = data.get("moq_mode")
    if moq_mode_v not in ("show", "round", "floor"):
        moq_mode_v = "show"

    live_rows = _compute_safety_recommendations(start_v, end_v, factor_v, min_v, moq_mode_v)
    live = {}
    for r in live_rows:
        live.setdefault((r["branch_name"], r["item_code"] or ""), []).append(r)

    skipped = []
    changes = []
    for it in items:
        key = str(it.get("key") or "")
        if "||" not in key:
            skipped.append({"key": key, "reason": "선택 값이 올바르지 않음"})
            continue
        branch, code = key.split("||", 1)
        lst = live.get((branch, code))
        if not lst:
            skipped.append({"key": key, "reason": "계산 대상에서 사라짐"})
            continue
        if len(lst) > 1:
            skipped.append({"key": key, "reason": "같은 품번의 안전재고 행이 여러 개라 수동 확인 필요"})
            continue
        r = lst[0]
        if r["recommended"] is None or r["status"] not in SAFETY_COMPARE_APPLY_STATUSES:
            skipped.append({"key": key, "reason": "변경 대상이 아님(" + str(r["status"]) + ")"})
            continue
        try:
            cur_client = int(it.get("cur"))
            rec_client = int(it.get("rec"))
        except (ValueError, TypeError):
            skipped.append({"key": key, "reason": "화면 값이 올바르지 않음"})
            continue
        if cur_client != r["current"] or rec_client != r["recommended"]:
            skipped.append({"key": key, "reason": "화면을 본 뒤 값이 바뀜(새로고침 후 다시 선택)"})
            continue
        cur = r["current"]
        rec = r["recommended"]
        new_qty = rec
        note = ""
        if rec < cur and max_down > 0:
            floor_v = math.ceil(cur * (100 - max_down) / 100)
            if new_qty < floor_v:
                new_qty = floor_v
                note = "하향 " + str(max_down) + "% 제한 적용(추천 " + str(rec) + ")"
        if new_qty == cur:
            skipped.append({"key": key, "reason": "변경 없음"})
            continue
        if r["status"] == "신규 후보":
            ctype = "신규"
        elif new_qty > cur:
            ctype = "상향"
        else:
            ctype = "하향"
        changes.append({
            "id": r["id"], "branch": r["branch_name"], "item_name": r["item_name"] or "",
            "code": r["item_code"] or "", "cur": cur, "rec": rec, "new": new_qty,
            "ctype": ctype, "min_used": r["min_used"], "note": note,
        })

    if not changes:
        return JSONResponse(content={
            "status": "ok", "batch_id": "-", "applied": 0, "applied_up": 0, "applied_down": 0,
            "applied_new": 0, "skipped": skipped
        })

    now_ss = datetime.now().isoformat()
    kst = str(_kst_now())[:19]
    batch_id = kst.replace("-", "").replace(":", "").replace(" ", "-") + "-" + uuid.uuid4().hex[:6]

    conn = get_conn()
    try:
        for c in changes:
            if c["id"]:
                conn.execute(
                    "UPDATE safety_stock SET qty=?, safety_qty=?, updated_at=? WHERE id=?",
                    (c["new"], c["new"], now_ss, c["id"])
                )
            else:
                conn.execute("""
                    INSERT INTO safety_stock (branch_name, item_name, item_code, qty, safety_qty, updated_at)
                    VALUES (?, ?, ?, ?, ?, ?)
                    ON CONFLICT (branch_name, item_name) DO UPDATE SET
                        item_code=excluded.item_code, qty=excluded.qty,
                        safety_qty=excluded.safety_qty, updated_at=excluded.updated_at
                """, (c["branch"], c["item_name"], c["code"], c["new"], c["new"], now_ss))
            conn.execute("""
                INSERT INTO safety_stock_change_log
                    (batch_id, applied_at, applied_by, branch_name, item_name, item_code,
                     old_qty, new_qty, recommended_qty, change_type, period_start, period_end,
                     factor, min_used, moq_mode, note)
                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """, (batch_id, kst, user["login_id"], c["branch"], c["item_name"], c["code"],
                  c["cur"], c["new"], c["rec"], c["ctype"], start_v, end_v,
                  factor_v, c["min_used"], moq_mode_v, c["note"] or None))
        conn.commit()
    except Exception as e:
        conn.close()
        return JSONResponse(status_code=500, content={"detail": "적용 실패(변경 없음): " + str(e)})
    conn.close()

    return JSONResponse(content={
        "status": "ok", "batch_id": batch_id, "applied": len(changes),
        "applied_up": sum(1 for c in changes if c["ctype"] == "상향"),
        "applied_down": sum(1 for c in changes if c["ctype"] == "하향"),
        "applied_new": sum(1 for c in changes if c["ctype"] == "신규"),
        "skipped": skipped
    })


@app.get("/master/purchase-order/safety-stock/compare/export")
async def safety_stock_compare_export(
    session_token: str = Cookie(default=None),
    start: str = "",
    end: str = "",
    factor: str = "1.05",
    min_qty: str = "1",
    filter_branch: str = "",
    filter_status: str = "",
    search_item: str = "",
    sort: str = "name",
    moq_mode: str = "show"
):
    """판매 기반 비교 결과를 엑셀로 내려받는다(화면과 같은 조회·필터 조건, 건수 제한 없음)."""
    from io import BytesIO
    from urllib.parse import quote
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter

    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "safety-stock"):
        return RedirectResponse(url="/master", status_code=303)

    res = _safety_compare_load(start, end, factor, min_qty, moq_mode, filter_branch, filter_status, search_item, sort)
    if res is None:
        return JSONResponse(status_code=404, content={"detail": "판매내역 데이터가 없습니다."})

    def _txt(v):
        s = "" if v is None else str(v)
        return (" " + s) if s.startswith("=") else s

    head_fill = PatternFill("solid", fgColor="1E2761")
    head_font = Font(bold=True, color="FFFFFF")

    wb = Workbook()
    ws = wb.active
    ws.title = "비교"
    headers = ["지점", "상품명", "품번", "리드타임", "기간 판매", "일평균", "MOQ", "최소값", "최소값 구분",
               "현재", "추천", "발주 시 수량", "증감", "상태"]
    ws.append(headers)
    for c in ws[1]:
        c.fill = head_fill
        c.font = head_font
        c.alignment = Alignment(horizontal="center", vertical="center")

    for r in res["rows"]:
        has_rec = r["recommended"] is not None
        min_val = r["min_used"] if has_rec else None
        min_kind = ("상품별" if r["min_custom"] else "공통") if has_rec else ""
        ws.append([
            _txt(r["branch_name"]), _txt(r["item_name"]), _txt(r["item_code"]),
            r["lead_time"] or None, r["sold"], round(r["avg_daily"], 4), r["moq"],
            min_val, min_kind, r["current"], r["recommended"], r["order_qty"], r["diff"], r["status"],
        ])
    for row in ws.iter_rows(min_row=2, min_col=6, max_col=6):
        for c in row:
            c.number_format = "0.00"
    widths = [14, 36, 16, 10, 10, 10, 8, 8, 12, 8, 8, 12, 8, 16]
    for i, w in enumerate(widths, start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = ws.dimensions

    moq_labels = {"show": "표시만 (추천은 그대로)", "round": "추천을 MOQ 배수로 올림", "floor": "추천 최소값을 MOQ로"}
    ws2 = wb.create_sheet("조회 조건")
    info = [
        ("시작일", res["start_v"]),
        ("종료일", res["end_v"]),
        ("적용 일수", res["days"]),
        ("안전계수", res["factor_v"]),
        ("공통 최소값", res["min_v"]),
        ("MOQ 반영", moq_labels.get(res["moq_mode_v"], res["moq_mode_v"])),
        ("지점 필터", filter_branch or "전체"),
        ("상태 필터", filter_status or "전체"),
        ("검색어", search_item or ""),
        ("정렬", "변화 큰 순" if sort == "diff" else "지점·상품명"),
        ("내려받은 행 수", len(res["rows"])),
        ("계산 대상 현재 합계(전체 조건)", res["cur_total"]),
        ("추천 합계(전체 조건)", res["rec_total"]),
        ("생성 시각(KST)", str(_kst_now())[:19]),
        ("", ""),
        ("[상태별 건수 - 필터 적용 전 전체]", ""),
    ]
    for s in SAFETY_COMPARE_STATUSES:
        info.append((s, res["counts"].get(s, 0)))
    for k, v in info:
        ws2.append([k, v])
    ws2.column_dimensions["A"].width = 34
    ws2.column_dimensions["B"].width = 30

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    fname = f"안전재고_판매기반비교_{res['start_v']}_{res['end_v']}.xlsx"
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f"attachment; filename*=UTF-8''{quote(fname)}"}
    )


@app.get("/master/purchase-order/safety-stock", response_class=HTMLResponse)
async def safety_stock_page(
    session_token: str = Cookie(default=None),
    search_item: str = "",
    filter_branch: str = "",
    sort_by: str = "item_name",
    sort_dir: str = "asc"
):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "safety-stock"):
        return RedirectResponse(url="/master", status_code=303)

    allowed_sort_cols = {"item_name", "branch_name", "qty", "updated_at"}
    if sort_by not in allowed_sort_cols:
        sort_by = "item_name"
    sort_dir_sql = "DESC" if sort_dir == "desc" else "ASC"

    conn = get_conn()
    query = "SELECT * FROM safety_stock WHERE 1=1"
    params: list = []
    if search_item:
        query += " AND (item_name LIKE ? OR item_code LIKE ?)"
        params.append(f"%{search_item}%")
        params.append(f"%{search_item}%")
    if filter_branch:
        query += " AND branch_name = ?"
        params.append(filter_branch)
    query += f" ORDER BY {sort_by} {sort_dir_sql} LIMIT 300"
    rows = conn.execute(query, params).fetchall()

    existing_rows = conn.execute(
        "SELECT DISTINCT branch_name, item_name, item_code FROM safety_stock ORDER BY branch_name, item_name LIMIT 5000"
    ).fetchall()
    conn.close()

    branches = get_branches(branch_type='branch')

    branch_filter_options = '<option value="">전체 지점</option>'
    for b in branches:
        sel = "selected" if filter_branch == b["branch_name"] else ""
        branch_filter_options += f'<option value="{b["branch_name"]}" {sel}>{b["branch_name"]}</option>'

    branch_select_options = '<option value="">지점 선택</option>'
    for b in branches:
        branch_select_options += f'<option value="{b["branch_name"]}">{b["branch_name"]}</option>'

    existing_by_branch: Dict[str, list] = {}
    for r in existing_rows:
        existing_by_branch.setdefault(r["branch_name"], []).append(
            {"name": r["item_name"], "code": r["item_code"] or ""}
        )
    existing_by_branch_json = json.dumps(existing_by_branch, ensure_ascii=False)

    rows_html = ""
    if not rows:
        rows_html = '<tr><td colspan="7" style="text-align:center;padding:20px;color:#888;">등록된 안전재고가 없습니다.</td></tr>'
    else:
        for r in rows:
            updated_display = (r["updated_at"] or "-")[:16] if r["updated_at"] else "-"
            rows_html += f"""
            <tr>
              <td style="text-align:center;"><input type="checkbox" name="ss_ids" value="{r['id']}" class="ss-check" style="width:16px;height:16px;"></td>
              <td>{r['branch_name'] or ''}</td>
              <td>{r['item_name'] or ''}</td>
              <td>{r['item_code'] or ''}</td>
              <td><input type="number" class="ss-qty" data-id="{r['id']}" value="{r['qty'] or 0}"></td>
              <td style="font-size:11px;color:#888;">{updated_display}</td>
              <td><button class="btn" style="font-size:12px;padding:6px 12px;" onclick="saveSsRow({r['id']})">저장</button></td>
            </tr>
            """

    content = f"""
    {SAFETY_STOCK_EXTRA_CSS}
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">
      <a href="/master/purchase-tracking" style="color:#1E2761;">← 발주 주기 트래킹</a>
      <h2>🎯 안전재고 관리</h2>
      <a href="/master/purchase-order/safety-stock/compare" style="margin-left:auto;padding:8px 14px;background:#8B5CF6;color:white;border-radius:8px;font-size:13px;text-decoration:none;">📊 판매 기반 비교</a>
    </div>

    <div class="card" style="background:#EFF6FF;border:1px solid #93C5FD;">
      <p style="font-size:13px;color:#1E40AF;">지점×상품별 안전재고 수량을 관리합니다. 발주서 자동생성 시 "현재고 &lt; 안전재고"인 상품이 발주 대상이 되며, 발주수량은 안전재고 수량 그대로 산정됩니다.</p>
    </div>

    <div class="card">
      <h3 style="margin-bottom:8px;">새 안전재고 등록</h3>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
        <select id="ssBranch" style="flex:1;min-width:120px;" onchange="ssBranchChanged()">{branch_select_options}</select>
        <select id="ssItemSelect" style="flex:2;min-width:180px;" disabled onchange="ssItemSelectChanged()">
          <option value="">지점을 먼저 선택하세요</option>
        </select>
        <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:#555;white-space:nowrap;">
          <input type="checkbox" id="ssManualMode" onchange="ssToggleManualMode()"> 새 상품 직접입력
        </label>
        <input type="text" id="ssItemNameManual" placeholder="상품명 직접입력" style="flex:2;min-width:160px;display:none;">
        <input type="number" id="ssQty" placeholder="안전재고 수량" style="flex:1;min-width:120px;">
        <button class="btn" type="button" onclick="addSsItem()">추가</button>
      </div>
      <div id="ssAddResult" style="margin-top:8px;font-size:13px;"></div>
    </div>

    <div class="card ss-upload-box">
      <h3 style="margin-bottom:8px;">엑셀 업로드 (안전재고 일괄 등록/갱신)</h3>
      <p style="font-size:12px;color:#1E40AF;margin-bottom:8px;">
        헤더 2행 형식(1행 제목, 2행 컬럼명, 3행부터 데이터). 컬럼 위치: <b>B=지점 / D=상품명 / E=품번 / J=지점설정재고(발주 기준)</b><br>
        (지점+상품명 기준으로 이미 있으면 덮어씁니다.)
      </p>
      <input type="file" id="ssExcelFile" accept=".xlsx,.xls">
      <button class="btn" type="button" onclick="uploadSsExcel()">업로드</button>
      <div id="ssUploadResult" style="margin-top:8px;font-size:13px;"></div>
    </div>

    <div class="card">
      <form method="get" action="/master/purchase-order/safety-stock" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px;">
        <input name="search_item" value="{search_item}" placeholder="상품명/품번 검색" style="flex:2;min-width:180px;">
        <select name="filter_branch" style="flex:1;min-width:120px;">{branch_filter_options}</select>
        <button class="btn" type="submit">검색</button>
        <a href="/master/purchase-order/safety-stock" style="padding:10px 14px;background:#eee;border-radius:8px;font-size:13px;text-decoration:none;color:#555;">초기화</a>
      </form>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;flex-wrap:wrap;gap:8px;">
        <p style="font-size:13px;color:#888;margin:0;">{len(rows)}건 (최대 300건까지 표시)</p>
        <div style="display:flex;gap:8px;">
          <button type="button" class="btn" id="ssSelectAllBtn" style="background:#64748B;font-size:12px;padding:6px 12px;">전체선택</button>
          <button type="button" class="btn btn-red" id="ssDeleteSelectedBtn" style="font-size:12px;padding:6px 12px;">선택 삭제</button>
          <button type="button" class="btn btn-red" id="ssDeleteAllBtn" style="font-size:12px;padding:6px 12px;">전체 삭제</button>
        </div>
      </div>
      <table class="ss-table">
        <thead><tr>
          <th style="width:36px;text-align:center;"><input type="checkbox" id="ssAllCheck" style="width:16px;height:16px;"></th>
          <th style="cursor:pointer;" onclick="sortSs('branch_name')">지점 {'▲' if sort_by=='branch_name' and sort_dir=='asc' else ('▼' if sort_by=='branch_name' else '')}</th>
          <th style="cursor:pointer;" onclick="sortSs('item_name')">상품명 {'▲' if sort_by=='item_name' and sort_dir=='asc' else ('▼' if sort_by=='item_name' else '')}</th>
          <th>품번</th>
          <th style="cursor:pointer;" onclick="sortSs('qty')">안전재고수량 {'▲' if sort_by=='qty' and sort_dir=='asc' else ('▼' if sort_by=='qty' else '')}</th>
          <th style="cursor:pointer;" onclick="sortSs('updated_at')">수정일시 {'▲' if sort_by=='updated_at' and sort_dir=='asc' else ('▼' if sort_by=='updated_at' else '')}</th>
          <th></th>
        </tr></thead>
        <tbody>{rows_html}</tbody>
      </table>
    </div>

    <script>
      const EXISTING_BY_BRANCH = {existing_by_branch_json};
      let ssSelectedItem = null;

      function sortSs(col) {{
        const params = new URLSearchParams(window.location.search);
        const curSort = params.get('sort_by') || 'item_name';
        const curDir = params.get('sort_dir') || 'asc';
        const newDir = (curSort === col && curDir === 'asc') ? 'desc' : 'asc';
        params.set('sort_by', col);
        params.set('sort_dir', newDir);
        window.location.search = params.toString();
      }}

      function ssBranchChanged() {{
        const branch = document.getElementById('ssBranch').value;
        const selectEl = document.getElementById('ssItemSelect');
        ssSelectedItem = null;
        if (!branch) {{
          selectEl.disabled = true;
          selectEl.innerHTML = '<option value="">지점을 먼저 선택하세요</option>';
          return;
        }}
        const items = EXISTING_BY_BRANCH[branch] || [];
        selectEl.disabled = false;
        if (items.length === 0) {{
          selectEl.innerHTML = '<option value="">이 지점에 등록된 상품 없음 (직접입력 사용)</option>';
        }} else {{
          selectEl.innerHTML = '<option value="">상품 선택</option>' +
            items.map((p, idx) => '<option value="' + idx + '">' + p.name + (p.code ? ' (' + p.code + ')' : '') + '</option>').join('');
        }}
      }}

      function ssItemSelectChanged() {{
        const branch = document.getElementById('ssBranch').value;
        const idx = document.getElementById('ssItemSelect').value;
        if (idx === '') {{ ssSelectedItem = null; return; }}
        const items = EXISTING_BY_BRANCH[branch] || [];
        ssSelectedItem = items[parseInt(idx)] || null;
      }}

      function ssToggleManualMode() {{
        const manual = document.getElementById('ssManualMode').checked;
        document.getElementById('ssItemSelect').style.display = manual ? 'none' : '';
        document.getElementById('ssItemNameManual').style.display = manual ? '' : 'none';
        ssSelectedItem = null;
      }}

      async function addSsItem() {{
        const branch = document.getElementById('ssBranch').value;
        const qty = parseInt(document.getElementById('ssQty').value);
        const manual = document.getElementById('ssManualMode').checked;

        let itemName = '';
        let itemCode = '';
        if (manual) {{
          itemName = document.getElementById('ssItemNameManual').value.trim();
        }} else if (ssSelectedItem) {{
          itemName = ssSelectedItem.name;
          itemCode = ssSelectedItem.code;
        }}

        if (!branch || !itemName || isNaN(qty)) {{
          alert('지점, 상품(선택 또는 직접입력), 안전재고수량을 입력하세요.');
          return;
        }}
        const res = await fetch('/master/purchase-order/safety-stock/save', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ branch_name: branch, item_name: itemName, item_code: itemCode, qty: qty }})
        }});
        if (res.ok) {{ location.reload(); }} else {{
          const err = await res.json();
          document.getElementById('ssAddResult').innerText = '오류: ' + (err.detail || '추가 실패');
        }}
      }}

      async function saveSsRow(id) {{
        const qtyEl = document.querySelector('.ss-qty[data-id="' + id + '"]');
        const res = await fetch('/master/purchase-order/safety-stock/save', {{
          method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ id: id, qty: parseInt(qtyEl.value) || 0 }})
        }});
        if (res.ok) {{ alert('저장되었습니다.'); }} else {{ alert('저장 실패'); }}
      }}

      async function uploadSsExcel() {{
        const fileEl = document.getElementById('ssExcelFile');
        if (!fileEl.files.length) {{ alert('파일을 선택하세요.'); return; }}
        const formData = new FormData();
        formData.append('file', fileEl.files[0]);
        document.getElementById('ssUploadResult').innerText = '업로드 중...';
        const res = await fetch('/master/purchase-order/safety-stock/upload', {{
          method: 'POST', body: formData
        }});
        const data = await res.json();
        if (res.ok) {{
          document.getElementById('ssUploadResult').innerText = '완료: ' + data.inserted + '건 등록/갱신 (건너뜀: ' + data.skipped + '건)';
          setTimeout(() => location.reload(), 1200);
        }} else {{
          document.getElementById('ssUploadResult').innerText = '오류: ' + (data.detail || '업로드 실패');
        }}
      }}

      (function() {{
        const allCheck = document.getElementById('ssAllCheck');
        const selectBtn = document.getElementById('ssSelectAllBtn');
        const deleteSelectedBtn = document.getElementById('ssDeleteSelectedBtn');
        const deleteAllBtn = document.getElementById('ssDeleteAllBtn');

        function applyAll(checked) {{
          document.querySelectorAll('.ss-check').forEach(function(c) {{ c.checked = checked; }});
          if (allCheck) allCheck.checked = checked;
        }}

        if (allCheck) {{ allCheck.addEventListener('click', function() {{ applyAll(allCheck.checked); }}); }}
        if (selectBtn) {{
          selectBtn.addEventListener('click', function() {{
            const next = !(allCheck && allCheck.checked);
            applyAll(next);
          }});
        }}

        if (deleteSelectedBtn) {{
          deleteSelectedBtn.addEventListener('click', async function() {{
            const checked = Array.from(document.querySelectorAll('.ss-check:checked')).map(c => parseInt(c.value));
            if (checked.length === 0) {{ alert('삭제할 항목을 선택하세요.'); return; }}
            if (!confirm(checked.length + '건을 삭제합니다. 되돌릴 수 없습니다. 계속할까요?')) return;
            const res = await fetch('/master/purchase-order/safety-stock/delete', {{
              method: 'POST', headers: {{ 'Content-Type': 'application/json' }},
              body: JSON.stringify({{ ids: checked }})
            }});
            if (res.ok) {{ location.reload(); }} else {{
              const err = await res.json();
              alert('오류: ' + (err.detail || '삭제 실패'));
            }}
          }});
        }}

        if (deleteAllBtn) {{
          deleteAllBtn.addEventListener('click', async function() {{
            if (!confirm('현재 검색/필터 결과와 무관하게 전체 안전재고 데이터를 삭제합니다. 되돌릴 수 없습니다. 계속할까요?')) return;
            const res = await fetch('/master/purchase-order/safety-stock/delete-all', {{ method: 'POST' }});
            if (res.ok) {{ location.reload(); }} else {{ alert('전체 삭제 실패'); }}
          }});
        }}
      }})();
    </script>
    """
    return HTMLResponse(content=render_page(content, user, "master"))


@app.post("/master/purchase-order/safety-stock/save")
async def safety_stock_save(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    row_id = data.get("id")
    branch_name = (data.get("branch_name") or "").strip()
    item_name = (data.get("item_name") or "").strip()
    item_code = (data.get("item_code") or "").strip()
    qty = data.get("qty", 0)

    now = datetime.now().isoformat()
    conn = get_conn()
    if row_id:
        conn.execute(
            "UPDATE safety_stock SET qty=?, updated_at=? WHERE id=?",
            (qty, now, row_id)
        )
    else:
        if not branch_name or not item_name:
            conn.close()
            return JSONResponse(status_code=400, content={"detail": "지점과 상품명을 입력하세요."})
        conn.execute("""
            INSERT INTO safety_stock (branch_name, item_name, item_code, qty, safety_qty, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT (branch_name, item_name) DO UPDATE SET
                item_code=excluded.item_code, qty=excluded.qty,
                safety_qty=excluded.safety_qty, updated_at=excluded.updated_at
        """, (branch_name, item_name, item_code, qty, qty, now))
    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok"})


@app.post("/master/purchase-order/safety-stock/upload")
async def safety_stock_upload(request: Request, session_token: str = Cookie(default=None)):
    """고정 컬럼 위치 기반 파싱: B=지점(idx1) D=상품명(idx3) E=품번(idx4) J=지점설정재고(idx9)
    1행=제목, 2행=헤더, 3행부터 데이터."""
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    form = await request.form()
    file = form.get("file")
    if not file:
        return JSONResponse(status_code=400, content={"detail": "파일이 없습니다."})

    import openpyxl
    from io import BytesIO
    raw = await file.read()
    wb = openpyxl.load_workbook(BytesIO(raw), data_only=True)
    ws = wb.active

    COL_BRANCH = 1   # B
    COL_ITEM_NAME = 3   # D
    COL_ITEM_CODE = 4   # E
    COL_QTY = 9   # J

    now = datetime.now().isoformat()
    conn = get_conn()
    inserted = 0
    skipped = 0

    for row in ws.iter_rows(min_row=3, values_only=True):
        if not row or len(row) <= COL_QTY:
            skipped += 1
            continue

        branch_name = str(row[COL_BRANCH] or "").strip()
        item_name = str(row[COL_ITEM_NAME] or "").strip()
        if not branch_name or not item_name:
            skipped += 1
            continue

        item_code = str(row[COL_ITEM_CODE] or "").strip()
        qty_raw = row[COL_QTY]
        try:
            qty = int(float(qty_raw)) if qty_raw not in (None, "") else 0
        except (ValueError, TypeError):
            skipped += 1
            continue

        conn.execute("""
            INSERT INTO safety_stock (branch_name, item_name, item_code, qty, safety_qty, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT (branch_name, item_name) DO UPDATE SET
                item_code=excluded.item_code, qty=excluded.qty,
                safety_qty=excluded.safety_qty, updated_at=excluded.updated_at
        """, (branch_name, item_name, item_code, qty, qty, now))
        inserted += 1

    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok", "inserted": inserted, "skipped": skipped})


@app.post("/master/purchase-order/safety-stock/delete")
async def safety_stock_delete(request: Request, session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    data = await request.json()
    ids = data.get("ids", [])
    if not ids:
        return JSONResponse(status_code=400, content={"detail": "삭제할 항목이 없습니다."})

    conn = get_conn()
    conn.execute(
        f"DELETE FROM safety_stock WHERE id IN ({','.join('?' for _ in ids)})",
        [int(i) for i in ids]
    )
    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok", "deleted_count": len(ids)})


@app.post("/master/purchase-order/safety-stock/delete-all")
async def safety_stock_delete_all(session_token: str = Cookie(default=None)):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return JSONResponse(status_code=403, content={"detail": "권한이 없습니다."})

    conn = get_conn()
    conn.execute("DELETE FROM safety_stock")
    conn.commit()
    conn.close()
    return JSONResponse(content={"status": "ok"})

# ============================================================
# 크론/기능 실패 알림 대상 채널 (테스트 채널, admin_hs)
# ============================================================
CRON_FAILURE_TEAMS_CHANNEL = "admin_hs"
CRON_FAILURE_EMAIL_TO = "hs.yu@petdoc.co.kr"


def send_email(to_addr: str, subject: str, body: str,
               attachment_bytes: bytes = None, attachment_filename: str = None) -> tuple:
    """Gmail SMTP로 이메일 발송. 성공 시 (True, ''), 실패 시 (False, 에러메시지) 반환.
    첨부파일이 있으면 attachment_bytes(bytes)와 attachment_filename을 함께 전달."""
    import smtplib
    from email.mime.multipart import MIMEMultipart
    from email.mime.text import MIMEText
    from email.mime.base import MIMEBase
    from email import encoders

    sender = os.environ.get("GMAIL_SENDER_ADDRESS", "")
    app_password = os.environ.get("GMAIL_APP_PASSWORD", "")

    if not sender or not app_password:
        return False, "GMAIL_SENDER_ADDRESS 또는 GMAIL_APP_PASSWORD 환경변수가 설정되지 않았습니다."

    try:
        msg = MIMEMultipart()
        msg["From"] = sender
        msg["To"] = to_addr
        msg["Subject"] = subject
        msg.attach(MIMEText(body, "plain", "utf-8"))

        if attachment_bytes and attachment_filename:
            part = MIMEBase("application", "octet-stream")
            part.set_payload(attachment_bytes)
            encoders.encode_base64(part)
            from email.header import Header
            encoded_filename = Header(attachment_filename, "utf-8").encode()
            part.add_header("Content-Disposition", f'attachment; filename="{encoded_filename}"')
            msg.attach(part)

        with smtplib.SMTP("smtp.gmail.com", 587) as server:
            server.starttls()
            server.login(sender, app_password)
            server.sendmail(sender, [to_addr], msg.as_string())

        return True, ""
    except Exception as e:
        return False, str(e)[:300]


def report_cron_failure(cron_name: str, error_detail: str):
    """크론/주요기능 실패 시 공통 처리: DB 기록 + Teams(admin_hs) 발송 + 이메일 발송.
    이 함수 자체는 예외를 던지지 않음 (알림 발송 실패가 원본 크론의 실패 처리를 방해하지 않도록 방어)."""
    now = datetime.now().isoformat()

    try:
        conn = get_conn()
        conn.execute(
            "INSERT INTO cron_failure_log (cron_name, error_detail, occurred_at) VALUES (?, ?, ?)",
            (cron_name, error_detail, now)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        print(f"[report_cron_failure] DB 기록 실패: {str(e)[:200]}")

    try:
        title = f"⚠️ 크론/기능 실패: {cron_name}"
        body = f"발생 시각: {now}\n\n오류 내용:\n{error_detail[:1000]}"
        send_teams_notification(
            CRON_FAILURE_TEAMS_CHANNEL, title, body,
            sent_by="system_cron_failure"
        )
    except Exception as e:
        print(f"[report_cron_failure] Teams 발송 실패: {str(e)[:200]}")

    try:
        subject = f"[재고관리시스템] 크론/기능 실패 알림 - {cron_name}"
        body = f"발생 시각: {now}\n\n실패한 작업: {cron_name}\n\n오류 상세:\n{error_detail[:2000]}"
        send_email(CRON_FAILURE_EMAIL_TO, subject, body)
    except Exception as e:
        print(f"[report_cron_failure] 이메일 발송 실패: {str(e)[:200]}")


@app.get("/master/cron-failure-log", response_class=HTMLResponse)
async def cron_failure_log_page(
    session_token: str = Cookie(default=None),
    filter_cron: str = "",
    date_filter: str = ""
):
    user = get_session(session_token)
    if not user or user["role"] != "master":
        return RedirectResponse(url="/login", status_code=303)
    if not has_menu_permission(user["login_id"], "cron-failure-log"):
        return RedirectResponse(url="/master", status_code=303)

    conn = get_conn()
    query = "SELECT * FROM cron_failure_log WHERE 1=1"
    params: list = []
    if filter_cron:
        query += " AND cron_name = ?"
        params.append(filter_cron)
    if date_filter:
        query += " AND occurred_at LIKE ?"
        params.append(f"{date_filter}%")
    query += " ORDER BY occurred_at DESC LIMIT 300"
    logs = conn.execute(query, params).fetchall()

    all_cron_names = conn.execute(
        "SELECT DISTINCT cron_name FROM cron_failure_log ORDER BY cron_name"
    ).fetchall()
    conn.close()

    cron_options = '<option value="">전체</option>'
    for c in all_cron_names:
        sel = "selected" if filter_cron == c["cron_name"] else ""
        cron_options += f'<option value="{c["cron_name"]}" {sel}>{c["cron_name"]}</option>'

    rows_html = ""
    if not logs:
        rows_html = '<tr><td colspan="3" style="text-align:center;padding:20px;color:#888;">기록된 실패 이력이 없습니다. (정상)</td></tr>'
    else:
        for lg in logs:
            occurred_display = (lg["occurred_at"] or "-")[:19] if lg["occurred_at"] else "-"
            error_preview = (lg["error_detail"] or "")[:150]
            rows_html += f"""
            <tr>
              <td style="font-size:12px;">{occurred_display}</td>
              <td><b>{lg['cron_name']}</b></td>
              <td style="font-size:12px;color:#EF4444;">{error_preview}</td>
            </tr>
            """

    content = f"""
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">
      <a href="/master" style="color:#1E2761;">← 마스터</a>
      <h2>🚨 크론/기능 실패 이력</h2>
    </div>
    <div class="card" style="background:#EFF6FF;border:1px solid #93C5FD;">
      <p style="font-size:13px;color:#1E40AF;">모든 cron 작업 및 주요 기능 실패 시 이 목록에 기록되며, 동시에 Teams(테스트채널)와 이메일로 알림이 발송됩니다.</p>
    </div>
    <div class="card">
      <form method="get" action="/master/cron-failure-log" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;">
        <div style="flex:1;min-width:160px;">
          <label style="font-size:12px;color:#888;">작업 종류</label>
          <select name="filter_cron" style="margin-top:4px;">{cron_options}</select>
        </div>
        <div style="flex:1;min-width:140px;">
          <label style="font-size:12px;color:#888;">날짜</label>
          <input name="date_filter" type="date" value="{date_filter}" style="margin-top:4px;">
        </div>
        <button class="btn" type="submit">검색</button>
        <a href="/master/cron-failure-log" style="padding:10px 14px;background:#eee;border-radius:8px;font-size:13px;text-decoration:none;color:#555;">초기화</a>
      </form>
    </div>
    <div class="card">
      <p style="font-size:13px;color:#888;margin-bottom:12px;">{len(logs)}건 (최근 300건까지 표시)</p>
      <table>
        <thead><tr><th>발생시각</th><th>작업</th><th>오류 내용</th></tr></thead>
        <tbody>{rows_html}</tbody>
      </table>
    </div>
    """
    return HTMLResponse(content=render_page(content, user, "master"))



# ══════════════════════════════════════════════════════════
# 마스터 > 크론 관리 — 자동 작업 상태 확인 + 외부 데이터 수신 수동 실행
# 스케줄 자체는 외부 스케줄러(cron-job.org 등)가 담당. 이 페이지는
# "지금 데이터가 들어오고 있는가"를 보여주고 필요 시 즉시 재수신한다.
# ══════════════════════════════════════════════════════════

def _cron_job_enabled(job: str) -> bool:
    """system_settings 'cron_enabled:<job>' — 'off'일 때만 False. 미설정/조회 실패 시 True(기본 켜짐)."""
    try:
        conn = get_conn()
        row = conn.execute(
            "SELECT value FROM system_settings WHERE key=?", (f"cron_enabled:{job}",)
        ).fetchone()
        conn.close()
        return not (row and str(row["value"]).strip().lower() == "off")
    except Exception:
        return True


def _cron_source_default(job: str) -> str:
    """외부 데이터 수신 주소 기본값 (코드/환경변수)."""
    if job == "sync-sales-records":
        return SALES_S3_BASE_URL
    if job == "sync-payment-records":
        return PAYMENT_S3_BASE_URL
    if job == "sync-raw-inventory":
        return "https://petdoc-ubiplus.s3.ap-northeast-2.amazonaws.com/stock/유비플러스_재고현황.csv"
    if job == "sync-purchase-records":
        return os.environ.get("PURCHASE_RECORDS_CSV_URL", "")
    return ""


def _cron_source_custom(job: str) -> str:
    """system_settings 'cron_src:<job>'에 저장된 사용자 지정 주소 (없으면 '')."""
    try:
        conn = get_conn()
        row = conn.execute(
            "SELECT value FROM system_settings WHERE key=?", (f"cron_src:{job}",)
        ).fetchone()
        conn.close()
        return str(row["value"]).strip() if row else ""
    except Exception:
        return ""


def _cron_source_url(job: str) -> str:
    """실제 사용할 수신 주소 — 사용자 지정 우선, 없으면 기본값."""
    return _cron_source_custom(job) or _cron_source_default(job)


